        if p.startswith("/final"):
            body=b"<html><head><title>F</title></head><body>final</body></html>"
        elif p.startswith("/red3"):
            body=b"<html><body>red3</body></html>"
        elif p.startswith("/err"):
            self.send_response(500); self.send_header("Content-Length","0"); self.end_headers(); return
        elif p.startswith("/gz"):
            body=gzip.compress(b"<html><body>gzipped</body></html>")
