            for part in [b"<html><bo", b"dy>chunked</bo", b"dy></html>"]:
                self.wfile.write(("%x\r\n"%len(part)).encode()+part+b"\r\n")
            self.wfile.write(b"0\r\n\r\n"); return
        elif p.startswith("/noct"):
            body=b"<html><body>noct</body></html>"
            self.send_response(200); self.send_header("Content-Length",str(len(body))); self.end_headers(); self.wfile.write(body); return
        else:
            body=b"<html><head><title>dump</title></head><body>ok</body></html>"
        self.send_response(200); self.send_header("Content-Type","text/html"); self.send_header("Content-Length",str(len(body))); self.end_headers(); self.wfile.write(body)
