    pub return_state: State,
    pub last_start_tag: Vec<u8>,
    appropriate_end_tag: Vec<u8>,
    buf: Vec<u8>,
    pub eof_emitted: bool,
}

impl Tokenizer {
    pub fn new(input: Vec<u8>) -> Tokenizer {
        Tokenizer {
            input,
            pos: 0,
            state: State::Data,
            return_state: State::Data,
            last_start_tag: Vec::new(),
            appropriate_end_tag: Vec::new(),
            buf: Vec::new(),
            eof_emitted: false,
        }
    }

    fn emit_eof(&mut self) -> Token {
        self.eof_emitted = true;
        Token::Eof
    }

    /// Perform one step of the tokenizer state machine. Returns a token if one is emitted.
    pub fn step(&mut self) -> Option<Token> {
        loop {
            let c = if self.pos < self.input.len() { Some(self.input[self.pos]) } else { None };
            let t = self.run_state(c);
            if let Some(t) = t {
                return Some(t);
            }
            if self.pos >= self.input.len() && c.is_none() {
                // avoid infinite loop at eof
                if self.eof_emitted {
                    return None;
                }
            }
        }
    }

    fn reconsume(&mut self, c: u8) {
        self.pos -= 1;
        let _ = c;
    }

    fn set_appropriate_end_tag(&mut self) {
        let mut t = self.last_start_tag.clone();
        if !t.is_empty() {
            t.insert(0, b'/');
        }
        self.appropriate_end_tag = t;
    }

    /// Run one state; returns Some(token) when a token is emitted.
    fn run_state(&mut self, c: Option<u8>) -> Option<Token> {
        match self.state {
            State::Data => self.st_data(c),
            State::Rcdata => self.st_rcdata(c),
            State::Rawtext => self.st_rawtext(c),
            State::ScriptData => self.st_script_data(c),
            State::Plaintext => self.st_plaintext(c),
            State::TagOpen => self.st_tag_open(c),
            State::EndTagOpen => self.st_end_tag_open(c),
            State::TagName => self.st_tag_name(c),
            State::RcdataLessThanSign => self.st_rcdata_lt(c),
            State::RcdataEndTagOpen => self.st_rcdata_end_open(c),
            State::RcdataEndTagName => self.st_rcdata_end_name(c),
            State::RawtextLessThanSign => self.st_rawtext_lt(c),
            State::RawtextEndTagOpen => self.st_rawtext_end_open(c),
            State::RawtextEndTagName => self.st_rawtext_end_name(c),
            State::ScriptDataLessThanSign => self.st_script_lt(c),
            State::ScriptDataEndTagOpen => self.st_script_end_open(c),
            State::ScriptDataEndTagName => self.st_script_end_name(c),
            State::ScriptDataEscapeStart => self.st_script_escape_start(c),
            State::ScriptDataEscapeStartDash => self.st_script_escape_start_dash(c),
            State::ScriptDataEscaped => self.st_script_escaped(c),
            State::ScriptDataEscapedDash => self.st_script_escaped_dash(c),
            State::ScriptDataEscapedDashDash => self.st_script_escaped_dash_dash(c),
            State::ScriptDataEscapedLessThanSign => self.st_script_escaped_lt(c),
            State::ScriptDataEscapedEndTagOpen => self.st_script_escaped_end_open(c),
            State::ScriptDataEscapedEndTagName => self.st_script_escaped_end_name(c),
            State::ScriptDataDoubleEscapeStart => self.st_script_double_escape_start(c),
            State::ScriptDataDoubleEscaped => self.st_script_double_escaped(c),
            State::ScriptDataDoubleEscapedDash => self.st_script_double_escaped_dash(c),
            State::ScriptDataDoubleEscapedDashDash => self.st_script_double_escaped_dash_dash(c),
            State::ScriptDataDoubleEscapedLessThanSign => self.st_script_double_escaped_lt(c),
            State::ScriptDataDoubleEscapeEnd => self.st_script_double_escape_end(c),
            State::ScriptDataDoubleEscapeEndDash => self.st_script_double_escape_end_dash(c),
            State::ScriptDataDoubleEscapeEndDashDash => self.st_script_double_escape_end_dash_dash(c),
            State::BeforeAttributeName => self.st_before_attr_name(c),
            State::AfterAttributeName => self.st_after_attr_name(c),
            State::BeforeAttributeValue => self.st_before_attr_value(c),
            State::AttributeValueDoubleQuoted => self.st_attr_value_dq(c),
            State::AttributeValueSingleQuoted => self.st_attr_value_sq(c),
            State::AttributeValueUnquoted => self.st_attr_value_uq(c),
            State::AfterAttributeValueQuoted => self.st_after_attr_value_quoted(c),
            State::SelfClosingStartTag => self.st_self_closing_start(c),
            State::BogusComment => self.st_bogus_comment(c),
            State::MarkupDeclarationOpen => self.st_markup_decl_open(c),
            State::CommentStart => self.st_comment_start(c),
            State::CommentStartDash => self.st_comment_start_dash(c),
            State::Comment => self.st_comment(c),
            State::CommentLessThanSign => self.st_comment_lt(c),
            State::CommentLessThanSignBang => self.st_comment_lt_bang(c),
            State::CommentLessThanSignBangDash => self.st_comment_lt_bang_dash(c),
            State::CommentLessThanSignBangDashDash => self.st_comment_lt_bang_dash_dash(c),
            State::CommentEndDash => self.st_comment_end_dash(c),
            State::CommentEnd => self.st_comment_end(c),
            State::CommentEndBang => self.st_comment_end_bang(c),
            State::Doctype => self.st_doctype(c),
            State::BeforeDoctypeName => self.st_before_doctype_name(c),
            State::DoctypeName => self.st_doctype_name(c),
            State::AfterDoctypeName => self.st_after_doctype_name(c),
            State::AfterDoctypePublicKeyword => self.st_after_doctype_public_keyword(c),
            State::BeforeDoctypePublicIdentifier => self.st_before_doctype_public_identifier(c),
            State::DoctypePublicIdentifierDoubleQuoted => self.st_doctype_pub_dq(c),
            State::DoctypePublicIdentifierSingleQuoted => self.st_doctype_pub_sq(c),
            State::AfterDoctypePublicIdentifier => self.st_after_doctype_public_identifier(c),
            State::BetweenDoctypePublicAndSystemIdentifier => {
                self.st_between_doctype_public_and_system(c)
            }
            State::AfterDoctypeSystemKeyword => self.st_after_doctype_system_keyword(c),
            State::BeforeDoctypeSystemIdentifier => self.st_before_doctype_system_identifier(c),
            State::DoctypeSystemIdentifierDoubleQuoted => self.st_doctype_sys_dq(c),
            State::DoctypeSystemIdentifierSingleQuoted => self.st_doctype_sys_sq(c),
            State::AfterDoctypeSystemIdentifier => self.st_after_doctype_system_identifier(c),
            State::BetweenDoctypeSystemAndSystemIdentifier => {
                self.st_between_doctype_system_and(c)
            }
            State::BogusDoctype => self.st_bogus_doctype(c),
            State::CdataSection => self.st_cdata_section(c),
            State::CdataSectionRightSquareBracket => self.st_cdata_rsb(c),
            State::CdataSectionDoubleRightSquareBracket => self.st_cdata_drsb(c),
        }
    }

    fn st_data(&mut self, c: Option<u8>) -> Option<Token> {
        match c {
            Some(b'&') => {
                self.state = State::Data;
                match self.consume_char_ref(true) {
                    Some((s, len)) => {
                        self.pos += len;
                        self.buf.extend_from_slice(s.as_bytes());
                        None
                    }
                    None => {
                        self.buf.push(b'&');
                        self.pos += 1;
                        None
                    }
                }
            }
            Some(b'<') => {
                self.pos += 1;
                self.state = State::TagOpen;
                self.return_state = State::Data;
                None
            }
            Some(0x00) => {
                self.pos += 1;
                None
            }
            Some(_) => {
                let start = self.pos;
                let mut end = start;
                while end < self.input.len() {
                    let b = self.input[end];
                    if b == b'&' || b == b'<' || b == 0x00 {
                        break;
                    }
                    end += 1;
                }
                self.buf.extend_from_slice(&self.input[start..end]);
                self.pos = end;
                None
            }
            None => {
                if !self.buf.is_empty() {
                    let s = std::mem::take(&mut self.buf);
                    return Some(Token::Character(s));
                }
                Some(self.emit_eof())
            }
        }
    }

    fn st_rcdata(&mut self, c: Option<u8>) -> Option<Token> {
        match c {
            Some(b'&') => match self.consume_char_ref(true) {
                Some((s, len)) => {
                    self.pos += len;
                    self.buf.extend_from_slice(s.as_bytes());
                    None
                }
                None => {
                    self.buf.push(b'&');
                    self.pos += 1;
                    None
                }
            },
            Some(b'<') => {
                self.pos += 1;
                self.state = State::RcdataLessThanSign;
                None
            }
            Some(0x00) => {
                self.pos += 1;
                self.buf.extend_from_slice("\u{FFFD}".as_bytes());
                None
            }
            Some(_) => {
                let start = self.pos;
                let mut end = start;
                while end < self.input.len() {
                    let b = self.input[end];
                    if b == b'&' || b == b'<' || b == 0x00 {
                        break;
                    }
                    end += 1;
                }
                self.buf.extend_from_slice(&self.input[start..end]);
                self.pos = end;
                None
            }
            None => {
                if !self.buf.is_empty() {
                    let s = std::mem::take(&mut self.buf);
