    fn st_tag_open(&mut self, c: Option<u8>) -> Option<Token> {
        match c {
            Some(b'!') => {
                self.pos += 1;
                self.state = State::MarkupDeclarationOpen;
                None
            }
            Some(b'/') => {
                self.pos += 1;
                self.state = State::EndTagOpen;
                None
            }
            Some(x) if is_alpha(x) => {
                self.state = State::TagName;
                self.last_start_tag.clear();
                None
            }
            Some(b'?') => {
                self.buf.clear();
                self.state = State::BogusComment;
                self.pos += 1;
                None
            }
            Some(x) if x == b'>' => {
                self.pos += 1;
                self.state = State::Data;
                self.buf.clear();
                Some(Token::Character(vec![b'<']))
            }
            Some(0x00) => {
                self.buf.clear();
                self.state = State::TagName;
                self.last_start_tag.clear();
                self.buf.push(0xFF);
                self.pos += 1;
                None
            }
            Some(_) => {
                self.buf.clear();
                self.state = State::Data;
                self.buf.push(b'<');
                Some(Token::Character(vec![b'<']))
            }
            None => {
                self.buf.clear();
                self.state = State::Data;
                Some(Token::Character(vec![b'<']))
            }
        }
    }

    fn st_end_tag_open(&mut self, c: Option<u8>) -> Option<Token> {
        match c {
            Some(x) if is_alpha(x) => {
                self.state = State::TagName;
                self.buf.clear();
                None
            }
            Some(b'>') => {
                self.pos += 1;
                self.state = State::Data;
                None
            }
            Some(0x00) => {
                self.state = State::BogusComment;
                None
            }
            Some(_) => {
                self.state = State::BogusComment;
                self.pos -= 1;
                None
            }
            None => {
                self.buf.push(b'<');
                self.buf.push(b'/');
                self.state = State::Data;
                Some(Token::Character(std::mem::take(&mut self.buf)))
            }
        }
    }

    fn st_tag_name(&mut self, c: Option<u8>) -> Option<Token> {
        match c {
            Some(x) if is_ws(x) => {
                self.pos += 1;
                self.state = State::BeforeAttributeName;
                None
            }
            Some(b'/') => {
                self.pos += 1;
                self.state = State::SelfClosingStartTag;
                None
            }
            Some(b'>') => {
                self.pos += 1;
                let name = std::mem::take(&mut self.buf);
                let lowered = to_lowercase(&name);
                self.last_start_tag = lowered.clone();
                self.state = State::Data;
                Some(Token::StartTag {
                    name: lowered,
                    attrs: Vec::new(),
                    self_closing: false,
                })
            }
            Some(0x00) => {
                self.buf.extend_from_slice("\u{FFFD}".as_bytes());
                self.pos += 1;
                None
            }
            Some(_) => {
                let start = self.pos;
                let mut end = start;
                while end < self.input.len() {
                    let b = self.input[end];
                    if is_ws(b) || b == b'/' || b == b'>' || b == 0x00 {
                        break;
                    }
                    end += 1;
                }
                self.buf.extend_from_slice(&self.input[start..end]);
                self.pos = end;
                None
            }
            None => {
                if !self.buf.is_empty() {
                    let name = std::mem::take(&mut self.buf);
                    let lowered = to_lowercase(&name);
                    self.last_start_tag = lowered.clone();
                    self.state = State::Data;
                    return Some(Token::StartTag {
                        name: lowered,
                        attrs: Vec::new(),
                        self_closing: false,
                    });
                }
                Some(self.emit_eof())
            }
        }
    }

    fn st_rcdata_lt(&mut self, c: Option<u8>) -> Option<Token> {
        match c {
            Some(b'/') => {
                self.pos += 1;
                self.state = State::RcdataEndTagOpen;
                self.buf.clear();
                None
            }
            _ => {
                self.buf.push(b'<');
                self.state = State::Rcdata;
                self.reconsume_if(c);
                None
            }
        }
    }

    fn reconsume_if(&mut self, c: Option<u8>) {
        if c.is_some() {
            self.pos -= 1;
        }
    }

    fn st_rcdata_end_open(&mut self, c: Option<u8>) -> Option<Token> {
        match c {
            Some(x) if is_alpha(x) => {
                self.pos += 1;
                self.state = State::RcdataEndTagName;
                self.buf.clear();
                self.reconsume_in_tag_name_mode();
                None
            }
            _ => {
                self.buf.clear();
                self.buf.push(b'<');
                self.buf.push(b'/');
                self.state = State::Rcdata;
                self.reconsume_if(c);
                None
            }
        }
    }

    fn reconsume_in_tag_name_mode(&mut self) {
        self.pos -= 1;
    }

    fn st_rcdata_end_name(&mut self, c: Option<u8>) -> Option<Token> {
        match c {
            Some(x) if is_ws(x) => {
                if self.name_matches_appropriate() {
                    self.pos += 1;
                    self.state = State::BeforeAttributeName;
                    None
                } else {
                    self.emit_as_chars_and_switch(State::Rcdata)
                }
            }
            Some(b'/') => {
                if self.name_matches_appropriate() {
                    self.pos += 1;
                    self.state = State::SelfClosingStartTag;
                    None
                } else {
                    self.emit_as_chars_and_switch(State::Rcdata)
                }
            }
            Some(b'>') => {
                if self.name_matches_appropriate() {
                    self.pos += 1;
                    let name = std::mem::take(&mut self.buf);
                    self.state = State::Data;
                    Some(Token::EndTag { name: to_lowercase(&name) })
                } else {
                    self.emit_as_chars_and_switch(State::Rcdata)
                }
            }
            Some(x) if is_alnum(x) => {
                self.buf.push(x);
                self.pos += 1;
                None
            }
            _ => {
                self.emit_as_chars_and_switch(State::Rcdata)
            }
        }
    }

    fn name_matches_appropriate(&self) -> bool {
        let name = to_lowercase(&self.buf);
        self.appropriate_end_tag == name
    }

    fn emit_as_chars_and_switch(&mut self, new_state: State) -> Option<Token> {
        let mut out = Vec::new();
        out.push(b'<');
        out.push(b'/');
        out.extend_from_slice(&self.buf);
        self.buf.clear();
        self.state = new_state;
        self.reconsume_if(Some(0));
        Some(Token::Character(out))
    }

    fn st_rawtext_lt(&mut self, c: Option<u8>) -> Option<Token> {
        match c {
            Some(b'/') => {
