    fn st_script_escape_start(&mut self, c: Option<u8>) -> Option<Token> {
        match c {
            Some(b'-') => {
                self.pos += 1;
                self.buf.push(b'-');
                self.state = State::ScriptDataEscapeStartDash;
                None
            }
            _ => {
                self.state = State::ScriptData;
                self.reconsume_if(c);
                None
            }
        }
    }

    fn st_script_escape_start_dash(&mut self, c: Option<u8>) -> Option<Token> {
