    fn st_tag_open(&mut self, c: Option<u8>) -> Option<Token> {
        match c {
            Some(b'!') => {
                self.pos += 1;
                self.state = State::MarkupDeclarationOpen;
                None
            }
            Some(b'/') => {
                self.pos += 1;
                self.state = State::EndTagOpen;
                None
            }
            Some(x) if is_alpha(x) => {
                self.state = State::TagName;
                self.last_start_tag.clear();
                None
            }
            Some(b'?') => {
                self.buf.clear();
                self.state = State::BogusComment;
                self.pos += 1;
                None
            }
            Some(x) if x == b'>' => {
                self.pos += 1;
                self.state = State::Data;
                self.buf.clear();
                Some(Token::Character(vec![b'<']))
            }
            Some(0x00) => {
                self.buf.clear();
                self.state = State::TagName;
                self.last_start_tag.clear();
                self.buf.push(0xFF);
                self.pos += 1;
                None
            }
            Some(_) => {
                self.buf.clear();
                self.state = State::Data;
                self.buf.push(b'<');
                Some(Token::Character(vec![b'<']))
            }
            None => {
                self.buf.clear();
                self.state = State::Data;
                Some(Token::Character(vec![b'<']))
            }
        }
    }

    fn st_end_tag_open(&mut self, c: Option<u8>) -> Option<Token> {
        match c {
            Some(x) if is_alpha(x) => {
