//! HTML5 tokenizer (states follow the HTML standard tokenizer algorithm).

pub fn is_ws(c: u8) -> bool {
    matches!(c, 0x09 | 0x0a | 0x0c | 0x0d | 0x20)
}
pub fn is_alpha(c: u8) -> bool {
    matches!(c, b'a'..=b'z' | b'A'..=b'Z')
}
pub fn is_alnum(c: u8) -> bool {
    matches!(c, b'0'..=b'9') || is_alpha(c)
}
pub fn lower_byte(c: u8) -> u8 {
    if c.is_ascii_uppercase() {
        c + 32
    } else {
        c
    }
}
pub fn to_lower(v: &[u8]) -> Vec<u8> {
    v.iter().map(|&c| lower_byte(c)).collect()
