            };
            match d { Some(d) => { n = n.saturating_mul(radix as u64).saturating_add(d); p += 1; any = true; } None => break }
        }
        if !any { return None; }
        let mut cp: u32 = if n > 0x10FFFF { 0 } else { n as u32 };
        if cp == 0 { cp = 0xFFFD; }
        else if (0xD800..0xE000).contains(&cp) { cp = 0xFFFD; }
        else if (0x80..=0x9F).contains(&cp) {
            let mapped = crate::WIN1252[(cp - 0x80) as usize];
            if mapped != 0 { cp = mapped; }
        }
        if self.input.get(p) == Some(&b';') { p += 1; }
        self.pos = p;
        Some((String::from_char(cp).into_bytes(), p - amp))
    }

    fn named_char_ref(&mut self, amp: usize, in_attribute: bool) -> Option<(Vec<u8>, usize)> {
        let mut p = amp + 1;
        while let Some(&x) = self.input.get(p) {
            if !is_alnum(x) { break }
            p += 1;
        }
        let n = p - (amp + 1);
        if n == 0 { return None; }
        let run = &self.input[amp + 1..amp + 1 + n];
        let maxlen = crate::MAX_ENTITY_LEN;
        let mut best: Option<(usize, &'static str)> = None;
        for l in (1..=n.min(maxlen)).rev() {
            if l < n && run[l] == b';' {
                if let Some(v) = crate::lookup_named_semi(&run[..l]) {
                    best = Some((l + 1, v));
                    break;
                }
            }
        }
        if best.is_none() {
            for l in (1..=n.min(maxlen)).rev() {
                if let Some(v) = crate::lookup_named_nosemi(&run[..l]) {
                    best = Some((l, v));
                    break;
                }
            }
        }
        match best {
            Some((len, v)) => {
                self.pos = amp + 1 + len;
                Some((v.as_bytes().to_vec(), len + 1))
            }
            None => {
                if in_attribute {
                    if let Some(&x) = self.input.get(amp + 1 + n) {
                        if x == b'=' || is_alnum(x) { return None }
                    }
                }
                None
            }
        }
    }

    pub fn next_token(&mut self) -> Token {
