                State::DoctypePublicIdentifierSingle => match c {
                    Some(b'\'') => { self.adv(); self.temp.clear(); self.state = State::AfterDoctypePublicIdentifier; }
                    Some(0x00) => { self.adv(); self.temp.extend_from_slice("\u{FFFD}".as_bytes()); }
                    Some(_) => {
                        let start = self.pos;
                        let mut end = start;
                        while end < self.input.len() && self.input[end] != b'\'' && self.input[end] != 0x00 { end += 1 }
                        self.temp.extend_from_slice(&self.input[start..end]);
                        self.pos = end;
                    }
                    None => { self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: true }; }
                }
                State::AfterDoctypePublicIdentifier => match c {
                    Some(x) if is_ws(x) => { self.adv(); self.state = State::BetweenDoctypePublicAndSystem; }
                    Some(b'>') => { self.adv(); self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: self.force_quirks }; }
                    _ => { self.pos -= 1; self.state = State::BogusDoctype; }
                }
                State::BetweenDoctypePublicAndSystem => match c {
                    Some(x) if is_ws(x) => { self.adv(); }
                    Some(b'>') => { self.adv(); self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: self.force_quirks }; }
                    Some(b'"') => { self.adv(); self.temp.clear(); self.state = State::DoctypeSystemIdentifierDouble; }
                    Some(b'\'') => { self.adv(); self.temp.clear(); self.state = State::DoctypeSystemIdentifierSingle; }
                    _ => { self.pos -= 1; self.state = State::BogusDoctype; }
                }
                State::AfterDoctypeSystemKeyword => match c {
                    Some(x) if is_ws(x) => { self.adv(); self.state = State::BeforeDoctypeSystemIdentifier; }
                    Some(b'"') => { self.adv(); self.temp.clear(); self.state = State::DoctypeSystemIdentifierDouble; }
                    Some(b'\'') => { self.adv(); self.temp.clear(); self.state = State::DoctypeSystemIdentifierSingle; }
                    Some(b'>') => { self.adv(); self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: true }; }
                    _ => { self.pos -= 1; self.state = State::BogusDoctype; }
                }
                State::BeforeDoctypeSystemIdentifier => match c {
                    Some(x) if is_ws(x) => { self.adv(); }
                    Some(b'"') => { self.adv(); self.temp.clear(); self.state = State::DoctypeSystemIdentifierDouble; }
                    Some(b'\'') => { self.adv(); self.temp.clear(); self.state = State::DoctypeSystemIdentifierSingle; }
                    Some(b'>') => { self.adv(); self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: true }; }
                    _ => { self.pos -= 1; self.state = State::BogusDoctype; }
                }
                State::DoctypeSystemIdentifierDouble => match c {
                    Some(b'"') => { self.adv(); self.temp.clear(); self.state = State::AfterDoctypeSystemIdentifier; }
                    Some(0x00) => { self.adv(); self.temp.extend_from_slice("\u{FFFD}".as_bytes()); }
                    Some(_) => {
                        let start = self.pos;
                        let mut end = start;
                        while end < self.input.len() && self.input[end] != b'"' && self.input[end] != 0x00 { end += 1 }
                        self.temp.extend_from_slice(&self.input[start..end]);
                        self.pos = end;
                    }
                    None => { self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: true }; }
                }
                State::DoctypeSystemIdentifierSingle => match c {
                    Some(b'\'') => { self.adv(); self.temp.clear(); self.state = State::AfterDoctypeSystemIdentifier; }
                    Some(0x00) => { self.adv(); self.temp.extend_from_slice("\u{FFFD}".as_bytes()); }
                    Some(_) => {
                        let start = self.pos;
                        let mut end = start;
                        while end < self.input.len() && self.input[end] != b'\'' && self.input[end] != 0x00 { end += 1 }
                        self.temp.extend_from_slice(&self.input[start..end]);
                        self.pos = end;
                    }
                    None => { self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: true }; }
                }
                State::AfterDoctypeSystemIdentifier => match c {
                    Some(x) if is_ws(x) => { self.adv(); self.state = State::BetweenDoctypeSystemAndSystem; }
                    Some(b'>') => { self.adv(); self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: self.force_quirks }; }
                    _ => { self.pos -= 1; self.state = State::BogusDoctype; }
                }
                State::BetweenDoctypeSystemAndSystem => match c {
                    Some(x) if is_ws(x) => { self.adv(); }
                    Some(b'>') => { self.adv(); self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: self.force_quirks }; }
                    _ => { self.pos -= 1; self.state = State::BogusDoctype; }
                }
                State::BogusDoctype => match c {
                    Some(b'>') => { self.adv(); self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: true }; }
                    Some(_) => { self.adv(); }
                    None => { self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: true }; }
                }
                State::RcdataLessThan | State::RawtextLessThan => match c {
                    Some(b'/') => { self.adv(); self.temp.clear(); self.state = if self.state == State::RcdataLessThan { State::RcdataEndTagOpen } else { State::RawtextEndTagOpen }; }
                    _ => { self.buf.push(b'<'); self.state = if self.state == State::RcdataLessThan { State::Rcdata } else { State::Rawtext }; if c.is_none() { return Token::Character(vec![b'<']) } }
                }
                State::RcdataEndTagOpen | State::RawtextEndTagOpen | State::ScriptDataEndTagOpen
                | State::ScriptDataEscapedEndTagOpen => match c {
                    Some(x) if is_alpha(x) => { self.pos -= 1; self.temp.clear(); self.state = match self.state {
                        State::RcdataEndTagOpen => State::RcdataEndTagName,
                        State::RawtextEndTagOpen => State::RawtextEndTagName,
                        State::ScriptDataEndTagOpen => State::ScriptDataEndTagName,
                        _ => State::ScriptDataEscapedEndTagName,
                    }; }
                    _ => {
                        let back = match self.state {
                            State::RcdataEndTagOpen => State::Rcdata,
                            State::RawtextEndTagOpen => State::Rawtext,
                            State::ScriptDataEndTagOpen => State::ScriptData,
                            _ => State::ScriptDataEscaped,
                        };
                        self.buf.extend_from_slice(b"</");
                        self.state = back;
                        if c.is_none() { return Token::Character(std::mem::take(&mut self.buf)); }
                    }
                }
                State::RcdataEndTagName | State::RawtextEndTagName | State::ScriptDataEndTagName
                | State::ScriptDataEscapedEndTagName => {
                    if let Some(t) = self.end_tag_name_step(c) { return t }
                }
                State::ScriptDataLessThan => match c {
                    Some(b'/') => { self.adv(); self.temp.clear(); self.state = State::ScriptDataEndTagOpen; }
                    Some(b'!') => { self.adv(); self.buf.extend_from_slice(b"<!"); self.temp.clear(); self.state = State::ScriptDataEscapeStart; }
                    _ => { self.buf.push(b'<'); self.state = State::ScriptData; if c.is_none() { return Token::Character(vec![b'<']) } }
                }
                State::ScriptDataEscapedLessThan | State::ScriptDataDoubleEscapedLessThan => match c {
                    Some(b'/') => {
                        self.adv();
                        self.temp.clear();
                        self.state = if self.state == State::ScriptDataEscapedLessThan { State::ScriptDataEscapedEndTagOpen } else { State::ScriptDataDoubleEscapeEnd };
                    }
                    Some(x) if is_alpha(x) => {
                        self.buf.push(b'<');
                        self.temp.clear();
                        self.state = if self.state == State::ScriptDataEscapedLessThan { State::ScriptDataDoubleEscapeStart } else { State::ScriptDataDoubleEscapeEnd };
                    }
                    _ => { self.state = if self.state == State::ScriptDataEscapedLessThan { State::ScriptDataEscaped } else { State::ScriptDataDoubleEscaped }; }
                }
                State::ScriptDataEscapeStart | State::ScriptDataEscapeStartDash => match c {
                    Some(b'-') => {
                        self.adv();
                        self.buf.push(b'-');
                        self.state = if self.state == State::ScriptDataEscapeStart { State::ScriptDataEscapeStartDash } else { State::ScriptDataEscapedDashDash };
                    }
                    _ => { self.state = State::ScriptData; }
                }
                State::ScriptDataEscapedDash => match c {
                    Some(b'-') => { self.adv(); self.state = State::ScriptDataEscapedDashDash; }
                    Some(b'<') => { self.adv(); self.state = State::ScriptDataEscapedLessThan; }
                    _ => { self.state = State::ScriptDataEscaped; }
                }
                State::ScriptDataEscapedDashDash => match c {
                    Some(b'-') => { self.adv(); }
                    Some(b'<') => { self.adv(); self.state = State::ScriptDataEscapedLessThan; }
                    Some(b'>') => { self.adv(); self.state = State::ScriptData; }
                    _ => { self.state = State::ScriptDataEscaped; }
                }
                State::ScriptDataDoubleEscapeStart | State::ScriptDataDoubleEscapeEnd => {
                    let is_start = self.state == State::ScriptDataDoubleEscapeStart;
                    match c {
                        Some(b'-') | Some(b'<') => { self.adv(); self.buf.push(c.unwrap()); }
                        Some(b'>') => {
                            if self.temp_matches_script() {
                                self.adv();
                                self.state = if is_start { State::ScriptData } else { State::ScriptDataEscaped };
                                self.buf.push(b'>');
                                return Token::Character(std::mem::take(&mut self.buf));
                            } else {
                                self.adv();
                                self.state = if is_start { State::ScriptDataEscaped } else { State::ScriptDataDoubleEscaped };
                            }
                        }
                        Some(x) if is_alnum(x) => { self.temp.push(lower_byte(x)); self.adv(); }
                        _ => { self.state = if is_start { State::ScriptDataEscaped } else { State::ScriptDataDoubleEscaped }; }
                    }
                }
                State::ScriptDataDoubleEscapedDash => match c {
                    Some(b'-') => { self.adv(); self.state = State::ScriptDataDoubleEscapedDashDash; }
                    Some(b'<') => { self.adv(); self.state = State::ScriptDataDoubleEscapedLessThan; }
                    _ => { self.state = State::ScriptDataDoubleEscaped; }
                }
                State::ScriptDataDoubleEscapedDashDash => match c {
                    Some(b'-') => { self.adv(); }
                    Some(b'<') => { self.adv(); self.state = State::ScriptDataDoubleEscapedLessThan; }
                    Some(b'>') => { self.adv(); self.state = State::ScriptDataEscaped; }
                    _ => { self.state = State::ScriptDataDoubleEscaped; }
                }
            }
        }
    }

    fn temp_matches_script(&self) -> bool {
        self.temp == b"script"
    }

    fn end_tag_name_step(&mut self, c: Option<u8>) -> Option<Token> {
        let back = match self.state {
            State::RcdataEndTagName => State::Rcdata,
            State::RawtextEndTagName => State::Rawtext,
            State::ScriptDataEndTagName => State::ScriptData,
            _ => State::ScriptDataEscaped,
        };
        match c {
            Some(x) if is_ws(x) => {
                if self.temp_matches_end_tag() {
                    self.adv();
                    self.state = State::AttributeNameBefore;
                    self.in_tag = true;
                    self.attrs.clear();
                    self.finish_attr();
                    self.attrs.clear();
                    return Some(Token::EndTag { name: std::mem::take(&mut self.temp) });
                }
                Some(self.flush_end_tag(back))
            }
            Some(b'/') => {
                if self.temp_matches_end_tag() {
                    self.adv();
                    self.state = State::SelfClosingStart;
                    self.in_tag = true;
                    self.attrs.clear();
                    return None;
                }
                Some(self.flush_end_tag(back))
            }
            Some(b'>') => {
                if self.temp_matches_end_tag() {
                    self.adv();
                    self.state = State::Data;
                    self.in_tag = false;
                    return Some(Token::EndTag { name: std::mem::take(&mut self.temp) });
                }
                Some(self.flush_end_tag(back))
            }
            Some(x) if is_alnum(x) => { self.temp.push(lower_byte(x)); self.adv(); None }
            _ => Some(self.flush_end_tag(back)),
        }
    }

    fn temp_matches_end_tag(&self) -> bool {
        self.appropriate_end_tag == self.temp
    }

    fn flush_end_tag(&mut self, back: State) -> Token {
        let mut out = Vec::new();
        out.push(b'<');
        out.push(b'/');
        out.extend_from_slice(&std::mem::take(&mut self.temp));
        self.state = back;
        self.in_tag = false;
        self.pos -= 1;
        if self.pos < 0 { self.pos = 0 }
        Token::Character(out)
    }

    fn finish_attr(&mut self) {
        if self.attr_name.is_empty() {
            return;
        }
        let name = to_lower(&std::mem::take(&mut self.attr_name));
        let value = std::mem::take(&mut self.attr_value);
        // duplicate attributes: first occurrence wins
        if self.attrs.iter().any(|(n, _)| *n == name) {
            return;
        }
        self.attrs.push((name, value));
    }
}
