                    _ => { self.state = State::ScriptDataDoubleEscaped; }
                }
                State::ScriptDataDoubleEscapedDashDash => match c {
                    Some(b'-') => { self.adv(); }
                    Some(b'<') => { self.adv(); self.state = State::ScriptDataDoubleEscapedLessThan; }
                    Some(b'>') => { self.adv(); self.state = State::ScriptDataEscaped; }
                    _ => { self.state = State::ScriptDataDoubleEscaped; }
                }
            }
        }
    }

    fn temp_matches_script(&self) -> bool {
        self.temp == b"script"
    }

    fn end_tag_name_step(&mut self, c: Option<u8>) -> Option<Token> {
        let back = match self.state {
            State::RcdataEndTagName => State::Rcdata,
            State::RawtextEndTagName => State::Rawtext,
            State::ScriptDataEndTagName => State::ScriptData,
            _ => State::ScriptDataEscaped,
        };
        match c {
            Some(x) if is_ws(x) => {
                if self.temp_matches_end_tag() {
                    self.adv();
                    self.state = State::AttributeNameBefore;
                    self.in_tag = true;
                    self.attrs.clear();
                    self.finish_attr();
                    self.attrs.clear();
                    return Some(Token::EndTag { name: std::mem::take(&mut self.temp) });
                }
                Some(self.flush_end_tag(back))
            }
            Some(b'/') => {
                if self.temp_matches_end_tag() {
                    self.adv();
                    self.state = State::SelfClosingStart;
                    self.in_tag = true;
                    self.attrs.clear();
                    return None;
                }
                Some(self.flush_end_tag(back))
            }
            Some(b'>') => {
                if self.temp_matches_end_tag() {
                    self.adv();
                    self.state = State::Data;
                    self.in_tag = false;
                    return Some(Token::EndTag { name: std::mem::take(&mut self.temp) });
                }
                Some(self.flush_end_tag(back))
            }
            Some(x) if is_alnum(x) => { self.temp.push(lower_byte(x)); self.adv(); None }
            _ => Some(self.flush_end_tag(back)),
        }
    }

    fn temp_matches_end_tag(&self) -> bool {
        self.appropriate_end_tag == self.temp
    }

    fn flush_end_tag(&mut self, back: State) -> Token {
        let mut out = Vec::new();
        out.push(b'<');
        out.push(b'/');
        out.extend_from_slice(&std::mem::take(&mut self.temp));
        self.state = back;
        self.in_tag = false;
        self.pos -= 1;
        if self.pos < 0 { self.pos = 0 }
        Token::Character(out)
    }

    fn finish_attr(&mut self) {
        if self.attr_name.is_empty() {
            return;
        }
        let name = to_lower(&std::mem::take(&mut self.attr_name));
        let value = std::mem::take(&mut self.attr_value);
        // duplicate attributes: first occurrence wins
        if self.attrs.iter().any(|(n, _)| *n == name) {
            return;
        }
        self.attrs.push((name, value));
    }
}
