//! HTML5 tokenizer implementing the tokenizer algorithm of the HTML standard.

pub fn is_ws(c: u8) -> bool { matches!(c, 0x09 | 0x0a | 0x0c | 0x0d | 0x20) }
pub fn is_alpha(c: u8) -> bool { matches!(c, b'a'..=b'z' | b'A'..=b'Z') }
pub fn is_alnum(c: u8) -> bool { matches!(c, b'0'..=b'9') || is_alpha(c) }
pub fn lower_byte(c: u8) -> u8 { if c.is_ascii_uppercase() { c + 32 } else { c } }
pub fn to_lower(v: &[u8]) -> Vec<u8> { v.iter().map(|&c| lower_byte(c)).collect() }

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum State {
    Data, Rcdata, Rawtext, ScriptData, Plaintext,
    TagOpen, EndTagOpen, TagName,
    RcdataLessThan, RcdataEndTagOpen, RcdataEndTagName,
    RawtextLessThan, RawtextEndTagOpen, RawtextEndTagName,
    ScriptDataLessThan, ScriptDataEndTagOpen, ScriptDataEndTagName,
    ScriptDataEscapeStart, ScriptDataEscapeStartDash, ScriptDataEscaped,
    ScriptDataEscapedDash, ScriptDataEscapedDashDash, ScriptDataEscapedLessThan,
    ScriptDataEscapedEndTagOpen, ScriptDataEscapedEndTagName,
    ScriptDataDoubleEscapeStart, ScriptDataDoubleEscaped, ScriptDataDoubleEscapedDash,
    ScriptDataDoubleEscapedDashDash, ScriptDataDoubleEscapedLessThan,
    ScriptDataDoubleEscapeEnd, ScriptDataDoubleEscapeEndDash, ScriptDataDoubleEscapeEndDashDash,
    AttributeNameBefore, AttributeName, AttributeNameAfter, AttributeValueBefore,
    AttributeValueDouble, AttributeValueSingle, AttributeValueUnquoted, AttributeValueAfterQuote,
    SelfClosingStart, BogusComment, MarkupDeclarationOpen,
    CommentStart, CommentStartDash, Comment, CommentLessThan, CommentLessThanBang,
    CommentLessThanBangDash, CommentLessThanBangDashDash, CommentEndDash, CommentEnd, CommentEndBang,
    BeforeDoctypeName, DoctypeName, AfterDoctypeName, AfterDoctypePublicKeyword,
    BeforeDoctypePublicIdentifier, DoctypePublicIdentifierDouble, DoctypePublicIdentifierSingle,
    AfterDoctypePublicIdentifier, BetweenDoctypePublicAndSystem, AfterDoctypeSystemKeyword,
    BeforeDoctypeSystemIdentifier, DoctypeSystemIdentifierDouble, DoctypeSystemIdentifierSingle,
    AfterDoctypeSystemIdentifier, BetweenDoctypeSystemAndSystem, BogusDoctype,
    CdataSection, CdataRightBracket, CdataDoubleRightBracket,
}

#[derive(Debug, Clone)]
pub enum Token {
    Doctype { name: Vec<u8>, force_quirks: bool },
    StartTag { name: Vec<u8>, attrs: Vec<(Vec<u8>, Vec<u8>)>, self_closing: bool },
    EndTag { name: Vec<u8> },
    Comment(Vec<u8>),
    Character(Vec<u8>),
    Eof,
}

pub struct Tokenizer {
    input: Vec<u8>,
    pos: usize,
    state: State,
    last_start_tag: Vec<u8>,
    appropriate_end_tag: Vec<u8>,
    buf: Vec<u8>,
    temp: Vec<u8>,
    attrs: Vec<(Vec<u8>, Vec<u8>)>,
    attr_name: Vec<u8>,
    attr_value: Vec<u8>,
    in_tag: bool,
    in_end_tag: bool,
    eof: bool,
    dname: Vec<u8>,
    force_quirks: bool,
}

macro_rules! emit_start {
    ($s:expr) => {{
        let name = to_lower(&std::mem::take(&mut $s.buf));
        $s.last_start_tag = name.clone();
        $s.set_appropriate_end_tag();
        $s.state = State::Data;
        $s.in_tag = false;
        if $s.in_end_tag {
            $s.in_end_tag = false;
            return Token::EndTag { name };
        }
        return Token::StartTag { name, attrs: std::mem::take(&mut $s.attrs), self_closing: false };
    }};
}

impl Tokenizer {
    pub fn new(input: Vec<u8>) -> Tokenizer {
        Tokenizer {
            input, pos: 0, state: State::Data, last_start_tag: Vec::new(),
            appropriate_end_tag: Vec::new(), buf: Vec::new(), temp: Vec::new(),
            attrs: Vec::new(), attr_name: Vec::new(), attr_value: Vec::new(),
            in_tag: false, in_end_tag: false, eof: false, dname: Vec::new(), force_quirks: false,
        }
    }
    fn set_appropriate_end_tag(&mut self) {
        let mut t = self.last_start_tag.clone();
        t.insert(0, b'/');
        self.appropriate_end_tag = t;
    }
    fn at(&self) -> Option<u8> { self.input.get(self.pos).copied() }
    fn adv(&mut self) { self.pos += 1; }
    fn reconsume(&mut self) { self.pos -= 1; }

    /// Handles a character reference. self.pos points just after '&'.
    fn char_ref(&mut self, in_attribute: bool) -> Option<Vec<u8>> {
        let amp = self.pos - 1;
        match self.at() {
            Some(b'#') => self.numeric_char_ref(amp),
            Some(x) if is_alnum(x) => self.named_char_ref(amp, in_attribute),
            _ => None,
        }
