        self.pos = p;
        Some(String::from_char(cp).into_bytes())
    }

    fn named_char_ref(&mut self, amp: usize, in_attribute: bool) -> Option<Vec<u8>> {
        let mut p = amp + 1;
        while let Some(&x) = self.input.get(p) {
            if !is_alnum(x) { break }
            p += 1;
        }
        let n = p - (amp + 1);
        if n == 0 { return None; }
        let run = &self.input[amp + 1..amp + 1 + n];
        let maxlen = crate::MAX_ENTITY_LEN;
        let mut best: Option<(usize, &'static str)> = None;
        for l in (1..=n.min(maxlen)).rev() {
            if l < n && run[l] == b';' {
                if let Some(v) = crate::lookup_named_semi(&run[..l]) {
                    best = Some((l + 1, v));
                    break;
                }
            }
        }
        if best.is_none() {
            for l in (1..=n.min(maxlen)).rev() {
                if let Some(v) = crate::lookup_named_nosemi(&run[..l]) {
                    best = Some((l, v));
                    break;
                }
            }
        }
        match best {
            Some((len, v)) => {
                self.pos = amp + 1 + len;
                Some(v.as_bytes().to_vec())
            }
            None => {
                if in_attribute {
                    if let Some(&x) = self.input.get(amp + 1 + n) {
                        if x == b'=' || is_alnum(x) { return None }
                    }
                }
                None
            }
        }
    }

    fn finish_attr(&mut self) {
        if self.attr_name.is_empty() {
            self.attr_value.clear();
            return;
        }
        let name = to_lower(&std::mem::take(&mut self.attr_name));
        let value = std::mem::take(&mut self.attr_value);
        if self.attrs.iter().any(|(n, _)| *n == name) {
            return;
        }
        self.attrs.push((name, value));
    }

    pub fn next_token(&mut self) -> Token {
        loop {
            let c = self.at();
            match self.state {
                // ------------------------------------------------ raw text-ish states
                State::Data | State::Rcdata | State::Rawtext | State::ScriptData
                | State::ScriptDataEscaped | State::ScriptDataDoubleEscaped | State::Plaintext => {
                    let mut was_script_escaped = false;
                    match c {
                        None => {
                            let v = std::mem::take(&mut self.buf);
                            if v.is_empty() { self.eof = true; return Token::Eof }
                            return Token::Character(v);
                        }
                        Some(b'<') => {
                            match self.state {
                                State::Data => { self.adv(); self.state = State::TagOpen; }
                                State::Rcdata => { self.adv(); self.state = State::RcdataLessThan; }
                                State::Rawtext => { self.adv(); self.state = State::RawtextLessThan; }
                                State::ScriptData => { self.adv(); self.state = State::ScriptDataLessThan; }
                                State::ScriptDataEscaped => { self.adv(); was_script_escaped = true; self.state = State::ScriptDataEscapedLessThan; }
                                State::ScriptDataDoubleEscaped => { self.adv(); was_script_escaped = true; self.state = State::ScriptDataDoubleEscapedLessThan; }
                                _ => { self.buf.push(b'<'); self.adv(); }
                            }
                        }
                        Some(b'&') if self.state == State::Data || self.state == State::Rcdata => {
                            self.adv();
                            match self.char_ref(false) {
                                Some(s) => self.buf.extend_from_slice(&s),
                                None => self.buf.push(b'&'),
                            }
                        }
                        Some(0x00) => {
                            self.adv();
                            if self.state != State::Data {
                                self.buf.extend_from_slice("\u{FFFD}".as_bytes());
                            }
                        }
                        Some(_) => {
                            let start = self.pos;
                            let mut end = start;
                            while end < self.input.len() {
                                let b = self.input[end];
                                let stop = match self.state {
                                    State::Plaintext => b == 0x00,
                                    State::Data | State::Rcdata => b == b'&' || b == b'<' || b == 0x00,
                                    _ => b == b'<' || b == 0x00,
                                };
                                if stop { break }
                                end += 1;
                            }
                            self.buf.extend_from_slice(&self.input[start..end]);
                            self.pos = end;
                        }
                    }
                    let _ = was_script_escaped;
                    continue;
                }
                State::ScriptDataEscapeStart | State::ScriptDataEscapeStartDash => {
                    match c {
                        Some(b'-') => {
                            self.adv();
                            self.buf.push(b'-');
                            self.state = if self.state == State::ScriptDataEscapeStart {
                                State::ScriptDataEscapeStartDash
                            } else { State::ScriptDataEscapedDashDash };
                        }
                        None => {
                            let v = std::mem::take(&mut self.buf);
                            if v.is_empty() { self.eof = true; return Token::Eof }
                            return Token::Character(v);
                        }
                        _ => { self.reconsume(); self.state = State::ScriptData; }
                    }
                }
                State::ScriptDataEscapedDash | State::ScriptDataDoubleEscapedDash => {
                    match c {
                        Some(b'-') => { self.adv(); self.state = if self.state == State::ScriptDataEscapedDash { State::ScriptDataEscapedDashDash } else { State::ScriptDataDoubleEscapedDashDash }; }
                        Some(b'<') => { self.adv(); self.state = if self.state == State::ScriptDataEscapedDash { State::ScriptDataEscapedLessThan } else { State::ScriptDataDoubleEscapedLessThan }; }
                        None => {
                            let v = std::mem::take(&mut self.buf);
                            if v.is_empty() { self.eof = true; return Token::Eof }
                            return Token::Character(v);
                        }
                        _ => { self.reconsume(); self.state = if self.state == State::ScriptDataEscapedDash { State::ScriptDataEscaped } else { State::ScriptDataDoubleEscaped }; }
                    }
                }
                State::ScriptDataEscapedDashDash | State::ScriptDataDoubleEscapedDashDash => {
                    let esc = self.state == State::ScriptDataEscapedDashDash;
                    match c {
                        Some(b'-') => { self.adv(); }
                        Some(b'<') => { self.adv(); self.state = if esc { State::ScriptDataEscapedLessThan } else { State::ScriptDataDoubleEscapedLessThan }; }
                        Some(b'>') => { self.adv(); self.state = if esc { State::ScriptData } else { State::ScriptDataEscaped }; }
                        None => {
                            let v = std::mem::take(&mut self.buf);
                            if v.is_empty() { self.eof = true; return Token::Eof }
                            return Token::Character(v);
                        }
                        _ => { self.reconsume(); self.state = if esc { State::ScriptDataEscaped } else { State::ScriptDataDoubleEscaped }; }
                    }
                }
                State::ScriptDataEscapedLessThan | State::ScriptDataDoubleEscapedLessThan => {
                    let esc = self.state == State::ScriptDataEscapedLessThan;
                    match c {
                        Some(b'/') => {
                            self.adv();
                            self.temp.clear();
                            self.state = if esc { State::ScriptDataEscapedEndTagOpen } else { State::ScriptDataDoubleEscapeEnd };
                        }
                        Some(x) if is_alpha(x) && esc => {
                            self.buf.push(b'<');
                            self.temp.clear();
                            self.state = State::ScriptDataDoubleEscapeStart;
                        }
                        None => {
                            let v = std::mem::take(&mut self.buf);
                            if v.is_empty() { self.eof = true; return Token::Eof }
                            return Token::Character(v);
                        }
                        _ => { self.reconsume(); self.state = if esc { State::ScriptDataEscaped } else { State::ScriptDataDoubleEscaped }; }
                    }
                }
                State::ScriptDataDoubleEscapeStart | State::ScriptDataDoubleEscapeEnd => {
                    let start = self.state == State::ScriptDataDoubleEscapeStart;
                    match c {
                        Some(x) if is_alnum(x) => { self.temp.push(lower_byte(x)); self.adv(); }
                        Some(x) if is_ws(x) || x == b'>' => {
                            if self.temp == b"script" {
                                self.adv();
                                self.state = if start { State::ScriptData } else { State::ScriptDataEscaped };
                            } else {
                                self.state = if start { State::ScriptDataEscaped } else { State::ScriptDataDoubleEscaped };
                            }
                        }
                        None => {
                            let v = std::mem::take(&mut self.buf);
                            if v.is_empty() { self.eof = true; return Token::Eof }
                            return Token::Character(v);
                        }
                        _ => { self.state = if start { State::ScriptDataEscaped } else { State::ScriptDataDoubleEscaped }; }
                    }
                }
                // ------------------------------------------------ less-than in rcdata/rawtext
                State::RcdataLessThan | State::RawtextLessThan => match c {
                    Some(b'/') => { self.adv(); self.temp.clear(); self.state = if self.state == State::RcdataLessThan { State::RcdataEndTagOpen } else { State::RawtextEndTagOpen }; }
                    None => { self.buf.push(b'<'); let v = std::mem::take(&mut self.buf); if v.is_empty() { self.eof = true; return Token::Eof } return Token::Character(v) }
                    _ => { self.buf.push(b'<'); self.state = if self.state == State::RcdataLessThan { State::Rcdata } else { State::Rawtext } }
                }
                State::RcdataEndTagOpen | State::RawtextEndTagOpen | State::ScriptDataEndTagOpen
                | State::ScriptDataEscapedEndTagOpen => match c {
                    Some(x) if is_alpha(x) => { self.pos -= 1; self.temp.clear(); self.state = match self.state {
                        State::RcdataEndTagOpen => State::RcdataEndTagName,
                        State::RawtextEndTagOpen => State::RawtextEndTagName,
                        State::ScriptDataEndTagOpen => State::ScriptDataEndTagName,
                        _ => State::ScriptDataEscapedEndTagName,
                    } }
                    _ => {
                        let back = match self.state {
                            State::RcdataEndTagOpen => State::Rcdata,
                            State::RawtextEndTagOpen => State::Rawtext,
                            State::ScriptDataEndTagOpen => State::ScriptData,
                            _ => State::ScriptDataEscaped,
                        };
                        self.buf.extend_from_slice(b"</");
                        self.state = back;
                        if c.is_none() { let v = std::mem::take(&mut self.buf); return Token::Character(v) }
                    }
                }
                State::RcdataEndTagName | State::RawtextEndTagName | State::ScriptDataEndTagName
                | State::ScriptDataEscapedEndTagName => {
                    let back = match self.state {
                        State::RcdataEndTagName => State::Rcdata,
                        State::RawtextEndTagName => State::Rawtext,
                        State::ScriptDataEndTagName => State::ScriptData,
                        _ => State::ScriptDataEscaped,
                    };
                    match c {
                        Some(x) if is_ws(x) => {
                            if self.appropriate_end_tag == self.temp {
                                self.adv();
                                self.in_tag = true;
                                self.in_end_tag = true;
                                self.attrs.clear();
                                self.state = State::AttributeNameBefore;
                                continue;
                            }
                            self.pos -= 1;
                            let mut out = vec![b'<', b'/'];
                            out.extend_from_slice(&std::mem::take(&mut self.temp));
                            self.state = back;
                            return Token::Character(out);
                        }
                        Some(b'/') => {
                            if self.appropriate_end_tag == self.temp {
                                self.adv();
                                self.in_tag = true;
                                self.in_end_tag = true;
                                self.attrs.clear();
                                self.state = State::SelfClosingStart;
                                continue;
                            }
                            self.pos -= 1;
                            let mut out = vec![b'<', b'/'];
                            out.extend_from_slice(&std::mem::take(&mut self.temp));
                            self.state = back;
                            return Token::Character(out);
                        }
                        Some(b'>') => {
                            if self.appropriate_end_tag == self.temp {
                                self.adv();
                                self.state = State::Data;
                                return Token::EndTag { name: std::mem::take(&mut self.temp) };
                            }
                            self.pos -= 1;
                            let mut out = vec![b'<', b'/'];
                            out.extend_from_slice(&std::mem::take(&mut self.temp));
                            self.state = back;
                            return Token::Character(out);
                        }
                        Some(x) if is_alnum(x) => { self.temp.push(lower_byte(x)); self.adv(); }
                        None => {
                            let mut out = vec![b'<', b'/'];
                            out.extend_from_slice(&std::mem::take(&mut self.temp));
                            self.state = back;
                            return Token::Character(out);
                        }
                        _ => {
                            self.pos -= 1;
                            let mut out = vec![b'<', b'/'];
                            out.extend_from_slice(&std::mem::take(&mut self.temp));
                            self.state = back;
                            return Token::Character(out);
                        }
                    }
                }
                State::ScriptDataLessThan => match c {
                    Some(b'/') => { self.adv(); self.temp.clear(); self.state = State::ScriptDataEndTagOpen; }
                    Some(b'!') => { self.adv(); self.buf.extend_from_slice(b"<!"); self.temp.clear(); self.state = State::ScriptDataEscapeStart; }
                    None => { self.buf.push(b'<'); let v = std::mem::take(&mut self.buf); if v.is_empty() { self.eof = true; return Token::Eof } return Token::Character(v) }
                    _ => { self.buf.push(b'<'); self.state = State::ScriptData; }
                }
                // ------------------------------------------------ tag states
                State::TagOpen => match c {
                    Some(b'!') => { self.adv(); self.state = State::MarkupDeclarationOpen; }
                    Some(b'/') => { self.adv(); self.state = State::EndTagOpen; }
                    Some(x) if is_alpha(x) => {
                        self.last_start_tag.clear();
                        self.attrs.clear();
                        self.in_tag = true;
                        self.in_end_tag = false;
                        self.state = State::TagName;
                    }
                    Some(b'?') => { self.adv(); self.temp.clear(); self.in_tag = true; self.in_end_tag = false; self.state = State::BogusComment; }
                    Some(b'>') => { self.adv(); self.state = State::Data; return Token::Character(vec![b'<']); }
                    Some(0x00) => {
                        self.adv();
                        self.attrs.clear();
                        self.in_tag = true;
                        self.in_end_tag = false;
                        self.state = State::TagName;
                        self.buf.extend_from_slice("\u{FFFD}".as_bytes());
                    }
                    Some(_) => { self.reconsume(); self.state = State::Data; self.buf.clear(); self.buf.push(b'<'); }
                    None => { self.state = State::Data; return Token::Character(vec![b'<']); }
                }
                State::EndTagOpen => match c {
                    Some(x) if is_alpha(x) => {
                        self.in_tag = true;
                        self.in_end_tag = true;
                        self.buf.clear();
                        self.state = State::TagName;
                    }
                    Some(b'>') => { self.adv(); self.state = State::Data; }
                    Some(0x00) => { self.adv(); self.temp.clear(); self.in_tag = true; self.state = State::BogusComment; }
                    Some(_) => { self.reconsume(); self.temp.clear(); self.in_tag = true; self.state = State::BogusComment; }
                    None => {
                        self.state = State::Data;
                        self.buf.clear();
                        self.buf.extend_from_slice(b"</");
                        return Token::Character(std::mem::take(&mut self.buf));
                    }
                }
                State::TagName => match c {
                    Some(x) if is_ws(x) => { self.adv(); self.state = State::AttributeNameBefore; }
                    Some(b'/') => { self.adv(); self.state = State::SelfClosingStart; }
                    Some(b'>') => { self.adv(); emit_start!(self) }
                    Some(0x00) => { self.buf.extend_from_slice("\u{FFFD}".as_bytes()); self.adv(); }
                    Some(_) => {
                        let start = self.pos;
                        let mut end = start;
                        while end < self.input.len() {
                            let b = self.input[end];
                            if is_ws(b) || b == b'/' || b == b'>' || b == 0x00 { break }
                            end += 1;
                        }
                        self.buf.extend_from_slice(&self.input[start..end]);
                        self.pos = end;
                    }
                    None => emit_start!(self),
                }
                State::AttributeNameBefore => match c {
                    Some(x) if is_ws(x) => { self.adv(); }
                    Some(b'/') => { self.state = State::SelfClosingStart; }
                    Some(b'>') => { self.adv(); emit_start!(self) }
                    Some(b'=') => { self.adv(); self.attr_name.clear(); self.attr_name.push(b'='); self.attr_value.clear(); self.state = State::AttributeValueBefore; }
                    Some(0x00) => { self.adv(); self.attr_name.clear(); self.attr_name.extend_from_slice("\u{FFFD}".as_bytes()); self.state = State::AttributeName; }
                    Some(b'"') | Some(b'\'') | Some(b'<') => { self.attr_name.clear(); self.attr_name.push(c.unwrap()); self.adv(); self.state = State::AttributeName; }
                    Some(_) => { self.attr_name.clear(); self.attr_value.clear(); self.state = State::AttributeName; }
                    None => emit_start!(self),
                }
                State::AttributeName => match c {
                    Some(x) if is_ws(x) || x == b'/' => { self.adv(); self.finish_attr(); self.state = State::AttributeNameAfter; }
                    Some(b'=') => { self.adv(); self.state = State::AttributeValueBefore; }
                    Some(b'>') => { self.adv(); self.finish_attr(); emit_start!(self) }
                    Some(0x00) => { self.attr_name.extend_from_slice("\u{FFFD}".as_bytes()); self.adv(); }
                    Some(b'"') | Some(b'\'') | Some(b'<') => { self.attr_name.push(c.unwrap()); self.adv(); }
                    Some(_) => {
                        let start = self.pos;
                        let mut end = start;
                        while end < self.input.len() {
                            let b = self.input[end];
                            if is_ws(b) || b == b'/' || b == b'=' || b == b'>' || b == 0x00 || b == b'"' || b == b'\'' || b == b'<' { break }
                            end += 1;
                        }
                        self.attr_name.extend_from_slice(&self.input[start..end]);
                        self.pos = end;
                    }
                    None => { self.finish_attr(); emit_start!(self) }
                }
                State::AttributeNameAfter => match c {
                    Some(x) if is_ws(x) => { self.adv(); }
                    Some(b'/') => { self.adv(); self.state = State::SelfClosingStart; }
                    Some(b'=') => { self.adv(); self.state = State::AttributeValueBefore; }
                    Some(b'>') => { self.adv(); emit_start!(self) }
                    Some(0x00) => { self.adv(); self.attr_name.clear(); self.attr_name.extend_from_slice("\u{FFFD}".as_bytes()); self.state = State::AttributeName; }
                    Some(b'"') | Some(b'\'') | Some(b'<') => { self.attr_name.clear(); self.attr_name.push(c.unwrap()); self.adv(); self.state = State::AttributeName; }
                    Some(_) => { self.attr_name.clear(); self.state = State::AttributeName; }
                    None => emit_start!(self),
                }
                State::AttributeValueBefore => match c {
                    Some(x) if is_ws(x) => { self.adv(); }
                    Some(b'"') => { self.adv(); self.attr_value.clear(); self.state = State::AttributeValueDouble; }
                    Some(b'\'') => { self.adv(); self.attr_value.clear(); self.state = State::AttributeValueSingle; }
                    Some(b'>') => { self.adv(); self.finish_attr(); emit_start!(self) }
                    Some(_) => { self.attr_value.clear(); self.state = State::AttributeValueUnquoted; }
                    None => { self.finish_attr(); emit_start!(self) }
                }
                State::AttributeValueDouble => match c {
                    Some(b'"') => { self.adv(); self.finish_attr(); self.state = State::AttributeValueAfterQuote; }
                    Some(b'&') => {
                        self.adv();
                        match self.char_ref(true) {
                            Some(s) => self.attr_value.extend_from_slice(&s),
                            None => self.attr_value.push(b'&'),
                        }
                    }
                    Some(0x00) => { self.attr_value.extend_from_slice("\u{FFFD}".as_bytes()); self.adv(); }
                    Some(_) => {
                        let start = self.pos;
                        let mut end = start;
                        while end < self.input.len() {
                            let b = self.input[end];
                            if b == b'"' || b == b'&' || b == 0x00 { break }
                            end += 1;
                        }
                        self.attr_value.extend_from_slice(&self.input[start..end]);
                        self.pos = end;
                    }
                    None => { self.finish_attr(); emit_start!(self) }
                }
                State::AttributeValueSingle => match c {
                    Some(b'\'') => { self.adv(); self.finish_attr(); self.state = State::AttributeValueAfterQuote; }
                    Some(b'&') => {
                        self.adv();
                        match self.char_ref(true) {
                            Some(s) => self.attr_value.extend_from_slice(&s),
                            None => self.attr_value.push(b'&'),
                        }
                    }
                    Some(0x00) => { self.attr_value.extend_from_slice("\u{FFFD}".as_bytes()); self.adv(); }
                    Some(_) => {
                        let start = self.pos;
                        let mut end = start;
                        while end < self.input.len() {
                            let b = self.input[end];
                            if b == b'\'' || b == b'&' || b == 0x00 { break }
                            end += 1;
                        }
                        self.attr_value.extend_from_slice(&self.input[start..end]);
                        self.pos = end;
                    }
                    None => { self.finish_attr(); emit_start!(self) }
                }
                State::AttributeValueUnquoted => match c {
                    Some(x) if is_ws(x) => { self.adv(); self.finish_attr(); self.state = State::AttributeNameBefore; }
                    Some(b'&') => {
                        self.adv();
                        match self.char_ref(true) {
                            Some(s) => self.attr_value.extend_from_slice(&s),
                            None => self.attr_value.push(b'&'),
                        }
                    }
                    Some(b'>') => { self.adv(); self.finish_attr(); emit_start!(self) }
                    Some(0x00) => { self.attr_value.extend_from_slice("\u{FFFD}".as_bytes()); self.adv(); }
                    Some(_) => {
                        let start = self.pos;
                        let mut end = start;
                        while end < self.input.len() {
                            let b = self.input[end];
                            if is_ws(b) || b == b'&' || b == b'>' || b == 0x00 { break }
                            end += 1;
                        }
                        self.attr_value.extend_from_slice(&self.input[start..end]);
                        self.pos = end;
                    }
                    None => { self.finish_attr(); emit_start!(self) }
                }
                State::AttributeValueAfterQuote => match c {
                    Some(x) if is_ws(x) => { self.adv(); self.state = State::AttributeNameBefore; }
                    Some(b'/') => { self.adv(); self.state = State::SelfClosingStart; }
                    Some(b'>') => { self.adv(); emit_start!(self) }
                    Some(_) => {
                        self.finish_attr();
                        self.state = State::AttributeName;
                        self.attr_name.clear();
                        self.attr_name.push(c.unwrap());
                        self.adv();
                    }
                    None => emit_start!(self),
                }
                State::SelfClosingStart => match c {
                    Some(b'>') => {
                        self.adv();
                        if self.in_end_tag {
                            self.in_end_tag = false;
                            self.state = State::Data;
                            self.in_tag = false;
                            return Token::EndTag { name: std::mem::take(&mut self.buf) };
                        }
                        let name = to_lower(&std::mem::take(&mut self.buf));
                        self.last_start_tag = name.clone();
                        self.set_appropriate_end_tag();
                        self.state = State::Data;
                        self.in_tag = false;
                        return Token::StartTag { name, attrs: std::mem::take(&mut self.attrs), self_closing: true };
                    }
                    _ => { self.state = State::AttributeNameBefore; }
                }
                State::BogusComment => match c {
                    Some(b'>') => { self.adv(); self.state = State::Data; self.in_tag = false; return Token::Comment(std::mem::take(&mut self.temp)); }
                    Some(_) => {
                        let start = self.pos;
                        let mut end = start;
                        while end < self.input.len() && self.input[end] != b'>' { end += 1 }
                        self.temp.extend_from_slice(&self.input[start..end]);
                        self.pos = end;
                    }
                    None => { self.state = State::Data; self.in_tag = false; return Token::Comment(std::mem::take(&mut self.temp)); }
                }
                State::MarkupDeclarationOpen => {
                    if self.input[self.pos..].starts_with(b"--") {
                        self.pos += 2; self.temp.clear(); self.in_tag = false; self.in_end_tag = false; self.state = State::CommentStart;
                    } else if self.input[self.pos..].starts_with(b"[CDATA[") {
                        self.pos += 7; self.temp.clear(); self.in_tag = false; self.in_end_tag = false; self.state = State::CdataSection;
                    } else if self.input[self.pos..].starts_with(b"DOCTYPE") {
                        self.pos += 7; self.temp.clear(); self.in_tag = false; self.in_end_tag = false; self.state = State::BeforeDoctypeName;
                        self.dname.clear(); self.force_quirks = false;
                    } else {
                        self.temp.clear(); self.in_tag = true; self.state = State::BogusComment;
                    }
                }
                // ------------------------------------------------ comments
                State::CommentStart => match c {
                    Some(b'-') => { self.adv(); self.state = State::CommentStartDash; }
                    Some(b'>') => { self.adv(); self.state = State::Data; return Token::Comment(std::mem::take(&mut self.temp)); }
                    _ => { self.state = State::Comment; }
                }
                State::CommentStartDash => match c {
                    Some(b'-') => { self.adv(); self.state = State::CommentEnd; }
                    Some(b'>') => { self.adv(); self.state = State::Data; return Token::Comment(std::mem::take(&mut self.temp)); }
                    _ => { self.temp.push(b'-'); self.state = State::Comment; }
                }
                State::Comment => match c {
                    Some(b'<') => { self.adv(); self.temp.push(b'<'); self.state = State::CommentLessThan; }
                    Some(b'-') => { self.adv(); self.state = State::CommentEndDash; }
                    Some(0x00) => { self.adv(); self.temp.extend_from_slice("\u{FFFD}".as_bytes()); }
                    Some(_) => {
                        let start = self.pos;
                        let mut end = start;
                        while end < self.input.len() {
                            let b = self.input[end];
                            if b == b'<' || b == b'-' || b == 0x00 { break }
                            end += 1;
                        }
                        self.temp.extend_from_slice(&self.input[start..end]);
                        self.pos = end;
                    }
                    None => { self.state = State::Data; return Token::Comment(std::mem::take(&mut self.temp)); }
                }
                State::CommentLessThan => match c {
                    Some(b'!') => { self.adv(); self.temp.push(b'!'); self.state = State::CommentLessThanBang; }
                    Some(b'<') => { self.adv(); self.temp.push(b'<'); }
                    _ => { self.state = State::Comment; }
                }
                State::CommentLessThanBang => match c {
                    Some(b'-') => { self.adv(); self.state = State::CommentLessThanBangDash; }
                    _ => { self.state = State::Comment; }
                }
                State::CommentLessThanBangDash => match c {
                    Some(b'-') => { self.adv(); self.state = State::CommentLessThanBangDashDash; }
                    _ => { self.state = State::CommentEndDash; }
                }
                State::CommentLessThanBangDashDash => { self.state = State::CommentEnd; }
                State::CommentEndDash => match c {
                    Some(b'-') => { self.adv(); self.state = State::CommentEnd; }
                    _ => { self.temp.push(b'-'); self.state = State::Comment; }
                }
                State::CommentEnd => match c {
                    Some(b'>') => { self.adv(); self.state = State::Data; return Token::Comment(std::mem::take(&mut self.temp)); }
                    Some(b'!') => { self.adv(); self.state = State::CommentEndBang; }
                    Some(b'-') => { self.adv(); self.temp.push(b'-'); }
                    _ => { self.temp.extend_from_slice(b"--"); self.state = State::Comment; }
                }
                State::CommentEndBang => match c {
                    Some(b'-') => { self.adv(); self.temp.extend_from_slice(b"--!"); self.state = State::CommentEndDash; }
                    Some(b'>') => { self.adv(); self.state = State::Data; return Token::Comment(std::mem::take(&mut self.temp)); }
                    _ => { self.temp.extend_from_slice(b"--!"); self.state = State::Comment; }
                }
                State::CdataSection => match c {
                    Some(b']') => { self.adv(); self.state = State::CdataRightBracket; }
                    Some(_) => {
                        let start = self.pos;
                        let mut end = start;
                        while end < self.input.len() && self.input[end] != b']' { end += 1 }
                        self.temp.extend_from_slice(&self.input[start..end]);
                        self.pos = end;
                    }
                    None => {
                        self.state = State::Data;
                        self.buf.extend_from_slice(b"<![CDATA[");
                        self.buf.extend_from_slice(&std::mem::take(&mut self.temp));
                        return Token::Character(std::mem::take(&mut self.buf));
                    }
                }
                State::CdataRightBracket => match c {
                    Some(b']') => { self.adv(); self.state = State::CdataDoubleRightBracket; }
                    _ => { self.temp.push(b']'); self.state = State::CdataSection; }
                }
                State::CdataDoubleRightBracket => match c {
                    Some(b'>') => { self.adv(); self.state = State::Data; return Token::Character(std::mem::take(&mut self.temp)); }
                    _ => { self.temp.extend_from_slice(b"]"); self.temp.push(b']'); self.state = State::CdataSection; }
                }
                // ------------------------------------------------ doctype
                State::BeforeDoctypeName => match c {
                    Some(x) if is_ws(x) => { self.adv(); }
                    Some(b'>') => { self.adv(); self.state = State::Data; return Token::Doctype { name: Vec::new(), force_quirks: true }; }
                    Some(_) => { self.temp.clear(); self.state = State::DoctypeName; }
                    None => { self.state = State::Data; return Token::Doctype { name: Vec::new(), force_quirks: true }; }
                }
                State::DoctypeName => match c {
                    Some(x) if is_ws(x) => { self.adv(); self.dname.extend_from_slice(&to_lower(&std::mem::take(&mut self.temp))); self.state = State::AfterDoctypeName; }
                    Some(b'>') => { self.adv(); self.dname.extend_from_slice(&to_lower(&std::mem::take(&mut self.temp))); let n = std::mem::take(&mut self.dname); let fq = self.force_quirks; self.state = State::Data; return Token::Doctype { name: n, force_quirks: fq }; }
                    Some(_) => {
                        let start = self.pos;
                        let mut end = start;
                        while end < self.input.len() && !is_ws(self.input[end]) && self.input[end] != b'>' { end += 1 }
                        self.temp.extend_from_slice(&self.input[start..end]);
                        self.pos = end;
                    }
                    None => { self.dname.extend_from_slice(&to_lower(&std::mem::take(&mut self.temp))); let n = std::mem::take(&mut self.dname); self.state = State::Data; return Token::Doctype { name: n, force_quirks: true }; }
                }
                State::AfterDoctypeName => match c {
                    Some(x) if is_ws(x) => { self.adv(); }
                    Some(b'>') => { self.adv(); self.state = State::Data; let n = std::mem::take(&mut self.dname); let fq = self.force_quirks; return Token::Doctype { name: n, force_quirks: fq }; }
                    _ => { self.reconsume(); self.state = State::BogusDoctype; }
                }
                State::AfterDoctypePublicKeyword | State::BeforeDoctypePublicIdentifier => match c {
                    Some(x) if is_ws(x) => {
                        self.adv();
                        if self.state == State::AfterDoctypePublicKeyword { self.state = State::BeforeDoctypePublicIdentifier }
                    }
                    Some(b'"') => { self.adv(); self.temp.clear(); self.state = State::DoctypePublicIdentifierDouble; }
                    Some(b'\'') => { self.adv(); self.temp.clear(); self.state = State::DoctypePublicIdentifierSingle; }
                    Some(b'>') => { self.adv(); self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: true }; }
                    _ => { self.reconsume(); self.state = State::BogusDoctype; }
                }
                State::DoctypePublicIdentifierDouble | State::DoctypePublicIdentifierSingle => {
                    let dq = self.state == State::DoctypePublicIdentifierDouble;
                    match c {
                        Some(x) if x == (if dq { b'"' } else { b'\'' }) => { self.adv(); self.temp.clear(); self.state = State::AfterDoctypePublicIdentifier; }
                        Some(0x00) => { self.adv(); self.temp.extend_from_slice("\u{FFFD}".as_bytes()); }
                        Some(_) => {
                            let q = if dq { b'"' } else { b'\'' };
                            let start = self.pos;
                            let mut end = start;
                            while end < self.input.len() && self.input[end] != q && self.input[end] != 0x00 { end += 1 }
                            self.temp.extend_from_slice(&self.input[start..end]);
                            self.pos = end;
                        }
                        None => { self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: true }; }
                    }
                }
                State::AfterDoctypePublicIdentifier => match c {
                    Some(x) if is_ws(x) => { self.adv(); self.state = State::BetweenDoctypePublicAndSystem; }
                    Some(b'>') => { self.adv(); self.state = State::Data; let n = std::mem::take(&mut self.dname); let fq = self.force_quirks; return Token::Doctype { name: n, force_quirks: fq }; }
                    _ => { self.reconsume(); self.state = State::BogusDoctype; }
                }
                State::BetweenDoctypePublicAndSystem => match c {
                    Some(x) if is_ws(x) => { self.adv(); }
                    Some(b'>') => { self.adv(); self.state = State::Data; let n = std::mem::take(&mut self.dname); let fq = self.force_quirks; return Token::Doctype { name: n, force_quirks: fq }; }
                    Some(b'"') => { self.adv(); self.temp.clear(); self.state = State::DoctypeSystemIdentifierDouble; }
                    Some(b'\'') => { self.adv(); self.temp.clear(); self.state = State::DoctypeSystemIdentifierSingle; }
                    _ => { self.reconsume(); self.state = State::BogusDoctype; }
                }
                State::AfterDoctypeSystemKeyword => match c {
                    Some(x) if is_ws(x) => { self.adv(); self.state = State::BeforeDoctypeSystemIdentifier; }
                    Some(b'"') => { self.adv(); self.temp.clear(); self.state = State::DoctypeSystemIdentifierDouble; }
                    Some(b'\'') => { self.adv(); self.temp.clear(); self.state = State::DoctypeSystemIdentifierSingle; }
                    Some(b'>') => { self.adv(); self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: true }; }
                    _ => { self.reconsume(); self.state = State::BogusDoctype; }
                }
                State::BeforeDoctypeSystemIdentifier => match c {
                    Some(x) if is_ws(x) => { self.adv(); }
                    Some(b'"') => { self.adv(); self.temp.clear(); self.state = State::DoctypeSystemIdentifierDouble; }
                    Some(b'\'') => { self.adv(); self.temp.clear(); self.state = State::DoctypeSystemIdentifierSingle; }
                    Some(b'>') => { self.adv(); self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: true }; }
                    _ => { self.reconsume(); self.state = State::BogusDoctype; }
                }
                State::DoctypeSystemIdentifierDouble | State::DoctypeSystemIdentifierSingle => {
                    let dq = self.state == State::DoctypeSystemIdentifierDouble;
                    match c {
                        Some(x) if x == (if dq { b'"' } else { b'\'' }) => { self.adv(); self.temp.clear(); self.state = State::AfterDoctypeSystemIdentifier; }
                        Some(0x00) => { self.adv(); self.temp.extend_from_slice("\u{FFFD}".as_bytes()); }
                        Some(_) => {
                            let q = if dq { b'"' } else { b'\'' };
                            let start = self.pos;
                            let mut end = start;
                            while end < self.input.len() && self.input[end] != q && self.input[end] != 0x00 { end += 1 }
                            self.temp.extend_from_slice(&self.input[start..end]);
                            self.pos = end;
                        }
                        None => { self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: true }; }
                    }
                }
                State::AfterDoctypeSystemIdentifier => match c {
                    Some(x) if is_ws(x) => { self.adv(); self.state = State::BetweenDoctypeSystemAndSystem; }
                    Some(b'>') => { self.adv(); self.state = State::Data; let n = std::mem::take(&mut self.dname); let fq = self.force_quirks; return Token::Doctype { name: n, force_quirks: fq }; }
                    _ => { self.reconsume(); self.state = State::BogusDoctype; }
                }
                State::BetweenDoctypeSystemAndSystem => match c {
                    Some(x) if is_ws(x) => { self.adv(); }
                    Some(b'>') => { self.adv(); self.state = State::Data; let n = std::mem::take(&mut self.dname); let fq = self.force_quirks; return Token::Doctype { name: n, force_quirks: fq }; }
                    _ => { self.reconsume(); self.state = State::BogusDoctype; }
                }
                State::BogusDoctype => match c {
                    Some(b'>') => { self.adv(); self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: true }; }
                    Some(_) => { self.adv(); }
                    None => { self.state = State::Data; let n = std::mem::take(&mut self.dname); return Token::Doctype { name: n, force_quirks: true }; }
                }
            }
        }
    }
}
