//! HTML tree construction (the tree construction algorithm of the HTML standard).

use crate::tokenizer::{is_alnum, is_alpha, is_ws, Token};
use crate::tokenizer::to_lower;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Ns { Html, Svg, MathMl }

#[derive(Clone, Debug)]
pub enum Node {
    Document,
    DocumentType { name: String },
    Element { name: String, ns: Ns, attrs: Vec<(String, String)>, children: Vec<usize>, content: Option<usize> },
    Text(String),
    Comment(String),
}

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Mode {
    Initial, BeforeHtml, BeforeHead, InHead, InHeadNoscript, AfterHead, InBody,
    Text, InTable, InTableText, InCaption, InColumnGroup, InTableBody, InRow, InCell,
    InSelect, InSelectInTable, InTemplate, AfterBody, InFrameset, AfterFrameset,
    AfterAfterBody, AfterAfterFrameset, ForeignContent,
}

pub struct Tree {
    pub nodes: Vec<Node>,
    modes: Vec<Mode>,
    template_modes: Vec<Mode>,
    open: Vec<usize>,
    pending_table: Vec<u8>,
    foster_parenting: bool,
    in_foreign: bool,
}

fn ws_only(s: &[u8]) -> bool { s.iter().all(|&c| is_ws(c)) }
fn has_ws(s: &[u8]) -> bool { s.iter().any(|&c| is_ws(c)) }

fn local(n: &str) -> &'static str { "x" }

/// Elements that are treated as void when serialized
pub fn is_void(name: &str) -> bool {
    matches!(name, "area" | "base" | "basefont" | "bgsound" | "br" | "col" | "embed"
        | "frame" | "hr" | "img" | "input" | "keygen" | "link" | "meta" | "param"
        | "source" | "track" | "wbr")
}

fn is_void_ns(name: &str, ns: Ns) -> bool {
    if ns == Ns::Svg {
        return matches!(name, "path" | "wbr") || matches!(name, "animate" | "animateTransform"
            | "circle" | "ellipse" | "line" | "polygon" | "polyline" | "rect" | "stop"
            | "use" | "image" | "feImage" | "foreignObject");
    }
    false
}

impl Tree {
    pub fn new() -> Tree {
        Tree {
            nodes: vec![Node::Document],
            modes: vec![Mode::Initial],
            template_modes: Vec::new(),
            open: Vec::new(),
            pending_table: Vec::new(),
            foster_parenting: false,
            in_foreign: false,
        }
    }

    pub fn mode(&self) -> Mode {
        *self.modes.last().unwrap_or(&Mode::Initial)
    }
    fn set_mode(&mut self, m: Mode) {
        *self.modes.last_mut().unwrap() = m;
    }
    pub fn children(&self, n: usize) -> &[usize] {
        match &self.nodes[n] {
            Node::Element { children, .. } | Node::Document => {
                match &self.nodes[n] {
                    Node::Element { children, .. } => children,
                    _ => &[],
                }
            }
            _ => &[],
        }
    }
    fn el_name(&self, n: usize) -> &str {
        match &self.nodes[n] {
            Node::Element { name, .. } => name,
            Node::Document => "#document",
            Node::DocumentType { .. } => "#documentType",
            Node::Text(_) => "#text",
            Node::Comment(_) => "#comment",
        }
    }
    fn el_ns(&self, n: usize) -> Ns {
        match &self.nodes[n] {
            Node::Element { ns, .. } => *ns,
            _ => Ns::Html,
        }
    }

    fn alloc(&mut self, n: Node) -> usize {
        self.nodes.push(n);
        self.nodes.len() - 1
    }

    fn append(&mut self, target: usize, node: usize) {
        match &mut self.nodes[target] {
            Node::Element { children, .. } => children.push(node),
            Node::Document => {}
            _ => {}
        }
    }

    /// Returns the last element in open elements matching the tag name (in scope).
    fn last_element_named(&self, name: &str) -> Option<usize> {
        self.open.iter().rev().find(|&&i| self.el_name(i) == name).copied()
    }
    fn has_element_named(&self, name: &str) -> bool {
        self.open.iter().any(|&i| self.el_name(i) == name)
    }

    fn in_scope(&self, name: &str, list: &[&str]) -> bool {
        for &i in self.open.iter().rev() {
            let n = self.el_name(i);
            if n == name {
                return true;
            }
            if list.contains(&n) {
                return false;
            }
        }
        false
    }
    fn in_button_scope(&self, name: &str) -> bool {
        self.in_scope(name, &["applet", "caption", "html", "table", "td", "th", "marquee", "object", "template"])
    }
    fn in_list_item_scope(&self, name: &str) -> bool {
        self.in_scope(name, &["applet", "caption", "html", "table", "td", "th", "marquee", "object", "ol", "ul"])
    }
    fn in_table_scope(&self, name: &str) -> bool {
        self.in_scope(name, &["html", "table", "template"])
    }
    fn in_select_scope(&self, name: &str) -> bool {
        self.in_scope(name, &["optgroup", "option"])
    }

    fn current(&self) -> usize { *self.open.last().unwrap_or(&0) }

    fn adjusted_insertion_location(&self) -> (usize, Option<usize>) {
        let target = self.current();
        if let Node::Element { content: Some(_), .. } = &self.nodes[target] {
            return (target, None);
        }
        (target, None)
    }

    /// Insert `node` at the appropriate location, honoring foster parenting.
    fn insert_node(&mut self, node: usize) {
        let target = self.current();
        let tname = self.el_name(target).to_string();
        let tns = self.el_ns(target);
        if tns == Ns::Html
            && matches!(tname.as_str(), "table" | "tbody" | "tfoot" | "thead" | "tr")
            && !self.foster_parenting
        {
            if let Node::Element { name, ns } = &self.nodes[node].clone() {
                let ok = ns != &Ns::Html
                    || matches!(name.as_str(), "table" | "caption" | "colgroup" | "col" | "tbody"
                        | "tfoot" | "thead" | "tr" | "td" | "th" | "template" | "script" | "style"
                        | "noscript" | "frameset");
                if !ok {
                    self.foster_parent(node);
                    return;
                }
            }
        }
        self.append(target, node);
    }

    fn foster_parent(&mut self, node: usize) {
        self.foster_parenting = true;
        // last table in table scope
        let mut table = None;
        for &i in self.open.iter().rev() {
            if self.el_name(i) == "table" {
                table = Some(i);
                break;
            }
        }
        match table {
            Some(t) => {
                // insert before the table in its parent
                let parent = self.parent_of(t);
                match parent {
                    Some(p) => {
                        if let Node::Element { children, .. } = &mut self.nodes[p] {
                            if let Some(pos) = children.iter().position(|&c| c == t) {
                                children.insert(pos, node);
                            } else {
                                children.push(node);
                            }
                        }
                    }
                    None => self.append(0, node),
                }
            }
            None => {
                // foster parent into the current node's parent? spec: error, push onto stack
                let target = self.current();
                self.append(target, node);
            }
        }
        self.foster_parenting = false;
    }

    fn parent_of(&self, n: usize) -> Option<usize> {
        fn walk(nodes: &[Node], cur: usize, want: usize) -> Option<usize> {
            match &nodes[cur] {
                Node::Element { children, .. } => {
                    for &c in children {
                        if c == want {
                            return Some(cur);
                        }
                        if let Some(p) = walk(nodes, c, want) {
                            return Some(p);
                        }
                    }
                    None
                }
                Node::Document => {
                    for &c in children(nodes, cur) {
                        if c == want {
                            return Some(cur);
                        }
                        if let Some(p) = walk(nodes, c, want) {
                            return Some(p);
                        }
                    }
                    None
                }
                _ => None,
            }
        }
        fn children(nodes: &[Node], cur: usize) -> &[usize] {
            match &nodes[cur] {
                Node::Element { children, .. } => children,
                _ => &[],
            }
        }
        walk(&self.nodes, 0, n)
    }

    fn insert_text(&mut self, s: &str) {
        if s.is_empty() {
            return;
        }
        let target = self.current();
        if let Node::Element { children, .. } = &mut self.nodes[target] {
            if let Some(&last) = children.last() {
                if let Node::Text(t) = &mut self.nodes[last] {
                    t.push_str(s);
                    return;
                }
            }
        }
        let n = self.alloc(Node::Text(s.to_string()));
        self.insert_node(n);
    }

    fn insert_comment(&mut self, data: &str) {
        let n = self.alloc(Node::Comment(data.to_string()));
        self.insert_node(n);
    }

    fn make_element(&mut self, name: &str, ns: Ns, attrs: Vec<(String, String)>) -> usize {
        self.alloc(Node::Element { name: name.to_string(), ns, attrs, children: Vec::new(), content: None })
    }

    fn pop_until(&mut self, name: &str) {
        while let Some(i) = self.open.pop() {
            self.modes.pop();
            if self.el_name(i) == name {
                break;
            }
        }
    }
    fn pop_one(&mut self) {
        if let Some(_i) = self.open.pop() {
            self.modes.pop();
        }
    }

    fn generate_implied_end_tags(&mut self, except: &[&str]) {
        loop {
            let cur = self.current();
            let name = self.el_name(cur).to_string();
            let implied = match name.as_str() {
                "dd" | "dt" | "li" | "optgroup" | "option" | "p" | "rb" | "rp" | "rt" | "rtc" => true,
                _ => false,
            };
            if implied && !except.contains(&name.as_str()) {
                self.pop_one();
            } else {
                break;
            }
        }
    }

    fn close_p_in_button_scope(&mut self) {
        if self.in_button_scope("p") {
            self.generate_implied_end_tags(&["p"]);
            if self.el_name(self.current()) == "p" {
                self.pop_one();
            }
        }
    }

    fn insert_element_common(&mut self, name: &str, ns: Ns, attrs: Vec<(String, String)>) -> usize {
        let el = self.make_element(name, ns, attrs);
        self.insert_node(el);
        el
    }

    // ---------------------------------------------------------------- main entry
    pub fn process(&mut self, token: Token) {
        if self.in_foreign {
            self.process_foreign(token);
            return;
        }
        let mode = self.mode();
        match token {
            Token::Character(s) => self.process_chars(&s, mode),
            Token::Doctype { name, force_quirks: _ } => self.process_doctype(&name, mode),
            Token::Comment(d) => {
                match mode {
                    Mode::Initial | Mode::BeforeHtml | Mode::AfterAfterBody | Mode::AfterBody => {
                        // html5ever appends comments to the document in some modes
                        match mode {
                            Mode::AfterAfterBody | Mode::AfterBody => {
                                let n = self.alloc(Node::Comment(d));
                                self.append(0, n);
                            }
                            _ => {
                                let n = self.alloc(Node::Comment(d));
                                self.append(0, n);
                            }
                        }
                    }
                    _ => self.insert_comment(&String::from_utf8_lossy(&d)),
                }
            }
            Token::StartTag { name, attrs, self_closing } => {
                self.process_start_tag(&to_lower(&name), attrs, self_closing, mode)
            }
            Token::EndTag { name } => self.process_end_tag(&to_lower(&name), mode),
            Token::Eof => self.process_eof(),
        }
    }

    fn process_chars(&mut self, s: &[u8], mode: Mode) {
        match mode {
            Mode::Initial | Mode::BeforeHtml => {
                if ws_only(s) {
                    return;
                }
                // create html element
                let html = self.insert_element_common("html", Ns::Html, Vec::new());
                self.open.push(html);
                self.modes.push(Mode::BeforeHead);
                self.process(Token::Character(s.to_vec()));
            }
            Mode::BeforeHead => {
                if ws_only(s) {
                    return;
                }
                let head = self.insert_element_common("head", Ns::Html, Vec::new());
                self.open.push(head);
                self.modes.push(Mode::InHead);
                self.process(Token::Character(s.to_vec()));
            }
            Mode::InHead | Mode::InHeadNoscript => {
                if ws_only(s) {
                    self.insert_text(&String::from_utf8_lossy(s));
                    return;
                }
                self.insert_text(&String::from_utf8_lossy(s));
                self.pop_one();
                self.set_mode(Mode::AfterHead);
                self.process(Token::Character(s.to_vec()));
            }
            Mode::AfterHead => {
                if ws_only(s) {
                    self.insert_text(&String::from_utf8_lossy(s));
                    return;
                }
                let body = self.insert_element_common("body", Ns::Html, Vec::new());
                self.open.push(body);
                self.set_mode(Mode::InBody);
                self.process(Token::Character(s.to_vec()));
            }
            Mode::InTable | Mode::InTableBody | Mode::InRow | Mode::InCaption
            | Mode::InColumnGroup | Mode::InCell => {
                if !has_ws(s) {
                    self.pending_table.extend_from_slice(s);
                    self.set_mode(Mode::InTableText);
                    self.flush_pending_table();
                } else {
                    self.pending_table.clear();
                    self.insert_text(&String::from_utf8_lossy(s));
                }
            }
            Mode::AfterAfterBody | Mode::AfterBody => {
                self.insert_text(&String::from_utf8_lossy(s));
            }
            _ => self.insert_text(&String::from_utf8_lossy(s)),
        }
    }

    fn flush_pending_table(&mut self) {
        if self.pending_table.is_empty() {
            return;
        }
        let s = std::mem::take(&mut self.pending_table);
        if ws_only(&s) {
            self.insert_text(&String::from_utf8_lossy(&s));
        } else {
            let t = String::from_utf8_lossy(&s).to_string();
            self.set_mode(Mode::InBody);
            self.pop_until_table();
            self.insert_text(&t);
            self.reconstruct_table_context();
        }
        self.set_mode(Mode::InTable);
    }

    fn pop_until_table(&mut self) {
        loop {
            if self.open.is_empty() {
                break;
            }
            let n = self.el_name(*self.open.last().unwrap()).to_string();
            if n == "table" || n == "template" || n == "html" {
                break;
            }
            self.pop_one();
        }
    }

    fn reconstruct_table_context(&mut self) {
        // re-enter table mode
        let mode = self.mode();
        if matches!(mode, Mode::InBody) {
            // nothing to do; the stack still has table elements? no.
        }
    }

    fn process_doctype(&mut self, name: &[u8], mode: Mode) {
        let n = self.alloc(Node::DocumentType { name: String::from_utf8_lossy(name).to_string() });
        match mode {
            Mode::Initial => {
                self.append(0, n);
                self.set_mode(Mode::BeforeHtml);
            }
            _ => {
                self.append(0, n);
            }
        }
    }

    fn process_start_tag(&mut self, name: &str, attrs: Vec<(Vec<u8>, Vec<u8>)>, self_closing: bool, mode: Mode) {
        let a: Vec<(String, String)> = attrs
            .into_iter()
            .map(|(k, v)| (String::from_utf8_lossy(&k).to_string(), String::from_utf8_lossy(&v).to_string()))
            .collect();
        // foreign content detection
        if mode == Mode::InBody {
            match name {
                "svg" | "math" => {
                    self.start_foreign(name, a, self_closing);
                    return;
                }
                _ => {}
            }
        }
        match mode {
            Mode::Initial | Mode::BeforeHtml => self.process_initial_start_tag(name, a, self_closing),
            Mode::BeforeHead => self.process_before_head_start_tag(name, a, self_closing),
            Mode::InHead | Mode::InHeadNoscript => self.process_in_head_start_tag(name, a, self_closing, mode),
            Mode::AfterHead => self.process_after_head_start_tag(name, a, self_closing),
            Mode::InBody => self.process_in_body_start_tag(name, a, self_closing),
            Mode::Text => self.process_in_body_start_tag(name, a, self_closing),
            Mode::InTable => self.process_in_table_start_tag(name, a, self_closing),
            Mode::InTableText => self.process_in_table_start_tag(name, a, self_closing),
            Mode::InCaption => self.process_in_caption_start_tag(name, a, self_closing),
            Mode::InColumnGroup => self.process_in_column_group_start_tag(name, a, self_closing),
            Mode::InTableBody => self.process_in_table_body_start_tag(name, a, self_closing),
            Mode::InRow => self.process_in_row_start_tag(name, a, self_closing),
            Mode::InCell => self.process_in_cell_start_tag(name, a, self_closing),
            Mode::InSelect | Mode::InSelectInTable => self.process_in_select_start_tag(name, a, self_closing, mode),
            Mode::InTemplate => self.process_in_body_start_tag(name, a, self_closing),
            Mode::AfterBody | Mode::AfterAfterBody => {
                self.process_in_body_start_tag(name, a, self_closing)
            }
            Mode::InFrameset | Mode::AfterFrameset | Mode::AfterAfterFrameset => {
                self.process_in_body_start_tag(name, a, self_closing)
            }
            Mode::ForeignContent => self.process_foreign_start_tag(name, a, self_closing),
        }
    }

    fn process_initial_start_tag(&mut self, name: &str, a: Vec<(String, String)>, _sc: bool) {
        match name {
            "html" => {
                let el = self.insert_element_common("html", Ns::Html, a);
                self.open.push(el);
                self.set_mode(Mode::BeforeHead);
            }
            _ => {
                let el = self.insert_element_common("html", Ns::Html, Vec::new());
                self.open.push(el);
                self.set_mode(Mode::BeforeHead);
                self.process_start_tag(name, a, _sc, Mode::BeforeHead);
            }
        }
    }

    fn process_before_head_start_tag(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match name {
            "head" => {
                let el = self.insert_element_common("head", Ns::Html, a);
                self.open.push(el);
                self.set_mode(Mode::InHead);
            }
            "html" => {
                self.process_start_tag("head", a, sc, Mode::BeforeHead);
            }
            _ => {
                let el = self.insert_element_common("head", Ns::Html, Vec::new());
                self.open.push(el);
                self.set_mode(Mode::InHead);
                self.process_start_tag(name, a, sc, Mode::InHead);
            }
        }
    }

    fn process_after_head_start_tag(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match name {
            "html" => {
                // handled by body creation in html5ever? spec: insert body then process in body
                let body = self.insert_element_common("body", Ns::Html, Vec::new());
                self.open.push(body);
                self.set_mode(Mode::InBody);
                self.process_start_tag(name, a, sc, Mode::InBody);
            }
            _ => {
                let body = self.insert_element_common("body", Ns::Html, Vec::new());
                self.open.push(body);
                self.set_mode(Mode::InBody);
                self.process_start_tag(name, a, sc, Mode::InBody);
            }
        }
    }

    fn process_in_head_start_tag(&mut self, name: &str, a: Vec<(String, String)>, _sc: bool, mode: Mode) {
        match name {
            "html" => {
                self.pop_one();
                self.set_mode(Mode::AfterHead);
                self.process_start_tag(name, a, _sc, Mode::AfterHead);
            }
            "base" | "basefont" | "bgsound" | "link" | "meta" | "title" => {
                let el = self.insert_element_common(name, Ns::Html, a);
                if name == "title" {
                    self.open.push(el);
                    self.modes.push(Mode::Text);
                    self.tokenizer_hint_rcdata();
                }
                if name != "title" {
                    self.pop_one();
                }
            }
            "noscript" if mode == Mode::InHead => {
                let el = self.insert_element_common("noscript", Ns::Html, a);
                self.open.push(el);
                self.modes.push(Mode::InHeadNoscript);
            }
            "noframes" | "style" | "script" | "template" => {
                if name == "template" {
                    let el = self.insert_element_common("template", Ns::Html, a);
                    self.template_modes.push(Mode::InTemplate);
                    self.open.push(el);
                    self.set_mode(Mode::InTemplate);
                    return;
                }
                let el = self.insert_element_common(name, Ns::Html, a);
                self.open.push(el);
                self.modes.push(Mode::Text);
                if name == "script" {
                    self.tokenizer_hint_script();
                } else if name == "style" || name == "noframes" {
                    self.tokenizer_hint_rawtext();
                }
            }
            "head" => {
                self.pop_one();
                self.process_start_tag("head", a, _sc, Mode::InHead);
            }
            _ => {
                self.pop_one();
                self.set_mode(Mode::AfterHead);
                self.process_start_tag(name, a, _sc, Mode::AfterHead);
            }
        }
    }

    // hints used by the driver to switch the tokenizer state
    fn tokenizer_hint_rcdata(&mut self) {}
    fn tokenizer_hint_rawtext(&mut self) {}
    fn tokenizer_hint_script(&mut self) {}

    fn process_in_table_start_tag(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match name {
            "caption" | "col" | "colgroup" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr" => {
                self.pop_until_table();
                self.set_mode(Mode::InTable);
                self.process_start_tag(name, a, sc, Mode::InTable);
            }
            "style" | "script" | "template" => {
                self.process_start_tag(name, a, sc, Mode::InHead);
            }
            "input" => {
                let hidden = a.iter().any(|(k, v)| k == "type" && v.eq_ignore_ascii_case("hidden"));
                if hidden {
                    self.insert_element_common("input", Ns::Html, a);
                    self.pop_one();
                } else {
                    self.foster_parent_start(name, a, sc);
                }
            }
            "form" => {
                if self.has_element_named("template") {
                    let el = self.insert_element_common("form", Ns::Html, a);
                    self.open.push(el);
                    self.pop_one();
                } else {
                    self.foster_parent_start(name, a, sc);
                }
            }
            "table" => {
                self.pop_until_table();
                self.set_mode(Mode::InTable);
                self.process_start_tag(name, a, sc, Mode::InBody);
            }
            _ => self.foster_parent_start(name, a, sc),
        }
    }

    fn foster_parent_start(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        // foster parent: process using in body rules after popping out of table
        let el = self.make_element(name, Ns::Html, a);
        self.insert_node(el);
        if !self.is_void_tag(name) {
            self.open.push(el);
            self.modes.push(Mode::InBody);
        }
        let _ = sc;
    }

    fn is_void_tag(&self, name: &str) -> bool {
        matches!(name, "area" | "base" | "basefont" | "bgsound" | "br" | "col" | "embed" | "frame"
            | "hr" | "img" | "input" | "keygen" | "link" | "meta" | "param" | "source" | "track" | "wbr")
    }

    fn process_in_caption_start_tag(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match name {
            "caption" | "col" | "colgroup" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr" => {
                self.pop_until_named("caption");
                self.set_mode(Mode::InTable);
                self.process_start_tag(name, a, sc, Mode::InTable);
            }
            _ => self.process_in_body_start_tag(name, a, sc),
        }
    }

    fn process_in_column_group_start_tag(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match name {
            "html" => { self.pop_one(); self.process_start_tag(name, a, sc, Mode::InColumnGroup) }
            "col" => { self.insert_element_common("col", Ns::Html, a); self.pop_one(); }
            "template" => self.process_start_tag(name, a, sc, Mode::InHead),
            "colgroup" => {
                if !self.has_current("colgroup") {
                    self.pop_one();
                    self.set_mode(Mode::InTable);
                    self.process_start_tag(name, a, sc, Mode::InTable);
                } else {
                    self.insert_element_common("colgroup", Ns::Html, a);
                    self.pop_one();
                }
            }
            _ => {
                self.pop_one();
                self.set_mode(Mode::InTable);
                self.process_start_tag(name, a, sc, Mode::InTable);
            }
        }
    }

    fn has_current(&self, name: &str) -> bool {
        self.el_name(self.current()) == name
    }

    fn process_in_table_body_start_tag(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match name {
            "tr" => {
                self.pop_until_named_any(&["tbody", "tfoot", "thead", "template", "html"]);
                self.set_mode(Mode::InRow);
                self.process_start_tag(name, a, sc, Mode::InRow);
            }
            "th" | "td" => {
                self.pop_until_named_any(&["tbody", "tfoot", "thead", "template", "html"]);
                self.set_mode(Mode::InRow);
                self.process_start_tag("tr", Vec::new(), false, Mode::InRow);
                self.process_start_tag(name, a, sc, Mode::InRow);
            }
            "caption" | "col" | "colgroup" | "tbody" | "tfoot" | "thead" => {
                self.pop_until_named_any(&["tbody", "tfoot", "thead", "template", "html"]);
                self.set_mode(Mode::InTable);
                self.process_start_tag(name, a, sc, Mode::InTable);
            }
            _ => self.process_in_table_start_tag(name, a, sc),
        }
    }

    fn process_in_row_start_tag(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match name {
            "th" | "td" => {
                self.pop_until_named_any(&["tr", "template", "html"]);
                self.set_mode(Mode::InCell);
                self.process_start_tag(name, a, sc, Mode::InCell);
            }
            "caption" | "col" | "colgroup" | "tbody" | "tfoot" | "thead" | "tr" => {
                self.pop_until_named_any(&["tr", "template", "html"]);
                self.set_mode(Mode::InTableBody);
                self.process_start_tag(name, a, sc, Mode::InTableBody);
            }
            _ => self.process_in_table_start_tag(name, a, sc),
        }
    }

    fn process_in_cell_start_tag(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match name {
            "caption" | "col" | "colgroup" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr" => {
                if self.in_table_scope("td") || self.in_table_scope("th") {
                    self.close_cell();
                    self.process_start_tag(name, a, sc, Mode::InTable);
                }
            }
            _ => self.process_in_body_start_tag(name, a, sc),
        }
    }

    fn close_cell(&mut self) {
        self.generate_implied_end_tags(&[]);
        while !self.open.is_empty() {
            let n = self.el_name(*self.open.last().unwrap()).to_string();
            self.pop_one();
            if n == "td" || n == "th" {
                break;
            }
        }
    }

    fn pop_until_named(&mut self, name: &str) {
        loop {
            if self.open.is_empty() { break }
            let n = self.el_name(*self.open.last().unwrap()).to_string();
            self.pop_one();
            if n == name { break }
        }
    }
    fn pop_until_named_any(&mut self, names: &[&str]) {
        loop {
            if self.open.is_empty() { break }
            let n = self.el_name(*self.open.last().unwrap()).to_string();
            self.pop_one();
            if names.contains(&n.as_str()) { break }
        }
    }

    fn process_in_select_start_tag(&mut self, name: &str, a: Vec<(String, String)>, _sc: bool, mode: Mode) {
        match name {
            "html" => {
                self.pop_one();
                self.set_mode(Mode::InBody);
                self.process_start_tag(name, a, _sc, Mode::InBody);
            }
            "option" => {
                if self.has_current("option") {
                    self.pop_one();
                }
                let el = self.insert_element_common("option", Ns::Html, a);
                self.open.push(el);
            }
            "optgroup" => {
                if self.has_current("option") {
                    self.pop_one();
                }
                if self.has_current("optgroup") {
                    self.pop_one();
                }
                let el = self.insert_element_common("optgroup", Ns::Html, a);
                self.open.push(el);
            }
            "select" => {
                if !self.in_select_scope("select") {
                    self.pop_until_named("select");
                }
            }
            "input" | "keygen" | "textarea" => {
                if !self.in_select_scope("select") {
                    self.pop_until_named("select");
                    self.set_mode(Mode::InBody);
                    self.process_start_tag(name, a, _sc, Mode::InBody);
                }
            }
            "script" | "template" => self.process_start_tag(name, a, _sc, Mode::InHead),
            _ => {}
        }
        let _ = mode;
    }

    fn process_end_tag(&mut self, name: &str, mode: Mode) {
        match mode {
            Mode::Initial | Mode::BeforeHtml => {}
            Mode::BeforeHead => {
                if name == "head" || name == "body" || name == "html" || name == "br" {}
                else {
                    let el = self.insert_element_common("head", Ns::Html, Vec::new());
                    self.open.push(el);
                    self.set_mode(Mode::InHead);
                    self.process_end_tag(name, Mode::InHead);
                }
            }
            Mode::InHead | Mode::InHeadNoscript => self.process_in_head_end_tag(name),
            Mode::AfterHead => {
                if name == "body" {
                    let body = self.insert_element_common("body", Ns::Html, Vec::new());
                    self.open.push(body);
                    self.set_mode(Mode::InBody);
                } else {
                    let body = self.insert_element_common("body", Ns::Html, Vec::new());
                    self.open.push(body);
                    self.set_mode(Mode::InBody);
                    self.process_end_tag(name, Mode::InBody);
                }
            }
            Mode::InBody => self.process_in_body_end_tag(name),
            Mode::Text => self.process_text_end_tag(name),
            Mode::InTable | Mode::InTableText => self.process_in_table_end_tag(name),
            Mode::InCaption => self.process_in_caption_end_tag(name),
            Mode::InColumnGroup => self.process_in_column_group_end_tag(name),
            Mode::InTableBody => self.process_in_table_body_end_tag(name),
            Mode::InRow => self.process_in_row_end_tag(name),
            Mode::InCell => self.process_in_cell_end_tag(name),
            Mode::InSelect | Mode::InSelectInTable => self.process_in_select_end_tag(name, mode),
            Mode::InTemplate => self.process_in_body_end_tag(name),
            Mode::AfterBody => {
                if name == "html" {
                    // spec: switch to after after body
                    self.modes.pop();
                    self.modes.push(Mode::AfterAfterBody);
                } else {
                    self.process_in_body_end_tag(name);
                }
            }
            Mode::InFrameset | Mode::AfterFrameset | Mode::AfterAfterFrameset => {
                self.process_in_body_end_tag(name)
            }
            Mode::AfterAfterBody => self.process_in_body_end_tag(name),
            Mode::ForeignContent => self.process_foreign_end_tag(name),
        }
    }

    fn process_in_head_end_tag(&mut self, name: &str) {
        match name {
            "head" => { self.pop_one(); self.set_mode(Mode::AfterHead); }
            "body" | "html" | "br" => {
                self.pop_one();
                self.set_mode(Mode::AfterHead);
                self.process_end_tag(name, Mode::AfterHead);
            }
            "template" => {
                if self.has_element_named("template") {
                    self.pop_until_named("template");
                }
            }
            _ => {
                self.pop_one();
                self.set_mode(Mode::AfterHead);
                self.process_end_tag(name, Mode::AfterHead);
            }
        }
    }

    fn process_text_end_tag(&mut self, name: &str) {
        let last = *self.open.last().unwrap_or(&0);
        let lname = self.el_name(last).to_string();
        self.pop_one();
        if lname != name {
            self.set_mode(Mode::InBody);
            self.process_end_tag(name, Mode::InBody);
        }
    }

    fn process_in_table_end_tag(&mut self, name: &str) {
        match name {
            "table" => {
                if self.in_table_scope("table") {
                    self.pop_until_named("table");
                    self.reset_insertion_mode();
                }
            }
            "body" | "caption" | "col" | "colgroup" | "html" | "tbody" | "td" | "tfoot" | "th"
            | "thead" | "tr" => {}
            "template" => {
                if self.has_element_named("template") {
                    self.pop_until_named("template");
                }
            }
            _ => {
                self.set_mode(Mode::InBody);
                self.process_end_tag(name, Mode::InBody);
            }
        }
    }

    fn process_in_caption_end_tag(&mut self, name: &str) {
        match name {
            "caption" => {
                if self.in_table_scope("caption") {
                    self.generate_implied_end_tags(&[]);
                    self.pop_until_named("caption");
                    self.set_mode(Mode::InTable);
                }
            }
            "table" => {
                if self.in_table_scope("caption") {
                    self.generate_implied_end_tags(&[]);
                    self.pop_until_named("caption");
                    self.set_mode(Mode::InTable);
                    self.process_end_tag(name, Mode::InTable);
                }
            }
            "body" | "col" | "colgroup" | "html" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr" => {}
            _ => self.process_in_body_end_tag(name),
        }
    }

    fn process_in_column_group_end_tag(&mut self, name: &str) {
        match name {
            "colgroup" => {
                if self.has_current("colgroup") {
                    self.pop_one();
                    self.set_mode(Mode::InTable);
                }
            }
            "col" => {}
            _ => {
                if self.has_current("colgroup") {
                    self.pop_one();
                    self.set_mode(Mode::InTable);
                    self.process_end_tag(name, Mode::InTable);
                }
            }
        }
    }

    fn process_in_table_body_end_tag(&mut self, name: &str) {
        match name {
            "tbody" | "tfoot" | "thead" => {
                if self.in_table_scope(name) {
                    self.clear_stack_to_table_body_context();
                    self.pop_one();
                    self.set_mode(Mode::InTable);
                }
            }
            "table" => {
                if self.in_table_scope("table") {
                    self.clear_stack_to_table_context();
                    self.pop_one();
                    self.set_mode(Mode::InTable);
                    self.process_end_tag(name, Mode::InTable);
                }
            }
            "body" | "caption" | "col" | "colgroup" | "html" | "td" | "th" | "tr" => {}
            _ => self.process_in_table_end_tag(name),
        }
    }

    fn clear_stack_to_table_body_context(&mut self) {
        while !self.open.is_empty() {
            let n = self.el_name(*self.open.last().unwrap()).to_string();
            if matches!(n.as_str(), "tbody" | "tfoot" | "thead" | "template" | "html") {
                break;
            }
            self.pop_one();
        }
    }
    fn clear_stack_to_table_context(&mut self) {
        while !self.open.is_empty() {
            let n = self.el_name(*self.open.last().unwrap()).to_string();
            if matches!(n.as_str(), "table" | "template" | "html") {
                break;
            }
            self.pop_one();
        }
    }
    fn clear_stack_to_table_row_context(&mut self) {
        while !self.open.is_empty() {
            let n = self.el_name(*self.open.last().unwrap()).to_string();
            if matches!(n.as_str(), "tr" | "template" | "html") {
                break;
            }
            self.pop_one();
        }
    }

    fn process_in_row_end_tag(&mut self, name: &str) {
        match name {
            "tr" => {
                if self.in_table_scope("tr") {
                    self.clear_stack_to_table_row_context();
                    self.pop_one();
                    self.set_mode(Mode::InTableBody);
                }
            }
            "table" => {
                if self.in_table_scope("tr") {
                    self.clear_stack_to_table_row_context();
                    self.pop_one();
                    self.set_mode(Mode::InTableBody);
                    self.process_end_tag(name, Mode::InTableBody);
                }
            }
            "tbody" | "tfoot" | "thead" => {
                if self.in_table_scope(name) {
                    self.clear_stack_to_table_row_context();
                    self.pop_one();
                    self.set_mode(Mode::InTableBody);
                    self.process_end_tag(name, Mode::InTableBody);
                }
            }
            "body" | "caption" | "col" | "colgroup" | "html" | "td" | "th" => {}
            _ => self.process_in_table_end_tag(name),
        }
    }

    fn process_in_cell_end_tag(&mut self, name: &str) {
        match name {
            "td" | "th" => {
                let n = if name == "td" { "th" } else { "td" };
                if self.in_table_scope(name) || self.in_table_scope(n) {
                    self.close_cell();
                    self.set_mode(Mode::InRow);
                }
            }
            "body" | "caption" | "col" | "colgroup" | "html" => {}
            "table" | "tbody" | "tfoot" | "thead" | "tr" => {
                if self.in_table_scope(name) {
                    self.close_cell();
                    self.process_end_tag(name, Mode::InRow);
                }
            }
            _ => self.process_in_body_end_tag(name),
        }
    }

    fn process_in_select_end_tag(&mut self, name: &str, mode: Mode) {
        match name {
            "optgroup" => {
                if self.has_current("option") {
                    self.pop_one();
                }
                if self.has_current("optgroup") {
                    self.pop_one();
                }
            }
            "option" => {
                if self.has_current("option") {
                    self.pop_one();
                }
            }
            "select" => {
                if self.in_select_scope("select") {
                    self.pop_until_named("select");
                    self.set_mode(Mode::InBody);
                }
            }
            _ => {}
        }
        let _ = mode;
    }

    fn reset_insertion_mode(&mut self) {
        // find the last table/html/template on the stack and set the mode accordingly
        let mut i = self.open.len();
        while i > 0 {
            i -= 1;
            let n = self.el_name(self.open[i]).to_string();
            let m = match n.as_str() {
                "select" => Mode::InSelect,
                "td" | "th" => Mode::InCell,
                "tr" => Mode::InRow,
                "tbody" | "thead" | "tfoot" => Mode::InTableBody,
                "caption" => Mode::InCaption,
                "colgroup" => Mode::InColumnGroup,
                "table" => Mode::InTable,
                "template" => Mode::InTemplate,
                "body" => Mode::InBody,
                "frameset" => Mode::InFrameset,
                "head" => Mode::InHead,
                "html" => Mode::BeforeHead,
                _ => continue,
            };
            self.set_mode(m);
            return;
        }
        self.set_mode(Mode::InBody);
    }

    fn process_in_body_start_tag(&mut self, name: &str, a: Vec<(String, String)>, _sc: bool) {
        match name {
            "html" => {
                if self.has_element_named("template") {
                    self.insert_element_common("html", Ns::Html, a);
                }
            }
            "base" | "basefont" | "bgsound" | "link" | "meta" | "noframes" | "script"
            | "style" | "template" | "title" => {
                if name == "template" {
                    let el = self.insert_element_common("template", Ns::Html, a);
                    self.template_modes.push(Mode::InTemplate);
                    self.open.push(el);
                    self.modes.push(Mode::InTemplate);
                    return;
                }
                let el = self.insert_element_common(name, Ns::Html, a);
                if name == "title" {
                    self.open.push(el);
                    self.modes.push(Mode::Text);
                    self.tokenizer_hint_rcdata();
                } else if name == "script" {
                    self.open.push(el);
                    self.modes.push(Mode::Text);
                    self.tokenizer_hint_script();
                } else if name == "style" || name == "noframes" {
                    self.open.push(el);
                    self.modes.push(Mode::Text);
                    self.tokenizer_hint_rawtext();
                } else {
                    self.pop_one();
                }
            }
            "body" => {
                if self.open.len() > 1 && self.el_name(self.open[1]) == "body"
                    && self.open.len() > 2
                {
                    // ignore
                } else if self.has_element_named("template") {
                    self.insert_element_common("body", Ns::Html, a);
                } else {
                    // ignore
                }
            }
            "frameset" => {
                // rare
                self.insert_element_common("frameset", Ns::Html, a);
                self.open.push(self.nodes.len() - 1);
                self.set_mode(Mode::InFrameset);
            }
            "address" | "article" | "aside" | "blockquote" | "center" | "details" | "dialog"
            | "dir" | "div" | "dl" | "fieldset" | "figcaption" | "figure" | "footer" | "header"
            | "hgroup" | "main" | "menu" | "nav" | "ol" | "p" | "section" | "summary" | "ul" => {
                if self.in_button_scope("p") {
                    self.close_p_in_button_scope();
                }
                let el = self.insert_element_common(name, Ns::Html, a);
                self.open.push(el);
            }
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                if self.in_button_scope("p") {
                    self.close_p_in_button_scope();
                }
                let cur = self.current();
                let cn = self.el_name(cur);
                if matches!(cn, "h1" | "h2" | "h3" | "h4" | "h5" | "h6") {
                    self.pop_one();
                }
                let el = self.insert_element_common(name, Ns::Html, a);
                self.open.push(el);
            }
            "pre" | "listing" => {
                if self.in_button_scope("p") {
                    self.close_p_in_button_scope();
                }
                let el = self.insert_element_common(name, Ns::Html, a);
                self.open.push(el);
                self.skip_next_newline = true;
            }
            "form" => {
                if !self.has_element_named("template") {
                    self.form_element = None;
                }
                if self.form_element.is_none() {
                    let el = self.insert_element_common("form", Ns::Html, a);
                    self.form_element = Some(el);
                    self.open.push(el);
                }
            }
            "li" => {
                if self.in_list_item_scope("li") {
                    self.generate_implied_end_tags(&["li"]);
                    if self.el_name(self.current()) == "li" {
                        self.pop_one();
                    }
                }
                let el = self.insert_element_common("li", Ns::Html, a);
                self.open.push(el);
            }
            "dd" | "dt" => {
                if self.in_list_item_scope(name) {
                    self.generate_implied_end_tags(&[name]);
                    let cur = self.el_name(self.current()).to_string();
                    if cur == name {
                        self.pop_one();
                    }
                }
                let el = self.insert_element_common(name, Ns::Html, a);
                self.open.push(el);
            }
            "plaintext" => {
                if self.in_button_scope("p") {
                    self.close_p_in_button_scope();
                }
                let el = self.insert_element_common("plaintext", Ns::Html, a);
                self.open.push(el);
                self.modes.push(Mode::Text);
                self.tokenizer_hint_plaintext();
            }
            "button" => {
                if self.in_button_scope("button") {
                    self.generate_implied_end_tags(&[]);
                    if self.el_name(self.current()) == "button" {
                        self.pop_one();
                    }
                }
                let el = self.insert_element_common("button", Ns::Html, a);
                self.open.push(el);
            }
            "a" => {
                if let Some(node) = self.last_element_named("a") {
                    // adoption agency (simplified): close the a
                    let _ = node;
                    self.adoption_agency("a");
                }
                let el = self.insert_element_common("a", Ns::Html, a);
                self.open.push(el);
            }
            "b" | "big" | "code" | "em" | "font" | "i" | "s" | "small" | "strike" | "strong"
            | "tt" | "u" => {
                if let Some(node) = self.last_element_named(name) {
                    let _ = node;
                    self.adoption_agency(name);
                }
                let el = self.insert_element_common(name, Ns::Html, a);
                self.open.push(el);
            }
            "nobr" => {
                let el = self.insert_element_common("nobr", Ns::Html, a);
                self.open.push(el);
            }
            "applet" | "marquee" | "object" => {
                self.reconstruct_formatting();
                let el = self.insert_element_common(name, Ns::Html, a);
                self.open.push(el);
                self.marker = true;
            }
            "table" => {
                if !self.quirks {
                    if self.in_button_scope("p") {
                        self.close_p_in_button_scope();
                    }
                }
                let el = self.insert_element_common("table", Ns::Html, a);
                self.open.push(el);
                self.set_mode(Mode::InTable);
            }
            "area" | "br" | "embed" | "img" | "keygen" | "wbr" => {
                self.reconstruct_formatting();
                self.insert_element_common(name, Ns::Html, a);
                self.pop_one();
            }
            "input" => {
                self.insert_element_common("input", Ns::Html, a);
                self.pop_one();
            }
            "param" | "source" | "track" => {
                self.insert_element_common(name, Ns::Html, a);
                self.pop_one();
            }
            "hr" => {
                if self.in_button_scope("p") {
                    self.close_p_in_button_scope();
                }
                self.insert_element_common("hr", Ns::Html, a);
                self.pop_one();
            }
            "image" => {
                self.process_in_body_start_tag("img", a, _sc);
            }
            "textarea" => {
                let el = self.insert_element_common("textarea", Ns::Html, a);
                self.open.push(el);
                self.skip_next_newline = true;
                self.modes.push(Mode::Text);
                self.tokenizer_hint_rcdata();
            }
            "xmp" => {
                if self.in_button_scope("p") {
                    self.close_p_in_button_scope();
                }
                let el = self.insert_element_common("xmp", Ns::Html, a);
                self.open.push(el);
                self.modes.push(Mode::Text);
                self.tokenizer_hint_rawtext();
            }
            "iframe" => {
                let el = self.insert_element_common("iframe", Ns::Html, a);
                self.open.push(el);
                self.modes.push(Mode::Text);
                self.tokenizer_hint_rawtext();
            }
            "noembed" => {
                let el = self.insert_element_common("noembed", Ns::Html, a);
                self.open.push(el);
                self.modes.push(Mode::Text);
                self.tokenizer_hint_rawtext();
            }
            "noscript" => {
                let el = self.insert_element_common("noscript", Ns::Html, a);
                self.open.push(el);
            }
            "select" => {
                if self.in_button_scope("select") {
                    self.pop_one();
                }
                let el = self.insert_element_common("select", Ns::Html, a);
                self.open.push(el);
                self.set_mode(Mode::InSelect);
            }
            "optgroup" | "option" => {
                if self.has_current("option") {
                    self.pop_one();
                }
                let el = self.insert_element_common(name, Ns::Html, a);
                self.open.push(el);
            }
            "rb" | "rtc" => {
                if self.in_scope(name, &[]) {
                    self.generate_implied_end_tags(&[]);
                    self.pop_one();
                }
                let el = self.insert_element_common(name, Ns::Html, a);
                self.open.push(el);
            }
            "rp" | "rt" => {
                if self.in_scope("rtc", &[]) {
                    self.generate_implied_end_tags(&[]);
                }
                let el = self.insert_element_common(name, Ns::Html, a);
                self.open.push(el);
            }
            "math" | "svg" => { self.start_foreign(name, a, _sc); }
            "caption" | "col" | "colgroup" | "frame" | "head" | "tbody" | "td" | "tfoot"
            | "th" | "thead" | "tr" => {}
            _ => {
                self.reconstruct_formatting();
                let el = self.insert_element_common(name, Ns::Html, a);
                self.open.push(el);
            }
        }
    }

    fn reconstruct_formatting(&mut self) {}

    fn adoption_agency(&mut self, subject: &str) {
        // simplified version of the adoption agency algorithm
        if let Some(furthest) = self.last_element_named(subject) {
            // close formatting element
            let mut common = furthest;
            let mut idx = self.open.iter().position(|&x| x == furthest).unwrap();
            // close everything from the common ancestor down
            for i in (idx + 1)..self.open.len() {
                let _ = i;
            }
            let _ = &mut common;
            // reparent children
            self.pop_from(idx);
        }
    }

    fn pop_from(&mut self, idx: usize) {
        while self.open.len() > idx {
            self.pop_one();
        }
    }

    pub skip_next_newline: bool,
    pub quirks: bool,
    pub form_element: Option<usize>,
    pub marker: bool,

    fn process_in_body_end_tag(&mut self, name: &str) {
        match name {
            "template" => {
                if self.has_element_named("template") {
                    self.pop_until_named("template");
                }
            }
            "p" => {
                if self.in_button_scope("p") {
                    self.generate_implied_end_tags(&["p"]);
                    if self.el_name(self.current()) == "p" {
                        self.pop_one();
                    }
                }
            }
            "body" => {
                if self.in_scope("body", &[]) {
                    self.generate_implied_end_tags(&[]);
                    if self.el_name(self.current()) == "body" {
                        self.pop_one();
                    }
                }
            }
            "html" => {
                if self.in_scope("body", &[]) {
                    self.process_end_tag("body", Mode::InBody);
                    self.process_end_tag("html", Mode::AfterBody);
                }
            }
            "address" | "article" | "aside" | "blockquote" | "button" | "center" | "details"
            | "dialog" | "dir" | "div" | "dl" | "fieldset" | "figcaption" | "figure" | "footer"
            | "header" | "hgroup" | "listing" | "main" | "menu" | "nav" | "ol" | "pre"
            | "section" | "summary" | "ul" => {
                if self.in_scope(name, &[]) {
                    self.generate_implied_end_tags(&[]);
                    if self.el_name(self.current()) == name {
                        self.pop_one();
                    }
                }
            }
            "form" => {
                if self.has_element_named("template") {
                    if self.in_scope("form", &[]) {
                        self.generate_implied_end_tags(&[]);
                        if self.el_name(self.current()) == "form" {
                            self.pop_one();
                        }
                    }
                } else if self.form_element.is_some() && self.in_scope("form", &[]) {
                    self.generate_implied_end_tags(&[]);
                    if self.el_name(self.current()) == "form" {
                        self.pop_one();
                    }
                }
            }
            "li" => {
                if self.in_list_item_scope("li") {
                    self.generate_implied_end_tags(&["li"]);
                    if self.el_name(self.current()) == "li" {
                        self.pop_one();
                    }
                }
            }
            "dd" | "dt" => {
                if self.in_list_item_scope(name) {
                    self.generate_implied_end_tags(&[name]);
                    if self.el_name(self.current()) == name {
                        self.pop_one();
                    }
                }
            }
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                if self.in_scope(name, &[]) {
                    self.generate_implied_end_tags(&[]);
                    if self.el_name(self.current()) == name {
                        self.pop_one();
                    }
                }
            }
            "a" | "b" | "big" | "code" | "em" | "font" | "i" | "nobr" | "s" | "small"
            | "strike" | "strong" | "tt" | "u" => {
                self.adoption_agency(name);
            }
            "applet" | "marquee" | "object" => {
                if self.in_scope(name, &[]) {
                    self.generate_implied_end_tags(&[]);
                    if self.el_name(self.current()) == name {
                        self.pop_one();
                    }
                }
            }
            "br" => {
                if self.in_scope(name, &[]) {
                    self.process_in_body_start_tag("br", Vec::new(), false);
                }
            }
            _ => {
                // any other end tag: close matching element if any
                let mut i = self.open.len();
                while i > 0 {
                    i -= 1;
                    if self.el_name(self.open[i]) == name {
                        self.generate_implied_end_tags(&[]);
                        self.pop_until_named(name);
                        break;
                    }
                }
            }
        }
    }

    fn process_eof(&mut self) {
        let mode = self.mode();
        match mode {
            Mode::Initial | Mode::BeforeHtml => {
                let el = self.insert_element_common("html", Ns::Html, Vec::new());
                self.open.push(el);
                self.modes.push(Mode::BeforeHead);
                let head = self.insert_element_common("head", Ns::Html, Vec::new());
                self.open.push(head);
                self.modes.push(Mode::InHead);
                self.pop_one();
                self.set_mode(Mode::AfterHead);
                let body = self.insert_element_common("body", Ns::Html, Vec::new());
                self.open.push(body);
                self.set_mode(Mode::InBody);
            }
            Mode::BeforeHead => {
                let head = self.insert_element_common("head", Ns::Html, Vec::new());
                self.open.push(head);
                self.modes.push(Mode::InHead);
                self.pop_one();
                self.set_mode(Mode::AfterHead);
                let body = self.insert_element_common("body", Ns::Html, Vec::new());
                self.open.push(body);
                self.set_mode(Mode::InBody);
            }
            Mode::InHead | Mode::InHeadNoscript => {
                self.pop_one();
                self.set_mode(Mode::AfterHead);
                let body = self.insert_element_common("body", Ns::Html, Vec::new());
                self.open.push(body);
                self.set_mode(Mode::InBody);
            }
            Mode::AfterHead => {
                let body = self.insert_element_common("body", Ns::Html, Vec::new());
                self.open.push(body);
                self.set_mode(Mode::InBody);
            }
            _ => {
                self.generate_implied_end_tags(&[]);
            }
        }
    }

    // ------------------------------------------------------------- foreign content
    fn start_foreign(&mut self, name: &str, a: Vec<(String, String)>, _sc: bool) {
        let ns = if name == "svg" { Ns::Svg } else { Ns::MathMl };
        let a2 = adjust_attributes(&a, ns);
        let el = self.make_element(name, ns, a2);
        self.insert_node(el);
        self.open.push(el);
        self.modes.push(Mode::ForeignContent);
        self.in_foreign = true;
        self.foreign_break_out = None;
    }

    pub foreign_break_out: Option<String>,

    fn process_foreign(&mut self, token: Token) {
        match token {
            Token::Character(s) => {
                if ws_only(&s) {
                    self.insert_text(&String::from_utf8_lossy(&s));
                } else {
                    self.insert_text(&String::from_utf8_lossy(&s));
                }
            }
            Token::Comment(d) => self.insert_comment(&String::from_utf8_lossy(&d)),
            Token::Doctype { name, .. } => {
                let n = self.alloc(Node::DocumentType { name: String::from_utf8_lossy(&name).to_string() });
                self.insert_node(n);
            }
            Token::StartTag { name, attrs, .. } => {
                self.process_foreign_start_tag(&to_lower(&name), attrs, false)
            }
            Token::EndTag { name } => self.process_foreign_end_tag(&to_lower(&name)),
            Token::Eof => self.process_eof(),
        }
    }

    fn process_foreign_start_tag(&mut self, name: &str, a: Vec<(String, String)>, _sc: bool) {
        let ns = self.el_ns(self.current());
        let ns2 = if name == "svg" { Ns::Svg } else if name == "math" { Ns::MathMl } else { ns };
        let a2 = adjust_attributes(&a, ns2);
        let adj = adjusted_foreign_tag_name(name, ns2);
        let el = self.make_element(&adj, ns2, a2);
        self.insert_node(el);
        if !self.is_void_tag(&adj) && !matches!(adj.as_str(), "rect" | "circle" | "line" | "path" | "polyline" | "polygon" | "ellipse" | "use" | "image" | "stop" | "animate" | "animateTransform" | "feImage" | "foreignObject") {
            self.open.push(el);
        }
        // break out of foreign content?
        let _ = ns2;
    }

    fn process_foreign_end_tag(&mut self, name: &str) {
        // only allowed for the current foreign element
        let cur = self.current();
        let cn = self.el_name(cur).to_string();
        let ns = self.el_ns(cur);
        let adj = adjusted_foreign_tag_name(name, ns);
        if adj == cn || matches!(name, "svg" | "math" | "annotation-xml" | "mglyph" | "malignmark") {
            self.pop_one();
            if self.el_ns(self.current()) == Ns::Html {
                self.in_foreign = false;
                self.reset_insertion_mode();
            }
        } else {
            // ignore
        }
    }

    fn tokenizer_hint_plaintext(&mut self) {}
}

fn adjust_attributes(a: &[(String, String)], ns: Ns) -> Vec<(String, String)> {
    a.iter()
        .map(|(k, v)| {
            let nk = match ns {
                Ns::Svg => adjust_svg_attr(k),
                Ns::MathMl => adjust_mathml_attr(k),
                _ => k.clone(),
            };
            (nk, v.clone())
        })
        .collect()
}

fn adjust_svg_attr(k: &str) -> String {
    match k {
        "xlink:actuate" | "xlink:arcrole" | "xlink:show" | "xlink:title" => k.to_string(),
        "xlink:type" => "xlink:type".to_string(),
        "glyphref" => "glyphRef".to_string(),
        "gradientunits" => "gradientUnits".to_string(),
        "gradienttransform" => "gradientTransform".to_string(),
        "patterncontentunits" => "patternContentUnits".to_string(),
        "patternunits" => "patternUnits".to_string(),
        "patterntransform" => "patternTransform".to_string(),
        "spreadmethod" => "spreadMethod".to_string(),
        "viewbox" => "viewBox".to_string(),
        "attributetype" => "attributeType".to_string(),
        "repeatcount" => "repeatCount".to_string(),
        "repeatdur" => "repeatDur".to_string(),
        "requiredextensions" => "requiredExtensions".to_string(),
        "requiredfeatures" => "requiredFeatures".to_string(),
        "systemlanguage" => "systemLanguage".to_string(),
        "calcmode" => "calcMode".to_string(),
        "stitchtiles" => "stitchTiles".to_string(),
        "zoomandpan" => "zoomAndPan".to_string(),
        "targetx" => "targetX".to_string(),
