        "xchannelselector" => "xChannelSelector".to_string(),
        "ychannelselector" => "yChannelSelector".to_string(),
        "accentheight" => "accent-height".to_string(),
        "alignmentbaseline" => "alignment-baseline".to_string(),
        "ariform" => "ariform".to_string(),
        "arithmetic" => "arithmetic".to_string(),
        "baseline-shift" => "baseline-shift".to_string(),
        "basefrequency" => "baseFrequency".to_string(),
        "basesurface" => "basesurface".to_string(),
        "bbox" => "bbox".to_string(),
        "bias" => "bias".to_string(),
        "borderimage" => "borderimage".to_string(),
        "by" => "by".to_string(),
        "clippath" => "clipPath".to_string(),
        "clip-rule" => "clip-rule".to_string(),
        "clippathunits" => "clipPathUnits".to_string(),
