//! HTML tree construction (the tree construction algorithm of the HTML standard).

use crate::tokenizer::{is_ws, to_lower, Token};

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Ns { Html, Svg, MathMl }

#[derive(Clone, Debug)]
pub enum Node {
    Document,
    DocumentType { name: String },
    Element { name: String, ns: Ns, attrs: Vec<(String, String)>, children: Vec<usize>, content: Option<usize> },
    Text(String),
    Comment(String),
}

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Mode {
    Initial, BeforeHtml, BeforeHead, InHead, InHeadNoscript, AfterHead, InBody,
    Text, InTable, InTableText, InCaption, InColumnGroup, InTableBody, InRow, InCell,
    InSelect, InSelectInTable, InTemplate, AfterBody, InFrameset, AfterFrameset,
    AfterAfterBody, AfterAfterFrameset, ForeignContent,
}

pub fn is_void_html(name: &str) -> bool {
    matches!(name, "area" | "base" | "basefont" | "bgsound" | "br" | "col" | "embed" | "frame"
        | "hr" | "img" | "input" | "keygen" | "link" | "meta" | "param" | "source" | "track" | "wbr")
}

pub struct Tree {
    pub nodes: Vec<Node>,
    modes: Vec<Mode>,
    template_modes: Vec<Mode>,
    open: Vec<usize>,
    pending_table: Vec<u8>,
    foster_parenting: bool,
    pub skip_next_newline: bool,
    pub form_element: Option<usize>,
    head: Option<usize>,
}

fn ws_only(s: &[u8]) -> bool { s.iter().all(|&c| is_ws(c)) }
fn has_ws(s: &[u8]) -> bool { s.iter().any(|&c| is_ws(c)) }

impl Tree {
    pub fn new() -> Tree {
        Tree {
            nodes: vec![Node::Document],
            modes: vec![Mode::Initial],
            template_modes: Vec::new(),
            open: Vec::new(),
            pending_table: Vec::new(),
            foster_parenting: false,
            skip_next_newline: false,
            form_element: None,
            head: None,
        }
    }

    pub fn mode(&self) -> Mode { *self.modes.last().unwrap_or(&Mode::Initial) }
    fn set_mode(&mut self, m: Mode) { if let Some(l) = self.modes.last_mut() { *l = m } }
    fn push_mode(&mut self, m: Mode) { self.modes.push(m) }

    fn name_of(&self, n: usize) -> String {
        match &self.nodes[n] {
            Node::Element { name, .. } => name.clone(),
            Node::Document => "#document".into(),
            Node::DocumentType { name } => name.clone(),
            Node::Text(_) => "#text".into(),
            Node::Comment(_) => "#comment".into(),
        }
    }
    fn ns_of(&self, n: usize) -> Ns {
        match &self.nodes[n] {
            Node::Element { ns, .. } => *ns,
            _ => Ns::Html,
        }
    }
    fn alloc(&mut self, n: Node) -> usize { self.nodes.push(n); self.nodes.len() - 1 }
    fn append_to(&mut self, target: usize, node: usize) {
        if let Node::Element { children, .. } = &mut self.nodes[target] {
            children.push(node);
        }
    }
    fn cur(&self) -> usize { *self.open.last().unwrap_or(&0) }
    fn cur_name(&self) -> String { self.name_of(self.cur()) }
    fn has_cur(&self, n: &str) -> bool { self.cur_name() == n }
    fn find_in_open(&self, n: &str) -> bool { self.open.iter().any(|&i| self.name_of(i) == n) }
    fn last_in_open(&self, n: &str) -> Option<usize> {
        self.open.iter().rev().find(|&&i| self.name_of(i) == n).copied()
    }

    fn in_scope(&self, name: &str, list: &[&str]) -> bool {
        for &i in self.open.iter().rev() {
            let n = self.name_of(i);
            if n == name { return true }
            if list.contains(&n.as_str()) { return false }
        }
        false
    }
    fn in_button_scope(&self, name: &str) -> bool {
        self.in_scope(name, &["applet", "caption", "html", "table", "td", "th", "marquee", "object", "template"])
    }
    fn in_list_item_scope(&self, name: &str) -> bool {
        self.in_scope(name, &["applet", "caption", "html", "table", "td", "th", "marquee", "object", "ol", "ul"])
    }
    fn in_table_scope(&self, name: &str) -> bool { self.in_scope(name, &["html", "template"]) }
    fn in_select_scope(&self, name: &str) -> bool { self.in_scope(name, &["optgroup", "option"]) }

    fn insert_node(&mut self, node: usize) {
        let target = self.cur();
        let tn = self.name_of(target);
        let tns = self.ns_of(target);
        if tns == Ns::Html && matches!(tn.as_str(), "table" | "tbody" | "tfoot" | "thead" | "tr") && !self.foster_parenting {
            if let Node::Element { name, ns } = self.nodes[node].clone() {
                let ok = ns != Ns::Html || matches!(name.as_str(), "table" | "caption" | "colgroup" | "col"
                    | "tbody" | "tfoot" | "thead" | "tr" | "td" | "th" | "template" | "script" | "style" | "noscript");
                if !ok { self.foster_parent(node); return }
            }
        }
        self.append_to(target, node);
    }

    fn foster_parent(&mut self, node: usize) {
        self.foster_parenting = true;
        let mut table = None;
        for &i in self.open.iter().rev() {
            if self.name_of(i) == "table" { table = Some(i); break }
        }
        match table {
            Some(t) => {
                let parent = self.parent_of(t);
                match parent {
                    Some(p) => {
                        if let Node::Element { children, .. } = &mut self.nodes[p] {
                            match children.iter().position(|&c| c == t) {
                                Some(pos) => children.insert(pos, node),
                                None => children.push(node),
                            }
                        }
                    }
                    None => self.append_to(0, node),
                }
            }
            None => {
                let target = self.cur();
                self.append_to(target, node);
            }
        }
        self.foster_parenting = false;
    }

    fn parent_of(&self, want: usize) -> Option<usize> {
        fn walk(nodes: &[Node], cur: usize, want: usize) -> Option<usize> {
            let children: Vec<usize> = match &nodes[cur] {
                Node::Element { children, .. } => children.clone(),
                Node::Document => {
                    if let Node::Document = &nodes[cur] {
                        let mut v = Vec::new();
                        for (i, n) in nodes.iter().enumerate() {
                            if let Node::Element { .. } = n { let _ = i; }
                        }
                        v
                    } else { vec![] }
                }
                _ => vec![],
            };
            for &c in &children {
                if c == want { return Some(cur) }
                if let Some(p) = walk(nodes, c, want) { return Some(p) }
            }
            None
        }
        // the document's children are the nodes not referenced by any element
        let mut used: Vec<usize> = Vec::new();
        for (i, n) in self.nodes.iter().enumerate() {
            if let Node::Element { children, .. } = n {
                used.extend_from_slice(children);
            }
        }
        let doc_children: Vec<usize> = (1..self.nodes.len()).filter(|i| !used.contains(i)).collect();
        for &c in &doc_children {
            if c == want { return Some(0) }
            if let Some(p) = walk(&self.nodes, c, want) { return Some(p) }
        }
        None
    }

    fn insert_text(&mut self, s: &str) {
        if s.is_empty() { return }
        let target = self.cur();
        if let Node::Element { children, .. } = &mut self.nodes[target] {
            if let Some(&last) = children.last() {
                if let Node::Text(t) = &mut self.nodes[last] { t.push_str(s); return }
            }
        }
        let n = self.alloc(Node::Text(s.to_string()));
        self.insert_node(n);
    }

    fn insert_comment(&mut self, data: &str) {
        let n = self.alloc(Node::Comment(data.to_string()));
        self.insert_node(n);
    }

    fn make_element(&mut self, name: &str, ns: Ns, attrs: Vec<(String, String)>) -> usize {
        self.alloc(Node::Element { name: name.to_string(), ns, attrs, children: Vec::new(), content: None })
    }

    fn insert_element(&mut self, name: &str, ns: Ns, attrs: Vec<(String, String)>) -> usize {
        let el = self.make_element(name, ns, attrs);
        self.insert_node(el);
        el
    }

    fn push_el(&mut self, name: &str, ns: Ns, attrs: Vec<(String, String)>, mode: Mode) -> usize {
        let el = self.insert_element(name, ns, attrs);
        self.open.push(el);
        self.push_mode(mode);
        el
    }

    fn pop_one(&mut self) {
        if self.open.pop().is_some() {
            self.modes.pop();
        }
    }

    fn pop_until(&mut self, names: &[&str]) {
        loop {
            if self.open.is_empty() { break }
            let n = self.name_of(*self.open.last().unwrap());
            self.pop_one();
            if names.contains(&n.as_str()) { break }
        }
    }

    fn generate_implied_end_tags(&mut self, except: &[&str]) {
        loop {
            let n = self.cur_name();
            let implied = matches!(n.as_str(), "dd" | "dt" | "li" | "optgroup" | "option" | "p" | "rb" | "rp" | "rt" | "rtc");
            if implied && !except.contains(&n.as_str()) { self.pop_one() } else { break }
        }
    }
    fn close_p(&mut self) {
        if self.in_button_scope("p") {
            self.generate_implied_end_tags(&["p"]);
            if self.has_cur("p") { self.pop_one() }
        }
    }

    pub fn process(&mut self, token: Token) {
        if self.mode() == Mode::ForeignContent {
            self.process_foreign(token);
            return;
        }
        let mode = self.mode();
        match token {
            Token::Character(s) => self.chars(&s, mode),
            Token::Doctype { name, .. } => {
                let n = self.alloc(Node::DocumentType { name: String::from_utf8_lossy(&name).to_string() });
                self.append_to(0, n);
            }
            Token::Comment(d) => {
                if matches!(mode, Mode::Initial | Mode::BeforeHtml | Mode::AfterBody | Mode::AfterAfterBody) {
                    self.append_to(0, self.alloc(Node::Comment(String::from_utf8_lossy(&d).to_string())));
                } else {
                    self.insert_comment(&String::from_utf8_lossy(&d));
                }
            }
            Token::StartTag { name, attrs, self_closing } => {
                self.start_tag(&to_lower(&name), attrs, self_closing)
            }
            Token::EndTag { name } => self.end_tag(&to_lower(&name)),
            Token::Eof => self.eof(),
        }
    }

    fn process_foreign(&mut self, token: Token) {
        match token {
            Token::Character(s) => self.insert_text(&String::from_utf8_lossy(&s)),
            Token::Comment(d) => self.insert_comment(&String::from_utf8_lossy(&d)),
            Token::Doctype { name, .. } => {
                let n = self.alloc(Node::DocumentType { name: String::from_utf8_lossy(&name).to_string() });
                self.insert_node(n);
            }
            Token::StartTag { name, attrs, .. } => self.foreign_start(&to_lower(&name), attrs),
            Token::EndTag { name } => self.foreign_end(&to_lower(&name)),
            Token::Eof => self.eof(),
        }
    }

    fn chars(&mut self, s: &[u8], mode: Mode) {
        match mode {
            Mode::Initial | Mode::BeforeHtml => {
                if ws_only(s) { return }
                self.push_el("html", Ns::Html, Vec::new(), Mode::BeforeHead);
                self.process(Token::Character(s.to_vec()));
            }
            Mode::BeforeHead => {
                if ws_only(s) { return }
                self.push_el("head", Ns::Html, Vec::new(), Mode::InHead);
                self.head = Some(self.open.last().copied().unwrap());
                self.process(Token::Character(s.to_vec()));
            }
            Mode::InHead | Mode::InHeadNoscript => {
                if ws_only(s) {
                    self.insert_text(&String::from_utf8_lossy(s));
                    return;
                }
                self.insert_text(&String::from_utf8_lossy(s));
                self.pop_one();
                self.set_mode(Mode::AfterHead);
                self.process(Token::Character(s.to_vec()));
            }
            Mode::AfterHead => {
                if ws_only(s) {
                    self.insert_text(&String::from_utf8_lossy(s));
                    return;
                }
                self.push_el("body", Ns::Html, Vec::new(), Mode::InBody);
                self.process(Token::Character(s.to_vec()));
            }
            Mode::InTable | Mode::InTableBody | Mode::InRow | Mode::InCaption
            | Mode::InColumnGroup | Mode::InCell => {
                if !has_ws(s) {
                    self.pending_table.extend_from_slice(s);
                    self.set_mode(Mode::InTableText);
                } else {
                    self.insert_text(&String::from_utf8_lossy(s));
                }
            }
            Mode::InTableText => {
                self.pending_table.extend_from_slice(s);
            }
            Mode::AfterBody | Mode::AfterAfterBody | Mode::InBody | Mode::Text
            | Mode::InSelect | Mode::InSelectInTable | Mode::InTemplate => {
                self.insert_text(&String::from_utf8_lossy(s));
            }
            Mode::InFrameset | Mode::AfterFrameset | Mode::AfterAfterFrameset => {
                self.insert_text(&String::from_utf8_lossy(s));
            }
            Mode::ForeignContent => self.insert_text(&String::from_utf8_lossy(s)),
        }
    }

    fn flush_pending_table(&mut self) {
        if self.pending_table.is_empty() { return }
        let s = std::mem::take(&mut self.pending_table);
        if ws_only(&s) {
            self.insert_text(&String::from_utf8_lossy(&s));
            self.set_mode(Mode::InTable);
        } else {
            let t = String::from_utf8_lossy(&s).to_string();
            self.pop_until(&["table", "template", "html"]);
            self.set_mode(Mode::InBody);
            self.insert_text(&t);
            self.reset_insertion_mode();
        }
    }

    fn reset_insertion_mode(&mut self) {
        let mut i = self.open.len();
        while i > 0 {
            i -= 1;
            let n = self.name_of(self.open[i]);
            let m = match n.as_str() {
                "select" => Mode::InSelect,
                "td" | "th" => Mode::InCell,
                "tr" => Mode::InRow,
                "tbody" | "thead" | "tfoot" => Mode::InTableBody,
                "caption" => Mode::InCaption,
                "colgroup" => Mode::InColumnGroup,
                "table" => Mode::InTable,
                "template" => Mode::InTemplate,
                "body" => Mode::InBody,
                "head" => Mode::InHead,
                "html" => Mode::BeforeHead,
                _ => continue,
            };
            self.set_mode(m);
            return;
        }
        self.set_mode(Mode::InBody);
    }

    fn start_tag(&mut self, name: &str, attrs: Vec<(Vec<u8>, Vec<u8>)>, sc: bool) {
        if self.mode() == Mode::InTableText {
            self.flush_pending_table();
        }
        let a: Vec<(String, String)> = attrs.into_iter()
            .map(|(k, v)| (String::from_utf8_lossy(&k).to_string(), String::from_utf8_lossy(&v).to_string()))
            .collect();
        let mode = self.mode();
        match mode {
            Mode::Initial | Mode::BeforeHtml => match name {
                "html" => { self.push_el("html", Ns::Html, a, Mode::BeforeHead); }
                _ => {
                    self.push_el("html", Ns::Html, Vec::new(), Mode::BeforeHead);
                    self.start_tag(name, a, sc);
                }
            },
            Mode::BeforeHead => match name {
                "head" => { self.push_el("head", Ns::Html, a, Mode::InHead); self.head = Some(self.open.last().copied().unwrap()); }
                "html" => { self.push_el("head", Ns::Html, Vec::new(), Mode::InHead); self.head = Some(self.open.last().copied().unwrap()); self.start_tag(name, a, sc); }
                _ => {
                    self.push_el("head", Ns::Html, Vec::new(), Mode::InHead);
                    self.head = Some(self.open.last().copied().unwrap());
                    self.start_tag(name, a, sc);
                }
            },
            Mode::InHead | Mode::InHeadNoscript => self.in_head_start(name, a, sc),
            Mode::AfterHead => match name {
                "html" => { self.push_el("body", Ns::Html, Vec::new(), Mode::InBody); self.start_tag(name, a, sc); }
                _ => { self.push_el("body", Ns::Html, Vec::new(), Mode::InBody); self.start_tag(name, a, sc); }
            },
            Mode::InTable | Mode::InTableBody | Mode::InRow | Mode::InCaption
            | Mode::InColumnGroup | Mode::InCell | Mode::InTableText => self.table_start(name, a, sc),
            Mode::InSelect | Mode::InSelectInTable => self.select_start(name, a, sc),
            _ => self.in_body_start(name, a, sc),
        }
    }

    fn in_head_start(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match name {
            "html" => { self.pop_one(); self.set_mode(Mode::AfterHead); self.start_tag(name, a, sc) }
            "base" | "basefont" | "bgsound" | "link" | "meta" => {
                self.insert_element(name, Ns::Html, a);
                self.pop_one();
            }
            "title" => { self.push_el("title", Ns::Html, a, Mode::Text); self.rcdata_hint = Some(true); }
            "noscript" => { self.push_el("noscript", Ns::Html, a, Mode::InHeadNoscript); }
            "noframes" | "style" | "script" | "template" => {
                if name == "template" {
                    let el = self.insert_element("template", Ns::Html, a);
                    self.template_modes.push(Mode::InTemplate);
                    self.open.push(el);
                    self.push_mode(Mode::InTemplate);
                    return;
                }
                let hint = match name { "script" => 2, _ => 1 };
                self.push_el(name, Ns::Html, a, Mode::Text);
                if hint == 2 { self.rcdata_hint = Some(false); self.script_hint = true } else { self.rcdata_hint = Some(false) }
            }
            "head" => { self.pop_one(); self.start_tag("head", a, sc) }
            _ => { self.pop_one(); self.set_mode(Mode::AfterHead); self.start_tag(name, a, sc) }
        }
    }

    fn table_start(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match name {
            "caption" | "col" | "colgroup" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr" => {
                self.pop_until(&["table", "template", "html"]);
                self.set_mode(Mode::InTable);
                self.start_tag(name, a, sc);
            }
            "style" | "script" | "template" => {
                if name == "template" {
                    let el = self.insert_element("template", Ns::Html, a);
                    self.template_modes.push(Mode::InTemplate);
                    self.open.push(el);
                    self.push_mode(Mode::InTemplate);
                    return;
                }
                self.push_el(name, Ns::Html, a, Mode::Text);
                self.rcdata_hint = Some(false);
            }
            "input" => {
                let hidden = a.iter().any(|(k, v)| k == "type" && v.eq_ignore_ascii_case("hidden"));
                if hidden {
                    self.insert_element("input", Ns::Html, a);
                    self.pop_one();
                } else { self.foster_start(name, a, sc) }
            }
            "form" => {
                if self.find_in_open("template") {
                    self.insert_element("form", Ns::Html, a);
                    self.pop_one();
                } else { self.foster_start(name, a, sc) }
            }
            "table" => {
                self.pop_until(&["table", "template", "html"]);
                self.set_mode(Mode::InTable);
                self.in_body_start(name, a, sc);
            }
            _ => self.foster_start(name, a, sc),
        }
    }

    fn foster_start(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        // foster parent the element using the in-body rules
        self.pop_until(&["table", "template", "html"]);
        self.set_mode(Mode::InBody);
        self.in_body_start(name, a, sc);
        self.reset_insertion_mode();
        let _ = sc;
    }

    fn select_start(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match name {
            "html" => { self.pop_one(); self.set_mode(Mode::InBody); self.start_tag(name, a, sc) }
            "option" => { if self.has_cur("option") { self.pop_one() } self.push_el("option", Ns::Html, a, Mode::InSelect) }
            "optgroup" => {
                if self.has_cur("option") { self.pop_one() }
                if self.has_cur("optgroup") { self.pop_one() }
                self.push_el("optgroup", Ns::Html, a, Mode::InSelect)
            }
            "select" => { if !self.in_select_scope("select") { self.pop_until(&["select"]) } }
            "input" | "keygen" | "textarea" => {
                if !self.in_select_scope("select") {
                    self.pop_until(&["select"]);
                    self.set_mode(Mode::InBody);
                    self.start_tag(name, a, sc);
                }
            }
            "script" | "template" => self.in_head_start(name, a, sc),
            _ => {}
        }
    }

    fn in_body_start(&mut self, name: &str, a: Vec<(String, String)>, _sc: bool) {
        match name {
            "html" => { if self.find_in_open("template") { self.insert_element("html", Ns::Html, a) } }
            "base" | "basefont" | "bgsound" | "link" | "meta" => {
                self.insert_element(name, Ns::Html, a);
                self.pop_one();
            }
            "title" => { self.push_el("title", Ns::Html, a, Mode::Text); self.rcdata_hint = Some(true); }
            "noframes" | "style" | "script" => {
                self.push_el(name, Ns::Html, a, Mode::Text);
                self.rcdata_hint = Some(false);
            }
            "template" => {
                let el = self.insert_element("template", Ns::Html, a);
                self.template_modes.push(Mode::InTemplate);
                self.open.push(el);
                self.push_mode(Mode::InTemplate);
            }
            "body" => {
                if self.find_in_open("template") { self.insert_element("body", Ns::Html, a) }
            }
            "frameset" => {
                let el = self.insert_element("frameset", Ns::Html, a);
                self.open.push(el);
                self.push_mode(Mode::InFrameset);
            }
            "address" | "article" | "aside" | "blockquote" | "center" | "details" | "dialog"
            | "dir" | "div" | "dl" | "fieldset" | "figcaption" | "figure" | "footer" | "header"
            | "hgroup" | "main" | "menu" | "nav" | "ol" | "p" | "section" | "summary" | "ul" => {
                self.close_p();
                self.push_el(name, Ns::Html, a, Mode::InBody);
            }
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                self.close_p();
                if matches!(self.cur_name().as_str(), "h1" | "h2" | "h3" | "h4" | "h5" | "h6") {
                    self.pop_one();
                }
                self.push_el(name, Ns::Html, a, Mode::InBody);
            }
            "pre" | "listing" => {
                self.close_p();
                self.push_el(name, Ns::Html, a, Mode::InBody);
                self.skip_next_newline = true;
            }
            "form" => {
                if !self.find_in_open("template") { self.form_element = None }
                if self.form_element.is_none() {
                    let el = self.insert_element("form", Ns::Html, a);
                    self.form_element = Some(el);
                    self.open.push(el);
                    self.push_mode(Mode::InBody);
                }
            }
            "li" => {
                if self.in_list_item_scope("li") {
                    self.generate_implied_end_tags(&["li"]);
                    if self.has_cur("li") { self.pop_one() }
                }
                self.push_el("li", Ns::Html, a, Mode::InBody);
            }
            "dd" | "dt" => {
                if self.in_list_item_scope(name) {
                    self.generate_implied_end_tags(&[name]);
                    if self.has_cur(name) { self.pop_one() }
                }
                self.push_el(name, Ns::Html, a, Mode::InBody);
            }
            "plaintext" => {
                self.close_p();
                self.push_el("plaintext", Ns::Html, a, Mode::Text);
                self.plaintext_hint = true;
            }
            "button" => {
                if self.in_scope("button", &[]) {
                    self.generate_implied_end_tags(&[]);
                    if self.has_cur("button") { self.pop_one() }
                }
                self.push_el("button", Ns::Html, a, Mode::InBody);
            }
            "a" => {
                if self.last_in_open("a").is_some() { self.adoption_agency("a") }
                self.push_el("a", Ns::Html, a, Mode::InBody);
            }
            "b" | "big" | "code" | "em" | "font" | "i" | "s" | "small" | "strike" | "strong"
            | "tt" | "u" | "nobr" => {
                if self.last_in_open(name).is_some() { self.adoption_agency(name) }
                self.push_el(name, Ns::Html, a, Mode::InBody);
            }
            "applet" | "marquee" | "object" => {
                self.push_el(name, Ns::Html, a, Mode::InBody);
            }
            "table" => {
                if !self.quirks && self.in_button_scope("p") { self.close_p() }
                self.push_el("table", Ns::Html, a, Mode::InTable);
            }
            "area" | "br" | "embed" | "img" | "keygen" | "wbr" | "input" | "param" | "source"
            | "track" => {
                self.insert_element(name, Ns::Html, a);
                self.pop_one();
            }
            "hr" => {
                self.close_p();
                self.insert_element("hr", Ns::Html, a);
                self.pop_one();
            }
            "image" => self.in_body_start("img", a, _sc),
            "textarea" => {
                self.push_el("textarea", Ns::Html, a, Mode::Text);
                self.rcdata_hint = Some(true);
                self.skip_next_newline = true;
            }
            "xmp" => {
                self.close_p();
                self.push_el("xmp", Ns::Html, a, Mode::Text);
                self.rcdata_hint = Some(false);
            }
            "iframe" | "noembed" => {
                self.push_el(name, Ns::Html, a, Mode::Text);
                self.rcdata_hint = Some(false);
            }
            "noscript" => { self.push_el("noscript", Ns::Html, a, Mode::InBody); }
            "select" => {
                if self.in_scope("select", &[]) { self.pop_one() }
                self.push_el("select", Ns::Html, a, Mode::InSelect);
            }
            "optgroup" | "option" => {
                if self.has_cur("option") { self.pop_one() }
                self.push_el(name, Ns::Html, a, Mode::InSelect);
            }
            "rb" | "rtc" => {
                if self.in_scope(name, &[]) { self.generate_implied_end_tags(&[]); self.pop_one() }
                self.push_el(name, Ns::Html, a, Mode::InBody);
            }
            "rp" | "rt" => {
                if self.in_scope("rtc", &[]) { self.generate_implied_end_tags(&[]) }
                self.push_el(name, Ns::Html, a, Mode::InBody);
            }
            "math" | "svg" => {
                let ns = if name == "svg" { Ns::Svg } else { Ns::MathMl };
                let a2 = adjust_attributes(&a, ns);
                let el = self.insert_element(name, ns, a2);
                self.open.push(el);
                self.push_mode(Mode::ForeignContent);
            }
            "caption" | "col" | "colgroup" | "frame" | "head" | "tbody" | "td" | "tfoot"
            | "th" | "thead" | "tr" => {}
            _ => { self.push_el(name, Ns::Html, a, Mode::InBody); }
        }
    }

    pub fn adoption_agency(&mut self, subject: &str) {
        if let Some(furthest) = self.last_in_open(subject) {
            let idx = self.open.iter().position(|&x| x == furthest).unwrap();
            self.pop_from(idx);
        }
    }
    fn pop_from(&mut self, idx: usize) {
        while self.open.len() > idx { self.pop_one() }
    }

    pub rcdata_hint: Option<bool>,
    pub script_hint: bool,
    pub plaintext_hint: bool,
    pub quirks: bool,

    fn end_tag(&mut self, name: &str) {
        if self.mode() == Mode::InTableText {
            self.flush_pending_table();
        }
        let mode = self.mode();
        match mode {
            Mode::Initial | Mode::BeforeHtml => {}
            Mode::BeforeHead => {
                if name == "head" || name == "body" || name == "html" || name == "br" {}
                else {
                    self.push_el("head", Ns::Html, Vec::new(), Mode::InHead);
                    self.head = Some(self.open.last().copied().unwrap());
                    self.end_tag(name);
                }
            }
            Mode::InHead | Mode::InHeadNoscript => self.in_head_end(name),
            Mode::AfterHead => match name {
                "body" => { self.push_el("body", Ns::Html, Vec::new(), Mode::InBody); }
                _ => { self.push_el("body", Ns::Html, Vec::new(), Mode::InBody); self.end_tag(name) }
            },
            Mode::InBody | Mode::AfterAfterBody | Mode::AfterBody | Mode::InTemplate
            | Mode::InFrameset | Mode::AfterFrameset | Mode::AfterAfterFrameset => self.in_body_end(name),
            Mode::Text => self.text_end(name),
            Mode::InTable | Mode::InTableText | Mode::InTableBody | Mode::InRow
            | Mode::InCell | Mode::InCaption | Mode::InColumnGroup => self.table_end(name),
            Mode::InSelect | Mode::InSelectInTable => self.select_end(name),
            Mode::ForeignContent => self.foreign_end(name),
        }
    }

    fn in_head_end(&mut self, name: &str) {
        match name {
            "head" => { self.pop_one(); self.set_mode(Mode::AfterHead); }
            "body" | "html" | "br" => {
                self.pop_one();
                self.set_mode(Mode::AfterHead);
                self.end_tag(name);
            }
            "template" => { if self.find_in_open("template") { self.pop_until(&["template"]) } }
            _ => {
                self.pop_one();
                self.set_mode(Mode::AfterHead);
                self.end_tag(name);
            }
        }
    }

    fn text_end(&mut self, name: &str) {
        let last = *self.open.last().unwrap_or(&0);
        let lname = self.name_of(last);
        self.pop_one();
        if lname != name {
            self.set_mode(Mode::InBody);
            self.end_tag(name);
        }
    }

    fn table_end(&mut self, name: &str) {
        match name {
            "caption" => {
                if self.in_table_scope("caption") {
                    self.generate_implied_end_tags(&[]);
                    self.pop_until(&["caption"]);
                    self.set_mode(Mode::InTable);
                }
            }
            "colgroup" => {
                if self.has_cur("colgroup") {
                    self.pop_one();
                    self.set_mode(Mode::InTable);
                }
            }
            "tbody" | "tfoot" | "thead" => {
                if self.in_table_scope(name) {
                    self.clear_stack(&["tbody", "tfoot", "thead", "template", "html"]);
                    self.pop_one();
                    self.set_mode(Mode::InTable);
                }
            }
            "tr" => {
                if self.in_table_scope("tr") {
                    self.clear_stack(&["tr", "template", "html"]);
                    self.pop_one();
                    self.set_mode(Mode::InTableBody);
                }
            }
            "td" | "th" => {
                let other = if name == "td" { "th" } else { "td" };
                if self.in_table_scope(name) || self.in_table_scope(other) {
                    self.generate_implied_end_tags(&[]);
                    self.pop_until(&[name, other]);
                    self.set_mode(Mode::InRow);
                }
            }
            "table" => {
                if self.in_table_scope("table") {
                    self.clear_stack(&["table", "template", "html"]);
                    self.pop_one();
                    self.reset_insertion_mode();
                }
            }
            "body" | "col" | "colgroup" | "html" => {}
            "template" => { if self.find_in_open("template") { self.pop_until(&["template"]) } }
            _ => {
                if self.in_table_scope("table") {
                    self.pop_until(&["table", "template", "html"]);
                    self.set_mode(Mode::InBody);
                    self.in_body_end(name);
                    self.reset_insertion_mode();
                }
            }
        }
    }

    fn clear_stack(&mut self, names: &[&str]) {
        while !self.open.is_empty() {
            let n = self.name_of(*self.open.last().unwrap());
            if names.contains(&n.as_str()) { break }
            self.pop_one();
        }
    }

    fn select_end(&mut self, name: &str) {
        match name {
            "optgroup" => {
                if self.has_cur("option") { self.pop_one() }
                if self.has_cur("optgroup") { self.pop_one() }
            }
            "option" => { if self.has_cur("option") { self.pop_one() } }
            "select" => {
                if self.in_select_scope("select") {
                    self.pop_until(&["select"]);
                    self.set_mode(Mode::InBody);
                }
            }
            _ => {}
        }
    }

    fn in_body_end(&mut self, name: &str) {
        match name {
            "template" => {
                if self.find_in_open("template") {
                    self.pop_until(&["template"]);
                    self.template_modes.pop();
                }
            }
            "p" => {
                if self.in_button_scope("p") {
                    self.generate_implied_end_tags(&["p"]);
                    if self.has_cur("p") { self.pop_one() }
                }
            }
            "body" => {
                if self.in_scope("body", &[]) {
                    self.generate_implied_end_tags(&[]);
                    if self.has_cur("body") { self.pop_one() }
                }
            }
            "html" => {
                if self.in_scope("body", &[]) {
                    self.in_body_end("body");
                }
            }
            "address" | "article" | "aside" | "blockquote" | "button" | "center" | "details"
            | "dialog" | "dir" | "div" | "dl" | "fieldset" | "figcaption" | "figure" | "footer"
            | "header" | "hgroup" | "listing" | "main" | "menu" | "nav" | "ol" | "pre"
            | "section" | "summary" | "ul" => {
                if self.in_scope(name, &[]) {
                    self.generate_implied_end_tags(&[]);
                    if self.has_cur(name) { self.pop_one() }
                }
            }
            "form" => {
                let has_tpl = self.find_in_open("template");
                if self.form_element.is_some() || has_tpl {
                    if self.in_scope("form", &[]) {
                        self.generate_implied_end_tags(&[]);
                        if self.has_cur("form") { self.pop_one() }
                    }
                }
            }
            "li" => {
                if self.in_list_item_scope("li") {
                    self.generate_implied_end_tags(&["li"]);
                    if self.has_cur("li") { self.pop_one() }
                }
            }
            "dd" | "dt" => {
                if self.in_list_item_scope(name) {
                    self.generate_implied_end_tags(&[name]);
                    if self.has_cur(name) { self.pop_one() }
                }
            }
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                if self.in_scope(name, &[]) {
                    self.generate_implied_end_tags(&[]);
                    if self.has_cur(name) { self.pop_one() }
                }
            }
            "a" | "b" | "big" | "code" | "em" | "font" | "i" | "nobr" | "s" | "small"
            | "strike" | "strong" | "tt" | "u" => self.adoption_agency(name),
            "applet" | "marquee" | "object" => {
                if self.in_scope(name, &[]) {
                    self.generate_implied_end_tags(&[]);
                    if self.has_cur(name) { self.pop_one() }
                }
            }
            "br" => { if self.in_scope("br", &[]) { self.in_body_start("br", Vec::new(), false) } }
            _ => {
                if self.last_in_open(name).is_some() {
                    self.generate_implied_end_tags(&[]);
                    self.pop_until(&[name]);
                }
            }
        }
    }

    fn foreign_start(&mut self, name: &str, a: Vec<(Vec<u8>, Vec<u8>)>) {
        let ns = self.ns_of(self.cur());
        let ns2 = if name == "svg" { Ns::Svg } else if name == "math" { Ns::MathMl } else { ns };
        let a2: Vec<(String, String)> = adjust_attributes(&a, ns2);
        let adj = adjusted_foreign_tag_name(name, ns2);
        let el = self.insert_element(&adj, ns2, a2);
        if !is_void_html(&adj) && !matches!(adj.as_str(), "rect" | "circle" | "line" | "path"
            | "polyline" | "polygon" | "ellipse" | "use" | "image" | "stop" | "animate"
            | "animateTransform" | "feImage" | "foreignObject" | "feBlend" | "feColorMatrix") {
            self.open.push(el);
            self.push_mode(Mode::ForeignContent);
        } else {
            self.push_mode(Mode::ForeignContent);
            self.pop_mode_if_foreign();
        }
    }
    fn pop_mode_if_foreign(&mut self) {
        if self.modes.len() > 1 { self.modes.pop() }
    }

    fn foreign_end(&mut self, name: &str) {
        let cur = self.cur();
        let cn = self.name_of(cur);
        let ns = self.ns_of(cur);
        let adj = adjusted_foreign_tag_name(name, ns);
        if adj == cn || matches!(name, "svg" | "math" | "annotation-xml" | "mglyph" | "malignmark") {
            self.pop_one();
            if self.ns_of(self.cur()) == Ns::Html {
                self.reset_insertion_mode();
            }
        }
    }

    fn eof(&mut self) {
        if self.mode() == Mode::InTableText { self.flush_pending_table() }
        match self.mode() {
            Mode::Initial | Mode::BeforeHtml => {
                self.push_el("html", Ns::Html, Vec::new(), Mode::BeforeHead);
                self.push_el("head", Ns::Html, Vec::new(), Mode::InHead);
                self.head = Some(self.open.last().copied().unwrap());
                self.pop_one();
                self.set_mode(Mode::AfterHead);
                self.push_el("body", Ns::Html, Vec::new(), Mode::InBody);
            }
            Mode::BeforeHead => {
                self.push_el("head", Ns::Html, Vec::new(), Mode::InHead);
                self.head = Some(self.open.last().copied().unwrap());
                self.pop_one();
                self.set_mode(Mode::AfterHead);
                self.push_el("body", Ns::Html, Vec::new(), Mode::InBody);
            }
            Mode::InHead | Mode::InHeadNoscript => {
                self.pop_one();
                self.set_mode(Mode::AfterHead);
                self.push_el("body", Ns::Html, Vec::new(), Mode::InBody);
            }
            Mode::AfterHead => { self.push_el("body", Ns::Html, Vec::new(), Mode::InBody); }
            _ => { self.generate_implied_end_tags(&[]); }
        }
    }
}

fn adjust_attributes(a: &[(Vec<u8>, Vec<u8>)], ns: Ns) -> Vec<(String, String)> {
    a.iter().map(|(k, v)| {
        let ks = String::from_utf8_lossy(k).to_string();
        let nk = match ns {
            Ns::Svg => adjust_svg_attr(&ks),
            Ns::MathMl => adjust_mathml_attr(&ks),
            _ => ks,
        };
        (nk, String::from_utf8_lossy(v).to_string())
    }).collect()
}

fn adjust_svg_attr(k: &str) -> String {
    match k {
        "glyphref" => "glyphRef", "gradientunits" => "gradientUnits",
        "gradienttransform" => "gradientTransform", "patterncontentunits" => "patternContentUnits",
        "patternunits" => "patternUnits", "patterntransform" => "patternTransform",
        "spreadmethod" => "spreadMethod", "viewbox" => "viewBox", "attributetype" => "attributeType",
        "repeatcount" => "repeatCount", "repeatdur" => "repeatDur",
        "requiredextensions" => "requiredExtensions", "requiredfeatures" => "requiredFeatures",
        "systemlanguage" => "systemLanguage", "calcmode" => "calcMode",
        "stitchtiles" => "stitchTiles", "zoomandpan" => "zoomAndPan",
        "targetx" => "targetX", "targety" => "targetY", "textlength" => "textLength",
        "startoffset" => "startOffset", "xchannelselector" => "xChannelSelector",
        "ychannelselector" => "yChannelSelector", "attributename" => "attributeName",
        "attributetype" => "attributeType", "basefrequency" => "baseFrequency",
        "clippathunits" => "clipPathUnits", "diffuseconstant" => "diffuseConstant",
        "edgemode" => "edgeMode", "filterunits" => "filterUnits",
        "kernelmatrix" => "kernelMatrix", "keypoints" => "keyPoints",
        "keysplines" => "keySplines", "keytimes" => "keyTimes",
        "limitingconeangle" => "limitingConeAngle", "markerheight" => "markerHeight",
        "markerunits" => "markerUnits", "markerwidth" => "markerWidth",
        "maskcontentunits" => "maskContentUnits", "maskunits" => "maskUnits",
        "numoctaves" => "numOctaves", "pathlength" => "pathLength",
        "pointsatx" => "pointsAtX", "pointsaty" => "pointsAtY", "pointsatz" => "pointsAtZ",
        "preservealpha" => "preserveAlpha", "primitiveunits" => "primitiveUnits",
        "refx" => "refX", "refy" => "refY", "repeatcount" => "repeatCount",
        "repeatdur" => "repeatDur", "shadowdx" => "shadowdx", "shadowdy" => "shadowdy",
        "specularconstant" => "specularConstant", "specularexponent" => "specularExponent",
        "surfacescale" => "surfaceScale", "xchannelselector" => "xChannelSelector",
        "ychannelselector" => "yChannelSelector", "zoomandpan" => "zoomAndPan",
        _ => k,
    }.to_string()
}

fn adjust_mathml_attr(k: &str) -> String {
    match k { "definitionurl" => "definitionURL", _ => k }.to_string()
}

fn adjusted_foreign_tag_name(name: &str, ns: Ns) -> String {
    if ns == Ns::Svg {
        return match name {
            "altglyph" => "altGlyph", "altglyphdef" => "altGlyphDef", "altglyphitem" => "altGlyphItem",
            "animatecolor" => "animateColor", "animatecount" => "animateCount",
            "animatecolorstart" => "animateColorStart", "animatecolorend" => "animateColorEnd",
            "animatemotion" => "animateMotion", "animatetransform" => "animateTransform",
            "clippath" => "clipPath", "feblend" => "feBlend", "fecolormatrix" => "feColorMatrix",
            "fecomponenttransfer" => "feComponentTransfer", "fecomposite" => "feComposite",
            "feconvolvematrix" => "feConvolveMatrix", "fediffuselighting" => "feDiffuseLighting",
            "fedisplacementmap" => "feDisplacementMap", "fedistantlight" => "feDistantLight",
            "fedropshadow" => "feDropShadow", "feflood" => "feFlood", "fefunca" => "feFuncA",
            "fefuncb" => "feFuncB", "fefuncg" => "feFuncG", "fefuncr" => "feFuncR",
            "fegaussianblur" => "feGaussianBlur", "feimage" => "feImage", "femerge" => "feMerge",
            "femergenode" => "feMergeNode", "femorphology" => "feMorphology", "feoffset" => "feOffset",
            "fepointlight" => "fePointLight", "fespecularlighting" => "feSpecularLighting",
            "fespotlight" => "feSpotLight", "fetile" => "feTile", "feturbulence" => "feTurbulence",
            "foreignobject" => "foreignObject", "glyphref" => "glyphRef",
            "lineargradient" => "linearGradient", "radialgradient" => "radialGradient",
            "solidcolor" => "solidColor", "solidcolorstop" => "solidColorStop",
            "textpath" => "textPath", _ => name,
        }.to_string();
    }
    name.to_string()
}
