//! CSS tokenizer (cssparser-compatible) used to rewrite url()/@import references.

pub fn is_ws(c: u8) -> bool { matches!(c, 0x09 | 0x0a | 0x0c | 0x0d | 0x20) }
fn is_nl(c: u8) -> bool { matches!(c, 0x0a | 0x0d) }
fn is_hex(c: u8) -> bool { matches!(c, b'0'..=b'9' | b'a'..=b'f' | b'A'..=b'F') }
fn hexval(c: u8) -> u32 {
    match c { b'0'..=b'9' => (c - b'0') as u32, b'a'..=b'f' => (c - b'a' + 10) as u32, _ => (c - b'A' + 10) as u32 }
}
fn is_ident_start(c: u8) -> bool {
    is_alpha(c) || c == b'_' || c >= 0x80 || c == b'\\'
}
fn is_alpha(c: u8) -> bool { matches!(c, b'a'..=b'z' | b'A'..=b'Z') }
fn is_ident_char(c: u8) -> bool {
    is_ident_start(c) || matches!(c, b'0'..=b'9' | b'-' | b'_')
}

pub enum Tok {
    Whitespace(Vec<u8>),
    Comment(Vec<u8>),
    Ident(Vec<u8>),
    Function(Vec<u8>),
    AtKeyword(Vec<u8>),
    Hash(Vec<u8>),
    Str(Vec<u8>),
    BadStr,
    Url(Vec<u8>),
    BadUrl,
    Delim(u8),
    Num { value: f32, has_sign: bool },
    Percent { value: f32, has_sign: bool },
    Dim { value: f32, unit: Vec<u8>, has_sign: bool },
    Colon, Semicolon, Comma, OpenParen, CloseParen, OpenBracket, CloseBracket,
    IncludeMatch, DashMatch, PrefixMatch, SuffixMatch, SubstringMatch,
    Column, Cdo, Cdc,
    Eof,
}

pub struct CssTokenizer {
    input: Vec<u8>,
    pos: usize,
}

fn decode_escapes(input: &[u8], start: usize, end: usize) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::with_capacity(end - start);
    let mut i = start;
    while i < end {
        let c = input[i];
        if c != b'\\' {
            out.push(c);
            i += 1;
            continue;
        }
        i += 1;
        if i >= end { continue }
        let c2 = input[i];
        if is_nl(c2) {
            i += 1;
            if c2 == 0x0d && i < end && input[i] == 0x0a { i += 1 }
            continue;
        }
        if is_hex(c2) {
            let mut v: u32 = 0;
            let mut n = 0;
            while i < end && n < 6 && is_hex(input[i]) {
                v = v * 16 + hexval(input[i]);
                i += 1;
                n += 1;
            }
            if i < end && is_ws(input[i]) { i += 1 }
            let cp = if v == 0 || v > 0x10FFFF || (0xD800..0xE000).contains(&v) { 0xFFFD } else { v };
            let mut buf = [0u8; 4];
            out.extend_from_slice(char::from_u32(cp).unwrap_or('\u{FFFD}').encode_utf8(&mut buf).as_bytes());
            continue;
        }
        out.push(c2);
        i += 1;
    }
    out
}

fn serialize_string_value(out: &mut Vec<u8>, s: &[u8]) {
    out.push(b'"');
    let t = String::from_utf8_lossy(s).into_owned();
    for c in t.chars() {
        match c {
            '"' => out.extend_from_slice(b"\\\""),
            '\\' => out.extend_from_slice(b"\\\\"),
            '\n' => out.extend_from_slice(b"\\a "),
            '\r' => out.extend_from_slice(b"\\d "),
            '\t' => out.extend_from_slice(b"\\9 "),
            c if (c as u32) < 0x20 || c as u32 == 0x7F => {
                out.push(b'\\');
                out.extend_from_slice(format!("{:x}", c as u32).as_bytes());
                out.push(b' ');
            }
            c => {
                let mut buf = [0u8; 4];
                out.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
            }
        }
    }
    out.push(b'"');
}

impl CssTokenizer {
    pub fn new(input: Vec<u8>) -> CssTokenizer { CssTokenizer { input, pos: 0 } }
    fn at(&self) -> Option<u8> { self.input.get(self.pos).copied() }

    fn read_ws(&mut self) -> Vec<u8> {
        let start = self.pos;
        while let Some(c) = self.at() {
            if is_ws(c) { self.pos += 1 } else { break }
        }
        self.input[start..self.pos].to_vec()
    }

    pub fn next(&mut self) -> Tok {
        // skip comments and whitespace, returning them as tokens
        if let Some(c) = self.at() {
            if is_ws(c) {
                let w = self.read_ws();
                return Tok::Whitespace(w);
            }
            if c == b'/' && self.input.get(self.pos + 1) == Some(&b'*') {
                // comment
                let start = self.pos;
                let mut i = self.pos + 2;
                while i < self.input.len() {
                    if self.input[i] == b'*' && i + 1 < self.input.len() && self.input[i + 1] == b'/' {
                        i += 2;
                        break;
                    }
                    i += 1;
                }
                self.pos = i;
                return Tok::Comment(self.input[start..i].to_vec());
            }
            if self.input[self.pos..].starts_with(b"<!--") {
                self.pos += 4;
                return Tok::Cdo;
            }
            if self.input[self.pos..].starts_with(b"-->") {
                self.pos += 3;
                return Tok::Cdc;
            }
        } else {
            return Tok::Eof;
        }
        let c = self.at().unwrap();
        match c {
            b':' => { self.pos += 1; Tok::Colon }
            b';' => { self.pos += 1; Tok::Semicolon }
            b',' => { self.pos += 1; Tok::Comma }
            b'(' => { self.pos += 1; Tok::OpenParen }
            b')' => { self.pos += 1; Tok::CloseParen }
            b'[' => { self.pos += 1; Tok::OpenBracket }
            b']' => { self.pos += 1; Tok::CloseBracket }
            b'~' if self.input.get(self.pos + 1) == Some(&b'=') => { self.pos += 2; Tok::IncludeMatch }
            b'|' if self.input.get(self.pos + 1) == Some(&b'=') => { self.pos += 2; Tok::DashMatch }
            b'|' if self.input.get(self.pos + 1) == Some(&b'|') => { self.pos += 2; Tok::Column }
            b'^' if self.input.get(self.pos + 1) == Some(&b'=') => { self.pos += 2; Tok::PrefixMatch }
            b'$' if self.input.get(self.pos + 1) == Some(&b'=') => { self.pos += 2; Tok::SuffixMatch }
            b'*' if self.input.get(self.pos + 1) == Some(&b'=') => { self.pos += 2; Tok::SubstringMatch }
            b'"' | b'\'' => self.read_string(c),
            b'#' => {
                self.pos += 1;
                let start = self.pos;
                self.read_name();
                let v = self.input[start..self.pos].to_vec();
                Tok::Hash(decode_escapes(&self.input, start, self.pos))
            }
            b'@' => {
                self.pos += 1;
                let start = self.pos;
                self.read_name();
                Tok::AtKeyword(decode_escapes(&self.input, start, self.pos))
            }
            b'0'..=b'9' => self.read_number(false),
            b'+' | b'-' => {
                let next = self.input.get(self.pos + 1).copied();
                let is_num = match next {
                    Some(n) if n.is_ascii_digit() => true,
                    Some(b'.') => self.input.get(self.pos + 2).map_or(false, |n| n.is_ascii_digit()),
                    _ => false,
                };
                if is_num { self.read_number(true) }
                else if c == b'-' && self.input.get(self.pos + 1) == Some(&b'-') {
                    let start = self.pos;
                    self.pos += 2;
                    self.read_name();
                    Tok::Ident(self.input[start..self.pos].to_vec())
                } else {
                    self.pos += 1;
                    Tok::Delim(c)
                }
            }
            b'.' => {
                if self.input.get(self.pos + 1).map_or(false, |n| n.is_ascii_digit()) {
                    self.read_number(false)
                } else {
                    self.pos += 1;
                    Tok::Delim(c)
                }
            }
            b'\\' => {
                let start = self.pos;
                self.read_name();
                Tok::Ident(decode_escapes(&self.input, start, self.pos))
            }
            _ if is_ident_start(c) => {
                let start = self.pos;
                self.read_name();
                let name = self.input[start..self.pos].to_vec();
                if self.at() == Some(b'(') {
                    self.pos += 1;
                    if name == b"url" {
                        self.read_url_function_body()
                    } else {
                        Tok::Function(decode_escapes(&self.input, start, self.pos - 1))
                    }
                } else {
                    Tok::Ident(decode_escapes(&self.input, start, self.pos))
                }
            }
            _ => { self.pos += 1; Tok::Delim(c) }
        }
    }

    fn read_name(&mut self) {
        while let Some(c) = self.at() {
            if is_ident_char(c) {
                self.pos += 1;
            } else if c == b'\\' {
                self.pos += 1;
                if let Some(n) = self.at() {
                    if is_ws(n) { self.pos += 1 }
                }
            } else {
                break;
            }
        }
    }

    fn read_string(&mut self, quote: u8) -> Tok {
        self.pos += 1;
        let start = self.pos;
        let mut bad = false;
        while let Some(c) = self.at() {
            if c == quote { self.pos += 1; break }
            if c == b'\\' {
                self.pos += 1;
                if let Some(n) = self.at() {
                    if is_nl(n) { bad = true; break }
                    self.pos += 1;
                } else { bad = true; break }
                continue;
            }
            if is_nl(c) { bad = true; break }
            self.pos += 1;
        }
        if bad {
            return Tok::BadStr;
        }
        Tok::Str(decode_escapes(&self.input, start, if self.pos > start && self.input.get(self.pos - 1) == Some(&quote) { self.pos - 1 } else { self.pos }))
    }

    fn read_url_function_body(&mut self) -> Tok {
        // self.pos points just after "url("
        let start = self.pos;
        // skip whitespace
        while let Some(c) = self.at() {
            if is_ws(c) { self.pos += 1 } else { break }
        }
        match self.at() {
            Some(b'"') | Some(b'\'') => {
                // quoted url: keep the whitespace tokens, so rewind
                self.pos = start;
                Tok::Function(b"url".to_vec())
            }
            Some(b')') | None => {
                self.pos = start;
                Tok::Function(b"url".to_vec())
            }
            Some(_) => {
                // unquoted url: consume until a bad url char
                let s = self.pos;
                let mut bad = false;
                while let Some(c) = self.at() {
                    if c == b')' { break }
                    if is_ws(c) || c == b'"' || c == b'\'' || c == b'(' || c < 0x20 || c == 0x7F {
                        bad = true;
                        break;
                    }
                    if c == b'\\' { self.pos += 1; continue }
                    self.pos += 1;
                }
                if bad { Tok::BadUrl } else { Tok::Url(self.input[s..self.pos].to_vec()) }
            }
        }
    }

    fn read_number(&mut self, signed: bool) -> Tok {
        let start = self.pos;
        if signed { self.pos += 1 }
        let mut int_part = false;
        while let Some(c) = self.at() {
            if c.is_ascii_digit() { self.pos += 1; int_part = true } else { break }
        }
        let mut frac = false;
        if self.at() == Some(b'.') && self.input.get(self.pos + 1).map_or(false, |c| c.is_ascii_digit()) {
            self.pos += 1;
            while let Some(c) = self.at() {
                if c.is_ascii_digit() { self.pos += 1 } else { break }
            }
            frac = true;
        }
        let mut expo = false;
        if matches!(self.at(), Some(b'e') | Some(b'E')) {
            let mut p = self.pos + 1;
            if matches!(self.input.get(p), Some(b'+') | Some(b'-')) { p += 1 }
            if self.input.get(p).map_or(false, |c| c.is_ascii_digit()) {
                self.pos = p;
                while let Some(c) = self.at() {
                    if c.is_ascii_digit() { self.pos += 1 } else { break }
                }
                expo = true;
            }
        }
        let text = String::from_utf8_lossy(&self.input[start..self.pos]).to_string();
        let has_sign = text.starts_with('+') || text.starts_with('-');
        let value: f32 = text.parse().unwrap_or(0.0);
        // unit?
        let save = self.pos;
        if self.at() == Some(b'%') {
            self.pos += 1;
            return Tok::Percent { value, has_sign };
        }
        if let Some(c) = self.at() {
            if is_ident_start(c) {
                let ustart = self.pos;
                self.read_name();
                let unit = self.input[ustart..self.pos].to_vec();
                return Tok::Dim { value, unit, has_sign };
            }
        }
        self.pos = save;
        if frac || expo { Tok::Num { value, has_sign } } else { Tok::Num { value, has_sign } }
    }
}

pub fn serialize_num(out: &mut Vec<u8>, value: f32, has_sign: bool) {
    if has_sign {
        out.push(if value.is_sign_positive() { b'+' } else { b'-' });
    }
    out.extend_from_slice(format!("{}", value).as_bytes());
}
