//! Minimal HTTP/1.1 client used for retrieving documents and assets.

use std::io::{Read, Write};
use std::net::TcpStream;
use std::time::Duration;

pub struct Response {
    pub status: u16,
    pub reason: String,
    pub headers: Vec<(String, String)>,
    pub body: Vec<u8>,
}

impl Response {
    pub fn header(&self, name: &str) -> Option<&str> {
        self.headers.iter().find(|(k, _)| k.eq_ignore_ascii_case(name)).map(|(_, v)| v.as_str())
    }
}

pub struct Client {
    pub timeout: u64,
    pub user_agent: String,
    pub insecure: bool,
    pub cookie: Option<String>,
}

pub enum FetchError {
    Builder(String),
    Transport(String),
    Status(u16, String),
    FileNotFound,
    Security,
}

impl std::fmt::Display for FetchError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            FetchError::Builder(u) => write!(f, "builder error for url ({})", u),
            FetchError::Transport(u) => write!(f, "error sending request for url ({})", u),
            FetchError::Status(_, r) => write!(f, "{}", r),
            FetchError::FileNotFound => write!(f, "file not found"),
            FetchError::Security => write!(f, "security error"),
        }
    }
}

fn status_text(code: u16) -> &'static str {
    match code {
        100 => "Continue", 101 => "Switching Protocols", 200 => "OK", 201 => "Created",
        202 => "Accepted", 203 => "Non-Authoritative Information", 204 => "No Content",
        205 => "Reset Content", 206 => "Partial Content", 300 => "Multiple Choices",
        301 => "Moved Permanently", 302 => "Found", 303 => "See Other", 304 => "Not Modified",
        305 => "Use Proxy", 307 => "Temporary Redirect", 308 => "Permanent Redirect",
        400 => "Bad Request", 401 => "Unauthorized", 402 => "Payment Required",
        403 => "Forbidden", 404 => "Not Found", 405 => "Method Not Allowed",
        406 => "Not Acceptable", 407 => "Proxy Authentication Required",
        408 => "Request Timeout", 409 => "Conflict", 410 => "Gone", 411 => "Length Required",
        412 => "Precondition Failed", 413 => "Payload Too Large", 414 => "URI Too Long",
        415 => "Unsupported Media Type", 416 => "Range Not Satisfiable",
        417 => "Expectation Failed", 418 => "I'm a teapot", 421 => "Misdirected Request",
        422 => "Unprocessable Entity", 423 => "Locked", 424 => "Failed Dependency",
        426 => "Upgrade Required", 428 => "Precondition Required", 429 => "Too Many Requests",
        431 => "Request Header Fields Too Large", 451 => "Unavailable For Legal Reasons",
        500 => "Internal Server Error", 501 => "Not Implemented", 502 => "Bad Gateway",
        503 => "Service Unavailable", 504 => "Gateway Timeout", 505 => "HTTP Version Not Supported",
        _ => "Unknown Status",
    }
}

pub fn status_reason(code: u16) -> String { status_text(code).to_string() }

pub struct Request {
    pub url: url::Url,
    pub referer: Option<String>,
}

impl Client {
    pub fn get(&self, url: &url::Url, referer: Option<&str>) -> Result<Response, FetchError> {
        let mut redirects = 0;
        let mut current = url.clone();
        loop {
            match self.get_once(&current, referer) {
                Ok(resp) => {
                    if (300..400).contains(&resp.status) {
                        if let Some(loc) = resp.header("location") {
                            if redirects < 10 {
                                redirects += 1;
                                match current.join(loc) {
                                    Ok(next) => { current = next; continue }
                                    Err(_) => {}
                                }
                            }
                        }
                    }
                    if !(200..300).contains(&resp.status) {
                        return Err(FetchError::Status(resp.status, status_reason(resp.status)));
                    }
                    return Ok(resp);
                }
                Err(e) => return Err(e),
            }
        }
    }

    fn get_once(&self, url: &url::Url, referer: Option<&str>) -> Result<Response, FetchError> {
        let scheme = url.scheme();
        if scheme != "http" && scheme != "https" {
            return Err(FetchError::Builder(url.to_string()));
        }
        if scheme == "https" {
            return Err(FetchError::Transport(url.to_string()));
        }
        let host = url.host_str().unwrap_or("").to_string();
        if host.is_empty() {
            return Err(FetchError::Transport(url.to_string()));
