            .set_read_timeout(Some(Duration::from_secs(self.timeout.max(1))))
            .ok();
        stream
            .set_write_timeout(Some(Duration::from_secs(self.timeout.max(1))))
            .ok();
        let mut stream = stream;
        let mut req = String::new();
        req.push_str(&format!("GET {} HTTP/1.1\r\n", url.path_and_query()));
        if let Some(r) = referer {
            req.push_str(&format!("referer: {}\r\n", r));
        }
        req.push_str("accept: */*\r\n");
        req.push_str(&format!("user-agent: {}\r\n", self.user_agent));
        req.push_str("accept-encoding: gzip, br, deflate\r\n");
        if let Some(u) = url.host_str() {
            match url.port() {
                Some(p) => req.push_str(&format!("host: {}:{}", u, p)),
                None => req.push_str(&format!("host: {}", u)),
            }
            req.push_str("\r\n");
        }
