                Ok(0) => break,
                Ok(n) => { raw.extend_from_slice(&buf[..n]); }
                Err(e) => {
                    if raw.is_empty() {
                        return Err(FetchError::Transport(url.to_string()));
                    }
                    break;
                }
            }
            if raw.len() > 64 * 1024 * 1024 { break }
        }
        parse_response(&raw).ok_or_else(|| FetchError::Transport(url.to_string()))
    }
}

pub fn parse_response(raw: &[u8]) -> Option<Response> {
