pub fn is_multibyte(e: Enc) -> bool {
    matches!(e, Enc::Gbk | Enc::Big5 | Enc::ShiftJis | Enc::EucJp | Enc::EucKr | Enc::Utf16le | Enc::Utf16be)
}

pub fn decode(e: Enc, bytes: &[u8]) -> String {
    match e {
        Enc::Utf8 => String::from_utf8_lossy(bytes).into_owned(),
        Enc::Utf16le | Enc::Utf16be => {
            let be = e == Enc::Utf16be;
            let mut out = String::new();
            let mut i = 0;
            if bytes.len() >= 2 {
                let b0 = bytes[0];
                let b1 = bytes[1];
                if (!be && b0 == 0xff && b1 == 0xfe) || (be && b0 == 0xfe && b1 == 0xff) {
                    i = 2;
                }
            }
            while i + 1 < bytes.len() {
                let cp = if be {
                    ((bytes[i] as u32) << 8) | bytes[i + 1] as u32
                } else {
                    ((bytes[i + 1] as u32) << 8) | bytes[i] as u32
                };
                i += 2;
                out.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
            }
            out
        }
        Enc::UserDefined => bytes.iter().map(|&b| b as char).collect(),
        _ => {
            if let Some(t) = single_table(e) {
                let mut out = String::with_capacity(bytes.len());
                for &b in bytes {
                    out.push(char::from_u32(t[b as usize]).unwrap_or('\u{FFFD}'));
                }
                out
            } else if let Some(t) = dbcs_table(e) {
                let mut out = String::with_capacity(bytes.len());
                let mut i = 0;
                while i < bytes.len() {
                    let b = bytes[i];
                    if b < 0x80 {
                        out.push(b as char);
                        i += 1;
                        continue;
                    }
                    if let Some((_, row)) = t.iter().find(|(l, _)| *l == b) {
                        if i + 1 < bytes.len() {
                            let cp = row[bytes[i + 1] as usize];
                            if cp != 0 {
                                out.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                                i += 2;
                                continue;
                            }
                        }
                    }
                    out.push('\u{FFFD}');
                    i += 1;
                }
                out
            } else {
                String::from_utf8_lossy(bytes).into_owned()
            }
        }
    }
}

/// Encode a string; characters that cannot be represented become decimal entities.
pub fn encode(e: Enc, s: &str) -> Vec<u8> {
    match e {
        Enc::Utf8 => s.as_bytes().to_vec(),
        Enc::UserDefined => s.chars().map(|c| c as u8).collect(),
        _ => {
            let mut out: Vec<u8> = Vec::with_capacity(s.len());
            // build reverse map lazily
            let mut map: Vec<(u32, u8)> = Vec::new();
            let mut map2: Vec<(u32, u8)> = Vec::new();
            if let Some(t) = single_table(e) {
                for (b, &cp) in t.iter().enumerate() {
                    if cp != 0 && b >= 0x80 {
                        map.push((cp, b as u8));
                    }
                }
            }
            if let Some(t) = dbcs_table(e) {
                for (b1, row) in t.iter() {
                    for (b2, &cp) in row.iter().enumerate() {
                        if cp != 0 {
                            map2.push((cp, *b1));
                            map2.push(b2 as u8);
                        }
                    }
                }
            }
            for c in s.chars() {
                let cp = c as u32;
                if cp < 0x80 {
                    out.push(cp as u8);
                    continue;
                }
                if let Some(t) = single_table(e) {
                    let mut found = false;
                    for b in 0x80..0x100 {
                        if t[b] == cp {
                            out.push(b as u8);
                            found = true;
                            break;
                        }
                    }
                    if found {
                        continue;
                    }
                    if cp <= 0xFF && t[cp as usize] == 0 {
                        // not in table
                        out.extend_from_slice(format!("&#{};", cp).as_bytes());
                        continue;
                    }
                    if cp <= 0xFF {
                        out.push(cp as u8);
                        continue;
                    }
                    out.extend_from_slice(format!("&#{};", cp).as_bytes());
                    continue;
                }
                if let Some(t) = dbcs_table(e) {
                    let mut found = false;
                    'outer: for (b1, row) in t.iter() {
                        for (b2, &cp2) in row.iter().enumerate() {
                            if cp2 == cp {
                                out.push(*b1);
                                out.push(b2 as u8);
                                found = true;
                                break 'outer;
                            }
                        }
                    }
                    if found {
                        continue;
                    }
                }
                out.extend_from_slice(format!("&#{};", cp).as_bytes());
            }
            out
        }
    }
}

