const DEFAULT_UA: &str =
    "Mozilla/5.0 (X11; Ubuntu; Linux x86_64; rv:135.0) Gecko/20100101 Firefox/135.0";

enum Asset {
    Data(String),
    Keep(String),
    Remove,
}

struct Ctx {
    o: Opts,
    client: http::Client,
    cache: HashMap<String, Result<(String, Vec<u8>), http::FetchError>>,
    base: Option<url::Url>,
    doc: Option<url::Url>,
    err: Option<String>,
}

impl Ctx {
    fn log(&self, s: &str) {
        if !self.o.quiet {
            eprintln!("{}", s);
        }
    }

    fn allowed(&self, url: &url::Url) -> bool {
        if self.o.domains.is_empty() {
            return true;
        }
        let host = url.host_str().unwrap_or("").to_ascii_lowercase();
        let mut any = false;
        for d in &self.o.domains {
            let dd = d.trim_start_matches('.').trim_end_matches('.').to_ascii_lowercase();
            if self.o.blacklist {
                if host == dd || (d.starts_with('.') && host.ends_with(&dd) && host.len() > dd.len()) {
                    return false;
                }
            } else {
                any = true;
                if host == dd || (d.starts_with('.') && host.ends_with(&dd)) {
                    return true;
                }
            }
        }
        if self.o.blacklist {
            true
        } else {
            any
        }
    }

    fn resolve(&self, raw: &str) -> Option<url::Url> {
        let raw = raw.trim_matches(|c: char| c.is_whitespace());
        if raw.is_empty() {
            return None;
        }
        let base = self.base.clone()?;
        base.join(raw).ok()
    }

    /// Fetch an asset and return the replacement value.
    fn asset(&mut self, raw: &str) -> Asset {
        let url = match self.resolve(raw) {
            Some(u) => u,
            None => return Asset::Data("data:text/plain;base64,".to_string()),
        };
        let s = url.to_string();
        if url.scheme() == "http" || url.scheme() == "https" {
            if !self.allowed(&url) {
                return Asset::Keep(s.clone());
            }
        }
        if url.scheme() == "data" {
            if let Some(d) = data_url_pass(&s) {
                return Asset::Data(d);
            }
            return Asset::Keep(s.clone());
        }
        let is_file = url.scheme() == "file";
        if is_file && self.doc.as_ref().map_or(true, |d| d.scheme() != "file") {
            self.log(&format!("{} (security error)", s));
            return Asset::Remove;
        }
        if let Some(r) = self.cache.get(&s) {
            let r = r.clone();
            return self.finish(&s, r, true);
        }
        let res = self.fetch(&url);
        self.cache.insert(s.clone(), res.clone());
        self.finish(&s, res, false)
    }

    fn finish(&mut self, url: &str, res: Result<(String, Vec<u8>), http::FetchError>, cached: bool) -> Asset {
        match res {
            Ok((mime, data)) => Asset::Data(make_data_url(&mime, &data)),
            Err(http::FetchError::Status(code, reason)) => {
                if self.o.ignore_errors {
                    Asset::Data("data:text/plain;base64,".to_string())
                } else {
                    if !cached {
                        self.log(&format!("{} ({} {})", url, code, reason));
                    }
                    Asset::Keep(url.to_string())
                }
            }
            Err(e) => {
                if !cached {
                    self.log(&format!("{} ({})", url, e));
                }
                if self.o.ignore_errors {
                    Asset::Data("data:text/plain;base64,".to_string())
                } else {
                    Asset::Remove
                }
            }
        }
    }

    fn fetch(&mut self, url: &url::Url) -> Result<(String, Vec<u8>), http::FetchError> {
        match url.scheme() {
            "http" | "https" => {
                let referer = self.doc.as_ref().map(|d| d.to_string());
                match self.client.get(url, referer.as_deref()) {
                    Ok(resp) => {
                        let mime = resp.header("content-type").unwrap_or("text/plain").trim().to_string();
                        Ok((mime, resp.body.clone()))
                    }
                    Err(e) => Err(e),
                }
            }
            "file" => {
                let p = url.path();
                let pct = percent_decode(p);
                match std::fs::metadata(&pct) {
                    Ok(m) => {
                        if m.is_dir() {
                            Err(http::FetchError::FileNotFound)
                        } else {
                            match std::fs::read(&pct) {
                                Ok(b) => Ok((guess_mime(&pct), b)),
                                Err(_) => Err(http::FetchError::FileNotFound),
                            }
                        }
                    }
                    Err(_) => Err(http::FetchError::FileNotFound),
                }
            }
            _ => Err(http::FetchError::Builder(url.to_string())),
        }
    }
}

fn percent_decode(s: &str) -> String {
    let b = s.as_bytes();
    let mut out: Vec<u8> = Vec::new();
    let mut i = 0;
    while i < b.len() {
        if b[i] == b'%' && i + 2 < b.len() {
            let h = |c: u8| -> Option<u8> {
                match c {
                    b'0'..=b'9' => Some(c - b'0'),
                    b'a'..=b'f' => Some(c - b'a' + 10),
                    b'A'..=b'F' => Some(c - b'A' + 10),
                    _ => None,
                }
            };
            if let (Some(a), Some(x)) = (h(b[i + 1]), h(b[i + 2])) {
                out.push(a * 16 + x);
                i += 3;
                continue;
            }
        }
        out.push(b[i]);
        i += 1;
    }
    String::from_utf8_lossy(&out).into_owned()
}

fn guess_mime(path: &str) -> String {
    let ext = Path::new(path).extension().map(|e| e.to_string_lossy().to_ascii_lowercase()).unwrap_or_default();
    let m = match ext.as_str() {
        "css" => "text/css",
        "html" | "htm" => "text/html",
        "js" | "mjs" => "application/javascript",
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "svg" => "image/svg+xml",
        "ico" => "image/vnd.microsoft.icon",
        "webp" => "image/webp",
        "avif" => "image/avif",
        "bmp" => "image/bmp",
        "json" => "application/json",
        "xml" => "application/xml",
        "txt" | "text" | "log" | "" => "text/plain",
        "mp4" | "m4v" => "video/mp4",
        "webm" => "video/webm",
        "ogv" => "video/ogg",
        "mp3" => "audio/mpeg",
        "ogg" | "oga" => "audio/ogg",
        "wav" => "audio/wav",
        "woff" => "font/woff",
        "woff2" => "font/woff2",
        "ttf" => "font/ttf",
        "otf" => "font/otf",
        "eot" => "application/vnd.ms-fontobject",
        "pdf" => "application/pdf",
        "csv" => "text/csv",
        "zip" => "application/zip",
        "flac" => "audio/flac",
        "ts" => "video/mp2t",
        "mpd" => "application/dash+xml",
        "m3u8" => "application/vnd.apple.mpegurl",
        _ => "text/plain",
    };
    m.to_string()
}

fn base64_encode(data: &[u8]) -> String {
    use base64::Engine;
    base64::engine::general_purpose::STANDARD.encode(data)
}

fn base64_decode(s: &str) -> Option<Vec<u8>> {
    use base64::Engine;
    base64::engine::general_purpose::STANDARD.decode(s.trim()).ok()
}

fn make_data_url(mime: &str, data: &[u8]) -> String {
    format!("data:{};base64,{}", mime, base64_encode(data))
}

fn data_url_percent(mime: &str, data: &[u8]) -> String {
    let mut out = String::from("data:");
    out.push_str(mime);
    out.push(',');
    for &b in data {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' | b'!' | b'*'
            | b'\'' | b'(' | b')' | b';' | b'/' | b'?' | b':' | b'@' | b'&' | b'=' | b'+'
            | b'$' | b',' | b'#' => out.push(b as char),
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

fn data_url_pass(_s: &str) -> Option<String> {
    None
}

fn timestamp() -> String {
    let now = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap();
    let secs = now.as_secs() as i64;
    let days = secs.div_euclid(86400);
    let secs_of_day = secs.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z", y, m, d, secs_of_day / 3600, (secs_of_day % 3600) / 60, secs_of_day % 60)
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = (z - era * 146097) as u64;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe as i64 + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

fn main() {
    let opts = parse_args();
    let out_enc: Option<Enc> = match &opts.encoding {
        Some(e) => match charset::resolve(e) {
            Some(x) => Some(x),
            None => {
                eprintln!("Error: unknown encoding \"{}\"", e);
                std::process::exit(1);
            }
        },
        None => None,
    };

    let cookie = opts.cookie_file.as_ref().and_then(|f| read_cookies(f));
    if let Some(f) = &opts.cookie_file {
        if cookie.is_none() {
            eprintln!("could not parse specified cookie file \"{}\"", f);
            std::process::exit(1);
        }
    }

    let client = http::Client {
        timeout: opts.timeout,
        user_agent: opts.user_agent.clone().unwrap_or_else(|| DEFAULT_UA.to_string()),
        insecure: opts.insecure,
        cookie,
    };

    let mut ctx = Ctx {
        o: opts.clone(),
        client,
        cache: HashMap::new(),
        base: None,
        doc: None,
        err: None,
    };

    let target = opts.target.clone();
    // Determine the source
    enum Src {
        Stdin,
        File(std::path::PathBuf),
        Url(url::Url),
    }
    let src: Src = if target == "-" {
        Src::Stdin
    } else if let Ok(u) = url::Url::parse(&target) {
        match u.scheme() {
            "file" => Src::File(std::path::PathBuf::from(percent_decode(u.path()))),
            _ => Src::Url(u),
        }
    } else {
        let p = Path::new(&target);
        if p.exists() {
            if p.is_file() {
                Src::File(p.to_path_buf())
            } else {
                eprintln!("Error: local target \"{}\" is not a file", target);
                std::process::exit(1);
            }
        } else {
            match url::Url::parse(&format!("http://{}", target)) {
                Ok(u) => Src::Url(u),
                Err(_) => {
                    eprintln!("Error: could not retrieve target document");
                    std::process::exit(1);
                }
            }
        }
    };

    let (body, mime, doc_url): (Vec<u8>, String, Option<url::Url>) = match src {
        Src::Stdin => {
            use std::io::Read;
            let mut b = Vec::new();
            let _ = std::io::stdin().read_to_end(&mut b);
            (b, String::new(), None)
        }
        Src::File(p) => {
            let abs = std::fs::canonicalize(&p).ok();
            let u = abs.and_then(|a| url::Url::from_file_path(&a).ok());
            match std::fs::read(&p) {
                Ok(b) => {
                    if !opts.quiet {
                        eprintln!("{}", u.as_ref().map(|x| x.to_string()).unwrap_or_default());
                    }
                    (b, String::new(), u)
                }
                Err(_) => {
                    let msg = if p.is_dir() { "is a directory" } else { "file not found" };
                    if !opts.quiet {
                        eprintln!("{} ({})", u.as_ref().map(|x| x.to_string()).unwrap_or_default(), msg);
                    }
                    eprintln!("Error: could not retrieve target document");
                    std::process::exit(1);
                }
            }
        }
        Src::Url(u) => {
            if !opts.quiet {
                eprintln!("{}", u);
            }
            match u.scheme() {
                "http" | "https" => {
                    if !ctx.allowed(&u) {
                        eprintln!("Error: could not retrieve target document");
                        std::process::exit(1);
                    }
                    match ctx.client.get(&u, None) {
                        Ok(resp) => {
                            let m = resp.header("content-type").unwrap_or("").trim().to_string();
                            (resp.body.clone(), m, Some(resp_final(&u, &resp)))
                        }
                        Err(e) => {
                            if !opts.quiet {
                                eprintln!("{} ({})", u, e);
                            }
                            eprintln!("Error: could not retrieve target document");
                            std::process::exit(1);
                        }
                    }
                }
                "data" => match parse_data_url(&u.to_string()) {
                    Some((m, b)) => (b, m, Some(u)),
                    None => {
                        eprintln!("Error: could not retrieve target document");
                        std::process::exit(1);
                    }
                },
                s => {
                    eprintln!("Error: unsupported target URL scheme \"{}\"", s);
                    std::process::exit(1);
                }
            }
        }
    };

    let is_html = mime_is_html(&mime);
    if !is_html {
        write_output(&opts, &body, out_enc.is_some(), &[]);
        return;
    }

    ctx.doc = doc_url.clone();
    ctx.base = doc_url.clone().or_else(|| opts.base_url.as_ref().and_then(|b| url::Url::parse(b).ok()));

    // charset detection
    let dec_enc = detect_charset(&body, &mime);
    let text = charset::decode(dec_enc, &body);
    let _ = &text;
    // parse
    let mut t = tree::Tree::new();
    parse_into_tree(&text, &mut t);
    // process
    let children = t.children_of(0).to_vec();
    for c in children {
        process_element(&mut ctx, &mut t, c, 0);
    }
    // head manipulation
    finish_document(&mut ctx, &mut t);
    let mut out = serialize::serialize(&t);
    if !opts.no_metadata {
        let url_repr = match &doc_url {
            Some(u) if u.scheme() == "http" || u.scheme() == "https" => u.to_string(),
            _ => "local source".to_string(),
        };
        if let Some(_u) = &doc_url {
            out = format!("<!-- Saved from {} at {} using monolith v{} -->\n{}", url_repr, timestamp(), "2.11.0", out);
        }
    }
    let enc = out_enc.unwrap_or(dec_enc);
    let bytes = charset::encode(enc, &out);
    write_output(&opts, &bytes, true, &[]);
    let _ = &ctx.err;
}

fn resp_final(u: &url::Url, _r: &http::Response) -> url::Url {
    u.clone()
}

fn mime_is_html(m: &str) -> bool {
    let mt = m.split(';').next().unwrap_or("").trim().to_ascii_lowercase();
    mt == "text/html" || mt == "application/xhtml+xml" || mt == "text/xml" || mt == "application/xml"
}

fn parse_data_url(s: &str) -> Option<(String, Vec<u8>)> {
    let rest = s.strip_prefix("data:")?;
    let comma = rest.find(',')?;
    let meta = &rest[..comma];
    let data = &rest[comma + 1..];
    let mut parts = meta.split(';');
    let mime = parts.next().unwrap_or("").to_string();
    let mut is_b64 = false;
    let mut charset: Option<String> = None;
    for p in parts {
        if p.eq_ignore_ascii_case("base64") {
            is_b64 = true;
        } else if let Some(c) = p.strip_prefix("charset=") {
            charset = Some(c.to_string());
        }
    }
    let bytes: Vec<u8> = if is_b64 {
        base64_decode(data)?
    } else {
        percent_decode(data).into_bytes()
    };
    let _ = charset;
    Some((mime, bytes))
}

fn read_cookies(path: &str) -> Option<String> {
    let data = std::fs::read(path).ok()?;
    let text = String::from_utf8_lossy(&data).to_string();
    let mut lines = text.lines();
    let first = lines.next()?;
    if first.trim() != "# Netscape HTTP Cookie File" {
        return None;
    }
    let mut cookies: Vec<(String, String, String)> = Vec::new();
    for line in lines {
        let line = line.trim_end_matches('\r');
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let f: Vec<&str> = line.split('\t').collect();
        if f.len() != 7 {
            return None;
        }
        if f[1] != "FALSE" || f[3] != "FALSE" {
            return None;
        }
        let _expiry: i64 = f[4].parse().ok()?;
        cookies.push((f[0].to_string(), f[2].to_string(), format!("{}={}", f[5], f[6])));
    }
    Some(String::from_utf8(cookies.iter().map(|c| c.2.clone().into_bytes()).flatten().collect()).unwrap_or_default())
}

fn detect_charset(body: &[u8], mime: &str) -> Enc {
    // meta charset in the first 1024 bytes
    let head = &body[..body.len().min(4096)];
    if let Some(e) = find_meta_charset(head) {
        if let Some(x) = charset::resolve(&e) {
            return x;
        }
    }
    if let Some(ct) = mime.split(';').find(|p| p.trim().to_ascii_lowercase().starts_with("charset=")) {
        let v = ct.split('=').nth(1).unwrap_or("").trim().trim_matches('"').to_string();
        if let Some(x) = charset::resolve(&v) {
            return x;
        }
    }
    if !mime.is_empty() {
        return Enc::Win1252;
    }
    if std::str::from_utf8(body).is_ok() {
        Enc::Utf8
    } else {
        Enc::Win1252
    }
}

fn find_meta_charset(body: &[u8]) -> Option<String> {
    let text = String::from_utf8_lossy(&body[..body.len().min(2048)]).to_ascii_lowercase();
    for pat in ["<meta charset=\"", "<meta charset='", "<meta charset="] {
        if let Some(i) = text.find(pat) {
            let rest = &text[i + pat.len()..];
            let end = rest.find(|c: char| c == '"' || c == '\'' || c == '>').unwrap_or(rest.len());
            let v = rest[..end].trim().to_string();
            if !v.is_empty() {
                return Some(v);
            }
        }
    }
    if let Some(i) = text.find("http-equiv=\"content-type\"") {
        if let Some(j) = text[i..].find("charset=") {
            let rest = &text[i + j + 8..];
            let end = rest.find(|c: char| c == '"' || c == '\'' || c == ';' || c == '>').unwrap_or(rest.len());
            let v = rest[..end].trim().trim_matches('"').to_string();
            if !v.is_empty() {
                return Some(v);
            }
        }
    }
    None
}

fn write_output(opts: &Opts, bytes: &[u8], _enc: bool, _extra: &[u8]) {
    match &opts.output {
        Some(p) if p != "-" => {
            if let Ok(mut f) = std::fs::File::create(p) {
                let _ = f.write_all(bytes);
            } else {
                panic!("could not prepare output");
            }
        }
        _ => {
            let stdout = std::io::stdout();
            let mut lock = stdout.lock();
            let _ = lock.write_all(bytes);
            if opts.mhtml {
                let _ = lock.flush();
            }
        }
    }
}

fn parse_into_tree(text: &str, t: &mut tree::Tree) {
    // normalise newlines
    let mut norm: Vec<u8> = Vec::with_capacity(text.len());
    let b = text.as_bytes();
    let mut i = 0;
    while i < b.len() {
        if b[i] == 0x0d {
            norm.push(0x0a);
            if i + 1 < b.len() && b[i + 1] == 0x0a {
                i += 1;
            }
        } else {
            norm.push(b[i]);
        }
        i += 1;
    }
    let mut tok = tokenizer::Tokenizer::new(norm);
    let mut pending_text: Option<Vec<u8>> = None;
    loop {
        let token = tok.next_token();
        let is_eof = matches!(token, tokenizer::Token::Eof);
        if let Some(pt) = pending_text.take() {
            let _ = pt;
        }
        // handle raw text hints set by the tree builder
        if let Some(h) = t.rcdata_hint.take() {
            set_tok_state(&mut tok, h, t.script_hint, t.plaintext_hint);
            t.script_hint = false;
            t.plaintext_hint = false;
        }
        // drop the first newline after pre/textarea
        let token = if t.skip_next_newline {
            match &token {
                tokenizer::Token::Character(s) => {
                    t.skip_next_newline = false;
                    if s.first() == Some(&0x0a) {
                        if s.len() > 1 {
                            tokenizer::Token::Character(s[1..].to_vec())
                        } else {
                            continue;
                        }
                    } else {
                        token.clone()
                    }
                }
                _ => token.clone(),
            }
        } else {
            token.clone()
        };
        t.process(token);
        if is_eof || tok.eof {
            break;
        }
    }
}

fn set_tok_state(tok: &mut tokenizer::Tokenizer, rcdata: bool, script: bool, plaintext: bool) {
    use tokenizer::State;
    tok.state = if plaintext {
        State::Plaintext
    } else if script {
        State::ScriptData
    } else if rcdata {
        State::Rcdata
    } else {
        State::Rawtext
    };
}

fn get_attr(attrs: &[(String, String)], name: &str) -> Option<String> {
    attrs.iter().find(|(k, _)| k == name).map(|(_, v)| v.clone())
}

fn process_element(ctx: &mut Ctx, t: &mut tree::Tree, idx: usize, depth: usize) {
    if depth > 60 {
        return;
    }
    let name = t.el_name(idx);
    let ns = t.el_ns(idx);
    let mut attrs = t.attrs(idx).clone();
    let mut new_attrs: Option<Vec<(String, String)>> = None;
    let mut remove_attr: Option<String> = None;

    // base element
    if name == "base" {
        if let Some(href) = get_attr(&attrs, "href") {
            let resolved: Option<url::Url> = if let Some(b) = ctx.o.base_url.clone() {
                url::Url::parse(&b).ok()
            } else {
                ctx.base.clone().and_then(|b| b.join(&href).ok())
            };
            if let Some(u) = resolved {
                ctx.base = Some(u.clone());
                set_attr_in(&mut attrs, "href", &u.to_string());
                new_attrs = Some(attrs.clone());
            }
        }
    }

    // element specific handling
    match (name.as_str(), ns) {
        ("noscript", tree::Ns::Html) if ctx.o.unwrap_noscript => {
            unwrap_noscript(ctx, t, idx);
            return;
        }
        _ => {}
    }

    if name == "img" && ns == tree::Ns::Html {
        let url_raw = get_attr(&attrs, "data-src")
            .or_else(|| get_attr(&attrs, "src"))
            .unwrap_or_default();
        let val = if ctx.o.no_images {
            Asset::Data(data_url_percent("image/png", &blank::BLANK_PNG))
        } else if url_raw.is_empty() {
            Asset::Keep(String::new())
        } else {
            ctx.asset(&url_raw)
        };
        apply_asset(ctx, t, idx, &mut attrs, &mut new_attrs, &mut remove_attr, "src", val);
    } else if (name == "video" || name == "audio") && ns == tree::Ns::Html {
        for a in ["src", "poster"] {
            if let Some(v) = get_attr(&attrs, a) {
                if v.is_empty() {
                    continue;
                }
                if name == "audio" && a == "poster" {
                    continue;
                }
                if name == "video" && a == "src" && ctx.o.no_video {
                    remove_attr = Some("src".to_string());
                    continue;
                }
                if name == "audio" && a == "src" && ctx.o.no_audio {
                    remove_attr = Some("src".to_string());
                    continue;
                }
                let val = ctx.asset(&v);
                apply_asset(ctx, t, idx, &mut attrs, &mut new_attrs, &mut remove_attr, a, val);
            } else if a == "src" && (name == "video" && ctx.o.no_video) {
                remove_attr = Some("src".to_string());
            }
        }
    } else if name == "source" && ns == tree::Ns::Html {
        let parent_is_picture = t.parent_is(idx, "picture");
        if parent_is_picture {
            if let Some(v) = get_attr(&attrs, "srcset") {
                let val = srcset_process(ctx, &v);
                set_attr_in(&mut attrs, "srcset", &val);
                new_attrs = Some(attrs.clone());
            }
        } else if let Some(v) = get_attr(&attrs, "src") {
            if !v.is_empty() {
                let val = ctx.asset(&v);
                apply_asset(ctx, t, idx, &mut attrs, &mut new_attrs, &mut remove_attr, "src", val);
            }
        }
    } else if name == "iframe" && ns == tree::Ns::Html {
        if ctx.o.no_frames {
            remove_attr = Some("src".to_string());
        } else if let Some(v) = get_attr(&attrs, "src") {
            if !v.is_empty() {
                let val = iframe_process(ctx, &v, depth);
                apply_asset(ctx, t, idx, &mut attrs, &mut new_attrs, &mut remove_attr, "src", val);
            }
        }
    } else if name == "link" && ns == tree::Ns::Html {
        let rel = get_attr(&attrs, "rel").unwrap_or_default();
        let toks: Vec<String> = rel.to_ascii_lowercase().split_whitespace().map(|s| s.to_string()).collect();
        if toks.iter().any(|s| s == "preload" || s == "dns-prefetch") {
            remove_attr = Some("rel".to_string());
        } else if toks.iter().any(|s| s == "stylesheet") {
            if let Some(v) = get_attr(&attrs, "href") {
                if !v.is_empty() {
                    let val = css_link_process(ctx, &v);
                    apply_asset(ctx, t, idx, &mut attrs, &mut new_attrs, &mut remove_attr, "href", val);
                }
            }
        } else if toks.iter().any(|s| s == "icon" || s == "apple-touch-icon") {
            if let Some(v) = get_attr(&attrs, "href") {
                if !v.is_empty() {
                    let val = ctx.asset(&v);
                    apply_asset(ctx, t, idx, &mut attrs, &mut new_attrs, &mut remove_attr, "href", val);
                }
            }
        } else {
            if let Some(v) = get_attr(&attrs, "href") {
                if !v.is_empty() {
                    if let Some(u) = ctx.resolve(&v) {
                        set_attr_in(&mut attrs, "href", &u.to_string());
                        new_attrs = Some(attrs.clone());
                    }
                }
            }
        }
    } else if name == "script" && ns == tree::Ns::Html {
        if ctx.o.no_js {
            remove_attr = Some("src".to_string());
            t.set_text(idx, "");
        } else if let Some(v) = get_attr(&attrs, "src") {
            if !v.is_empty() {
                let ty = get_attr(&attrs, "type").unwrap_or_default();
                let inline = ty.is_empty() || ty == "text/javascript" || ty == "application/javascript";
                let val = if inline {
                    match ctx.asset(&v) {
                        Asset::Data(d) => {
                            if let Some((_m, b)) = data_url_decode(&d) {
                                t.set_text(idx, &script_text(&String::from_utf8_lossy(&b)));
                                Asset::Keep("__inline__".to_string())
                            } else {
                                Asset::Data(d)
                            }
                        }
                        other => other,
                    }
                } else {
                    ctx.asset(&v)
                };
                if let Asset::Keep(k) = &val {
                    if k == "__inline__" {
                        remove_attr = Some("src".to_string());
                    }
                }
                if !matches!(val, Asset::Keep(ref k) if k == "__inline__") {
                    apply_asset(ctx, t, idx, &mut attrs, &mut new_attrs, &mut remove_attr, "src", val);
                }
            }
        }
    } else if name == "style" && ns == tree::Ns::Html {
        if ctx.o.no_css {
            t.set_text(idx, "");
        } else if let Some(text) = t.el_text(idx) {
            let nt = process_css(ctx, &text);
            t.set_text(idx, &nt);
        }
    } else if name == "svg" || ns == tree::Ns::Svg || ns == tree::Ns::MathMl {
        if name == "image" || name == "use" {
            let url_raw = get_attr(&attrs, "xlink:href").or_else(|| get_attr(&attrs, "href"));
            if let Some(v) = url_raw {
                if !v.is_empty() {
                    let val = ctx.asset(&v);
                    set_attr_in(&mut attrs, "xlink:href", "");
                    set_attr_in(&mut attrs, "href", "");
                    let mut a2 = attrs.clone();
                    match val {
                        Asset::Data(d) => {
                            set_attr_in(&mut a2, "xlink:href", &d);
                            set_attr_in(&mut a2, "href", &d);
                        }
                        Asset::Keep(u) => {
                            set_attr_in(&mut a2, "xlink:href", &u);
                            set_attr_in(&mut a2, "href", &u);
                        }
                        Asset::Remove => {
                            remove_attr = Some("xlink:href".to_string());
                        }
                    }
                    attrs = a2;
                    new_attrs = Some(attrs.clone());
                }
            }
        }
    } else if (name == "a" || name == "form") && ns == tree::Ns::Html {
        let an = if name == "a" { "href" } else { "action" };
        if let Some(v) = get_attr(&attrs, an) {
            if !v.is_empty() && !v.starts_with('#') {
                if let Some(u) = ctx.resolve(&v) {
                    set_attr_in(&mut attrs, an, &u.to_string());
                    new_attrs = Some(attrs.clone());
                }
            }
        }
    }

    if let Some(na) = new_attrs {
        t.set_attrs(idx, na);
    }
    if let Some(r) = remove_attr {
        t.remove_attr(idx, &r);
    }

    // children
    if let Some(kids) = t.children(idx) {
        for c in kids {
            process_element(ctx, t, c, depth + 1);
        }
    }
}

fn apply_asset(
    _ctx: &mut Ctx,
    t: &mut tree::Tree,
    idx: usize,
    attrs: &mut Vec<(String, String)>,
    new_attrs: &mut Option<Vec<(String, String)>>,
    remove_attr: &mut Option<String>,
    attr: &str,
    val: Asset,
) {
    match val {
        Asset::Data(d) => {
            set_attr_in(attrs, attr, &d);
            *new_attrs = Some(attrs.clone());
        }
        Asset::Keep(u) => {
            if u.is_empty() {
                if t.has_attr(idx, attr) {
                    *remove_attr = Some(attr.to_string());
                } else {
                    set_attr_in(attrs, attr, "");
                    *new_attrs = Some(attrs.clone());
                }
            } else {
                set_attr_in(attrs, attr, &u);
                *new_attrs = Some(attrs.clone());
            }
        }
        Asset::Remove => {
            *remove_attr = Some(attr.to_string());
        }
    }
}

fn set_attr_in(attrs: &mut Vec<(String, String)>, name: &str, value: &str) {
    if let Some(p) = attrs.iter().position(|(k, _)| k == name) {
        attrs[p].1 = value.to_string();
    } else {
        attrs.push((name.to_string(), value.to_string()));
    }
}

fn srcset_process(ctx: &mut Ctx, v: &str) -> String {
    let mut out: Vec<String> = Vec::new();
    for part in v.split(',') {
        let trimmed = part.trim();
        if trimmed.is_empty() {
            out.push(part.to_string());
            continue;
        }
        let mut it = trimmed.splitn(2, char::is_whitespace);
        let url = it.next().unwrap_or("");
        let desc = it.next().unwrap_or("").to_string();
        let val = ctx.asset(url);
        let nu = match val {
            Asset::Data(d) => d,
            Asset::Keep(u) => u,
            Asset::Remove => url.to_string(),
        };
        if desc.is_empty() {
            out.push(nu);
        } else {
            out.push(format!("{} {}", nu, desc));
        }
    }
    out.join(",")
}

fn css_link_process(ctx: &mut Ctx, v: &str) -> Asset {
    match ctx.asset(v) {
        Asset::Data(d) => {
            if let Some((mime, body)) = data_url_decode(&d) {
                let text = String::from_utf8_lossy(&body).to_string();
                let nt = process_css(ctx, &text);
                Asset::Data(make_data_url(&mime, nt.as_bytes()))
            } else {
                Asset::Data(d)
            }
        }
        other => other,
    }
}

fn iframe_process(ctx: &mut Ctx, v: &str, depth: usize) -> Asset {
    match ctx.asset(v) {
        Asset::Data(d) => {
            if let Some((mime, body)) = data_url_decode(&d) {
                if mime_is_html(&mime) {
                    let sub_enc = detect_charset(&body, &mime);
                    let text = charset::decode(sub_enc, &body);
                    let mut st = tree::Tree::new();
                    parse_into_tree(&text, &mut st);
                    let saved_base = ctx.base.clone();
                    ctx.base = ctx.resolve(v);
                    let kids = st.children_of(0).to_vec();
                    for c in kids {
                        process_element(ctx, &mut st, c, depth + 1);
                    }
                    ctx.base = saved_base;
                    let s = serialize::serialize(&st);
                    Asset::Data(make_data_url(&mime, s.as_bytes()))
                } else {
                    Asset::Data(d)
                }
            } else {
                Asset::Data(d)
            }
        }
        other => other,
    }
}

fn unwrap_noscript(_ctx: &mut Ctx, t: &mut tree::Tree, idx: usize) {
    t.unwrap_noscript(idx);
}

fn data_url_decode(d: &str) -> Option<(String, Vec<u8>)> {
    if !d.starts_with("data:") {
        return None;
    }
    parse_data_url(d)
}

fn script_text(s: &str) -> String {
    s.replace("</script>", "<\\/script>")
}

fn process_css(ctx: &mut Ctx, text: &str) -> String {
    css::process(ctx, text)
}

fn finish_document(ctx: &mut Ctx, t: &mut tree::Tree) {
    let head = t.find_head();
    if head.is_none() {
        return;
    }
    let head = head.unwrap();
    let csp = build_csp(&ctx.o);
    if !csp.is_empty() {
        let el = t.create_element("meta");
        t.set_attrs(el, vec![
            ("http-equiv".to_string(), "Content-Security-Policy".to_string()),
            ("content".to_string(), csp),
        ]);
        t.prepend_child(head, el);
    }
    if let Some(b) = &ctx.o.base_url {
        if t.find_base().is_none() {
            if let Some(u) = url::Url::parse(b).ok() {
                let el = t.create_element("base");
                t.set_attrs(el, vec![("href".to_string(), u.to_string())]);
                t.append_child(head, el);
            }
        }
    }
    // favicon
    let is_http = ctx.doc.as_ref().map_or(false, |d| d.scheme() == "http" || d.scheme() == "https");
    if is_http && !ctx.o.no_images && !t.has_icon_link() {
        if let Some(base) = ctx.base.clone() {
            let fav = format!("{}/favicon.ico", base.origin().ascii_serialization());
            if let Some(u) = url::Url::parse(&fav).ok() {
                if ctx.allowed(&u) {
                    let r = ctx.asset(&fav);
                    if let Asset::Data(d) = r {
                        let mime = d
                            .strip_prefix("data:")
                            .and_then(|s| s.split(';').next())
                            .unwrap_or("text/plain")
                            .to_string();
                        let el = t.create_element("link");
                        t.set_attrs(el, vec![
                            ("rel".to_string(), "icon".to_string()),
                            ("href".to_string(), d),
                        ]);
                        t.append_child(head, el);
                        let _ = mime;
                    }
                }
            }
        }
    }
    let el = t.create_element("meta");
    t.set_attrs(el, vec![("name".to_string(), "robots".to_string()), ("content".to_string(), "none".to_string())]);
    t.append_child(head, el);
    if let Some(e) = &ctx.o.encoding {
        if let Some(existing) = t.find_meta_charset_el() {
            t.set_attr(existing, "charset", e);
        } else {
            let el = t.create_element("meta");
            t.set_attrs(el, vec![("charset".to_string(), e.clone())]);
            t.append_child(head, el);
        }
    }
    let _ = ctx;
}

fn build_csp(o: &Opts) -> String {
    let mut parts: Vec<String> = Vec::new();
    if o.isolate {
        parts.push("default-src 'unsafe-eval' 'unsafe-inline' data:;".to_string());
    }
    if o.no_css {
        parts.push("style-src 'none';".to_string());
    }
    if o.no_fonts {
        parts.push("font-src 'none';".to_string());
    }
    if o.no_frames {
        parts.push("frame-src 'none';".to_string());
        parts.push("child-src 'none';".to_string());
    }
    if o.no_js || o.mhtml {
        parts.push("script-src 'none';".to_string());
    }
    if o.no_images {
        parts.push("img-src data:;".to_string());
    }
    parts.join(" ")
}
