// ------------------------------------------------------------------ public API
impl Tree {
    pub fn el_name(&self, n: usize) -> String { self.name_of(n) }
    pub fn el_ns(&self, n: usize) -> Ns { self.ns_of(n) }
    pub fn attrs(&self, n: usize) -> &[(String, String)] {
        match &self.nodes[n] {
            Node::Element { attrs, .. } => attrs,
            _ => &[],
        }
    }
    pub fn children_of(&self, n: usize) -> Vec<usize> {
        match &self.nodes[n] {
            Node::Element { children, .. } => children.clone(),
            _ => Vec::new(),
        }
    }
    pub fn children(&self, n: usize) -> Option<Vec<usize>> {
        Some(self.children_of(n))
    }
    pub fn set_attrs(&mut self, n: usize, a: Vec<(String, String)>) {
        if let Node::Element { attrs, .. } = &mut self.nodes[n] {
            *attrs = a;
        }
    }
    pub fn set_attr(&mut self, n: usize, name: &str, value: &str) {
        if let Node::Element { attrs, .. } = &mut self.nodes[n] {
            match attrs.iter().position(|(k, _)| k == name) {
                Some(p) => attrs[p].1 = value.to_string(),
                None => attrs.push((name.to_string(), value.to_string())),
            }
        }
    }
    pub fn remove_attr(&mut self, n: usize, name: &str) {
        if let Node::Element { attrs, .. } = &mut self.nodes[n] {
            attrs.retain(|(k, _)| k != name);
        }
    }
    pub fn has_attr(&self, n: usize, name: &str) -> bool {
