            }
            Tok::AtKeyword(v) => {
                out.push(b'@');
                out.extend_from_slice(&v);
                at_import = v == b"import";
            }
            Tok::Function(v) => {
                out.extend_from_slice(&v);
                out.push(b'(');
                in_url_fn = v == b"url";
                at_import = false;
            }
            Tok::Hash(v) => {
                out.push(b'#');
                out.extend_from_slice(&v);
                at_import = false;
            }
            Tok::Str(v) => {
                if at_import || in_url_fn {
                    let s = String::from_utf8_lossy(&v).to_string();
                    if s.trim().is_empty() {
                        // empty url: drop
                    } else {
                        let nv = rewrite_url(ctx, &s);
                        serialize_string_value(&mut out, nv.as_bytes());
                    }
                } else {
                    serialize_string_value(&mut out, &v);
                }
                at_import = false;
            }
            Tok::BadStr => {}
            Tok::Url(v) => {
                let s = String::from_utf8_lossy(&v).to_string();
                if s.trim().is_empty() {
                    out.extend_from_slice(b"url()");
                } else {
                    let nv = rewrite_url(ctx, &s);
                    out.extend_from_slice(b"url(\"");
                    out.extend_from_slice(nv.as_bytes());
                    out.push(b'"');
                    out.push(b')');
                }
                at_import = false;
            }
            Tok::BadUrl => {}
            Tok::Delim(c) => {
                out.push(c);
                if c == b'{' { depth += 1 }
                if c == b'}' { depth -= 1 }
                at_import = false;
            }
            Tok::Num { value, has_sign } => {
                serialize_num(&mut out, value, has_sign);
                at_import = false;
            }
            Tok::Percent { value, has_sign } => {
                serialize_num(&mut out, value, has_sign);
                out.push(b'%');
                at_import = false;
            }
            Tok::Dim { value, unit, has_sign } => {
                serialize_num(&mut out, value, has_sign);
                out.extend_from_slice(&unit);
                at_import = false;
            }
            Tok::Colon => { out.push(b':'); at_import = false }
            Tok::Semicolon => { out.push(b';'); at_import = false }
            Tok::Comma => { out.push(b','); at_import = false }
            Tok::OpenParen => { out.push(b'('); at_import = false }
            Tok::CloseParen => { out.push(b')'); in_url_fn = false; at_import = false }
            Tok::OpenBracket => { out.push(b'['); at_import = false }
            Tok::CloseBracket => { out.push(b']'); at_import = false }
            Tok::IncludeMatch => out.extend_from_slice(b"~="),
            Tok::DashMatch => out.extend_from_slice(b"|="),
            Tok::PrefixMatch => out.extend_from_slice(b"^="),
            Tok::SuffixMatch => out.extend_from_slice(b"$="),
            Tok::SubstringMatch => out.extend_from_slice(b"*="),
            Tok::Column => out.extend_from_slice(b"||"),
            Tok::Cdo => out.extend_from_slice(b"<!--"),
            Tok::Cdc => out.extend_from_slice(b"-->"),
        }
    }
    if depth > 0 {
        for _ in 0..depth {
            out.push(b'}');
        }
    }
    String::from_utf8_lossy(&out).into_owned()
}

fn rewrite_url(ctx: &mut crate::Ctx, url: &str) -> String {
    match ctx.asset(url) {
        crate::Asset::Data(d) => d,
        crate::Asset::Keep(u) => u,
        crate::Asset::Remove => String::new(),
    }
}
