new = '''    fn table_start(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match self.mode() {
            Mode::InTableBody => self.in_table_body_start(name, a, sc),
            Mode::InRow => self.in_row_start(name, a, sc),
            Mode::InCell => self.in_cell_start(name, a, sc),
            Mode::InCaption => self.in_caption_start(name, a, sc),
            Mode::InColumnGroup => self.in_column_group_start(name, a, sc),
            _ => self.in_table_start(name, a, sc),
        }
    }

    fn in_table_start(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match name {
            "caption" | "col" | "colgroup" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr" => {
                self.clear_stack(&["table", "template", "html"]);
                self.set_mode(Mode::InTableBody);
                self.start_tag(name, a, sc);
            }
            "style" | "script" | "template" => self.in_head_start(name, a, sc),
            "input" => {
                let hidden = a.iter().any(|(k, v)| k == "type" && v.eq_ignore_ascii_case("hidden"));
                if hidden {
                    let _ = self.insert_element("input", Ns::Html, a);
                    self.pop_one();
                } else {
                    self.in_body_start(name, a, sc);
                }
            }
            "form" => {
                if self.find_in_open("template") {
                    let _ = self.insert_element("form", Ns::Html, a);
                    self.pop_one();
                } else {
                    self.in_body_start(name, a, sc);
                }
            }
            "table" => {
                self.clear_stack(&["table", "template", "html"]);
                self.set_mode(Mode::InTable);
                self.in_body_start(name, a, sc);
            }
            _ => self.in_body_start(name, a, sc),
        }
    }

    fn in_table_body_start(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match name {
            "tr" => {
                self.clear_stack(&["tbody", "tfoot", "thead", "template", "html"]);
                self.set_mode(Mode::InRow);
                self.start_tag(name, a, sc);
            }
            "th" | "td" => {
                self.clear_stack(&["tbody", "tfoot", "thead", "template", "html"]);
                self.set_mode(Mode::InRow);
                let _ = self.push_el("tr", Ns::Html, Vec::new(), Mode::InRow);
                self.start_tag(name, a, sc);
            }
            "caption" | "col" | "colgroup" | "tbody" | "tfoot" | "thead" => {
                self.clear_stack(&["tbody", "tfoot", "thead", "template", "html"]);
                self.pop_one();
                self.set_mode(Mode::InTable);
                self.start_tag(name, a, sc);
            }
            _ => self.in_table_start(name, a, sc),
        }
    }

    fn in_row_start(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match name {
            "th" | "td" => {
                self.clear_stack(&["tr", "template", "html"]);
                self.set_mode(Mode::InCell);
                self.start_tag(name, a, sc);
            }
            "caption" | "col" | "colgroup" | "tbody" | "tfoot" | "thead" | "tr" => {
                self.clear_stack(&["tr", "template", "html"]);
                self.pop_one();
                self.set_mode(Mode::InTableBody);
                self.start_tag(name, a, sc);
            }
            _ => self.in_table_start(name, a, sc),
        }
    }

    fn in_cell_start(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match name {
            "caption" | "col" | "colgroup" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr" => {
                if self.in_table_scope("td") || self.in_table_scope("th") {
                    self.generate_implied_end_tags(&[]);
                    self.pop_until(&["td", "th"]);
                    self.set_mode(Mode::InRow);
                    self.start_tag(name, a, sc);
                }
            }
            _ => self.in_body_start(name, a, sc),
        }
    }

    fn in_caption_start(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match name {
            "caption" | "col" | "colgroup" | "tbody" | "td" | "tfoot" | "th" | "thead" | "tr" => {
                if self.in_table_scope("caption") {
                    self.generate_implied_end_tags(&[]);
                    self.pop_until(&["caption"]);
                    self.set_mode(Mode::InTable);
                    self.start_tag(name, a, sc);
                }
            }
            _ => self.in_body_start(name, a, sc),
        }
    }

    fn in_column_group_start(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        match name {
            "html" => { self.pop_one(); self.start_tag(name, a, sc) }
            "col" => { let _ = self.insert_element("col", Ns::Html, a); self.pop_one(); }
            "template" => self.in_head_start(name, a, sc),
            "colgroup" => {
                if !self.has_cur("colgroup") {
                    self.pop_one();
                    self.set_mode(Mode::InTable);
                    self.start_tag(name, a, sc);
                } else {
                    let _ = self.insert_element("colgroup", Ns::Html, a);
                    self.pop_one();
                }
            }
            _ => {
                if self.has_cur("colgroup") {
                    self.pop_one();
                    self.set_mode(Mode::InTable);
                    self.start_tag(name, a, sc);
                }
            }
        }
    }

    fn foster_start(&mut self, name: &str, a: Vec<(String, String)>, sc: bool) {
        self.in_body_start(name, a, sc);
        let _ = sc;
    }

