{"command": "cd /workspace && python3 - <<'PY'
p='src/tree.rs'; s=open(p).read()
old = s[s.index("    fn insert_node(&mut self, node: usize) {"):s.index("    fn foster_parent(&mut self, node: usize) {")]
new = '''    fn insert_node(&mut self, node: usize) {
        let target = self.cur();
        let tn = self.name_of(target);
        let tns = self.ns_of(target);
        if tns == Ns::Html
            && matches!(tn.as_str(), "table" | "tbody" | "tfoot" | "thead" | "tr")
            && !self.foster_parenting
        {
            let ok = match &self.nodes[node] {
                Node::Element { name, ns, .. } => {
                    *ns != Ns::Html
                        || matches!(name.as_str(), "table" | "caption" | "colgroup" | "col"
                            | "tbody" | "tfoot" | "thead" | "tr" | "td" | "th" | "template"
                            | "script" | "style" | "noscript" | "input" | "form")
                }
                Node::Comment(_) => false,
                Node::Text(_) => false,
                _ => true,
            };
            if !ok {
                self.foster_parent(node);
                return;
            }
        }
        self.append_to(target, node);
    }

'''
s = s.replace(old, new)
open(p,'w').write(s)
print("ok")
